  function isEntryFlowDone(){
    if (COOKIE.get('kareta_onb_done') === '1') return true;
    try{
      if (localStorage.getItem(STORAGE.entryDoneKey) === '1') return true;
      // ONBOARDING-STABILITY: support the r15 completion flag as well.
      if (localStorage.getItem('kareta_onboarding_done_v1') === '1') return true;
      if (localStorage.getItem('kareta_onboarding_completed_at')) return true;
    }catch(_e){ return false; }
    return false;
  }
  function getPendingEntryFlow(){
    const flow = getEntryFlow();
    if (!flow || flow.pending !== true) return null;
    return {
      role: normalizeEntryRole(flow.role || flow.entryRole || 'client'),
      entryRole: normalizeEntryRole(flow.entryRole || flow.role || 'client'),
      city: String(flow.city || '').trim(),
      countryCode: String(flow.countryCode || flow.country_code || 'KZ').trim() || 'KZ',
      stage: String(flow.stage || flow.onboardingStage || '').trim()
    };
  }
  function rememberEntryRole(roleValue){
    const r = normalizeEntryRole(roleValue || 'client');
    COOKIE.set('kareta_role', r, 365);
    try{ localStorage.setItem(STORAGE.roleMemoryKey, r); }catch(_e){}
    return r;
  }
  function getRememberedRole(){
    // Pending entry-flow > Cookie > localStorage fallback.
    // Если роль уже выбрана, не возвращаем пользователя на первый экран выбора роли.
    const pending = getPendingEntryFlow();
    if (pending?.role) return pending.role;
    return COOKIE.get('kareta_role') || (()=>{ try{ return localStorage.getItem(STORAGE.roleMemoryKey)||''; }catch(e){return '';} })();
  }
  function shouldShowStartupEntryFlow(){
    if (S.user?.phone) return false;
    // Cookie через PHP (мгновенно, без localStorage)
    const phpRole    = window._karetaCookieRole    || '';
    const phpOnbDone = window._karetaCookieOnbDone || false;
    if (phpOnbDone && phpRole) return false; // уже прошёл
    if (phpOnbDone) return false;            // onb пройден, роль потом
    const pending = getPendingEntryFlow();
    if (pending?.role) return false;
    const remembered = getRememberedRole();
    if (remembered) return false;
    return !isEntryFlowDone();
  }
  // Куда вести гостя с запомненной ролью (без auth)
