  const DEMO_ROLE_KEY      = 'kareta_demo_role';
  const PENDING_ACTION_KEY = 'kareta_pending_action';

  function getDemoRole() {
    try { return localStorage.getItem(DEMO_ROLE_KEY) || COOKIE.get(DEMO_ROLE_KEY) || ''; }
    catch(e) { return COOKIE.get(DEMO_ROLE_KEY) || ''; }
  }
  function setDemoRole(role) {
    const r = normalizeEntryRole(role) || 'client';
    try { localStorage.setItem(DEMO_ROLE_KEY, r); } catch(e) {}
    COOKIE.set(DEMO_ROLE_KEY, r, 30);
  }
  function clearDemoRole() {
    try { localStorage.removeItem(DEMO_ROLE_KEY); } catch(e) {}
    COOKIE.del(DEMO_ROLE_KEY);
  }
  function getAuthRole() { return S.user?.role || ''; }

  function setPendingAction(action, data) {
    try { localStorage.setItem(PENDING_ACTION_KEY, JSON.stringify({action, data, ts:Date.now()})); } catch(e) {}
  }
  function getPendingAction() {
    try {
      const raw = localStorage.getItem(PENDING_ACTION_KEY);
      if (!raw) return null;
      const p = JSON.parse(raw);
      if (Date.now() - (p.ts||0) > 30*60*1000) { clearPendingAction(); return null; }
      return p;
    } catch(e) { return null; }
  }
  function clearPendingAction() { try { localStorage.removeItem(PENDING_ACTION_KEY); } catch(e) {} }

  function _runRequireAuthImmediateAction(action, data) {
    const d = data || {};
    switch (String(action || '')) {
      case 'master_workbench':
        nav('master:work:queue', true);
        return true;
      case 'open_cabinet':
        nav('cabinet', true);
        return true;
      case 'open_myorders':
        nav('myorders', true);
        return true;
      case 'open_booking':
        nav('services:quick', true);
        return true;
      case 'open_chat':
        if (d.orderId && !String(d.orderId).startsWith('demo_')) window.Messenger?.openByOrder?.(d.orderId);
        else window.Messenger?.toggle?.();
        return true;
      case 'open_order':
        if (d.orderId && !String(d.orderId).startsWith('demo_')) window.masterOpenOrderCard?.(d.orderId);
        else nav('master:work:queue', true);
        return true;
      case 'sto_team':
      case 'sto_accept_lead':
      case 'sto_assign_master':
      case 'sto_open_client':
        nav('sto_dashboard', true);
        return true;
      case 'sto_orders':
        nav('myorders', true);
        return true;
      default:
        return false;
    }
  }

  function _softSwitchRoleForWorkbench(action, requiredRole, data) {
    const act = String(action || '');
    const roleTarget = normalizeEntryRole(requiredRole || '');
    if (!S.user?.phone) return false;
    if (act !== 'master_workbench' || roleTarget !== 'master') return false;

    // кнопка "Войти как мастер" — это не рабочее действие заявки,
    // а явный вход в мастерскую. Если пользователь уже сидит как клиент,
    // переводим его профиль в роль master и только потом открываем #master:work:queue.
    try { clearDemoRole(); } catch(_e) {}
    try { clearPendingAction(); } catch(_e) {}
    try { rememberEntryRole('master'); } catch(_e) {}
    try { setEntryFlow({ role:'master', entryRole:'master', pending:false, stage:'done' }); } catch(_e) {}

    mergeUserPatch({
      role:'master',
      entryRole:'master',
      onboardingStage:'done',
      onboarded:true
    });
    try { RBAC.upsertUser?.(S.user); } catch(_e) {}

    // Серверная синхронизация не блокирует навигацию, но запускается сразу.
    Promise.resolve()
      .then(() => persistServerProfile(profileFromUser(S.user)))
      .catch(e => { try { console.warn('[requireAuth.master_workbench] persist failed', e); } catch(_e) {} });

    nav('master:work:queue', true);
    setTimeout(() => {
      try {
        const needsSetup = !String(S.user?.city || '').trim() || !String(S.user?.spec || S.user?.specialization || '').trim();
        if (needsSetup) showProfileSetupModal?.('master', S.user);
      } catch(_e) {}
    }, 260);
    showToast?.('Открыта мастерская', 'success');
    return true;
  }

  function requireAuth(action, opts) {
    // requireAuth остаётся gate-проверкой для действий,
    // но role-entry кнопки вроде master_workbench теперь реально переводят пользователя
    // в мастерскую, даже если он уже был авторизован как клиент.
    const data = opts || {};
    const requiredRole = normalizeEntryRole(data.role || '');
    if (S.user?.phone) {
      const userRole = normalizeEntryRole(S.user.role || 'client');
      const isPrivileged = userRole === 'admin' || userRole === 'owner';
      if (requiredRole && requiredRole !== userRole && !isPrivileged) {
        if (_softSwitchRoleForWorkbench(action, requiredRole, data)) return false;
        const labels = { client:'клиента', master:'мастера', sto:'СТО' };
        showToast?.('Требуется роль ' + (labels[requiredRole] || requiredRole) + '. Сейчас активна роль ' + (labels[userRole] || userRole) + '.', 'error');
        return false;
      }
      if (action && _runRequireAuthImmediateAction(action, data)) return false;
      return true;
    }
    if (action) setPendingAction(action, data);
    const role = normalizeEntryRole(data.role || getDemoRole() || getRememberedRole() || 'client');
    if (role) {
      try { rememberEntryRole(role); } catch(_e) {}
      try { setEntryFlow({ role, entryRole:role, pending:true, stage:'auth' }); } catch(_e) {}
    }
    window.showAuth?.(null, role);
    return false;
  }
  window.requireAuth = requireAuth;

  function _executePendingAction(pending) {
    if (!pending?.action) return;
    const {action, data} = pending;
    clearPendingAction();
    try {
      const d = data || {};
      switch(action) {
        case 'open_myorders':     nav('myorders', true); break;
        case 'open_booking':      nav('services:quick', true);  break;
        case 'book_service':      nav('services', true); break;
        case 'create_order':      nav('services', true); break;
        case 'write_review':      if (d.orderId) window.openServiceReviewModal?.(d.orderId); break;
        case 'master_claim':
          if (String(d.orderId||'').startsWith('demo_')) { nav('master:work:queue', true); showToast?.('Вход выполнен. Выберите реальную заявку из биржи.', 'success'); }
          else if (d.orderId) window.masterSelfClaim?.(d.orderId);
          else nav('master:work:queue', true);
          break;
        case 'master_discuss':
          if (String(d.orderId||'').startsWith('demo_')) { nav('master:work:queue', true); showToast?.('Вход выполнен. Откройте реальную заявку для обсуждения.', 'success'); }
          else if (d.orderId) window.masterOpenQueuePreview?.(d.orderId);
          else nav('master:work:queue', true);
          break;
        case 'master_workbench':  nav('master:work:queue', true); break;
        case 'open_chat':         if (d.orderId && !String(d.orderId).startsWith('demo_')) window.Messenger?.openByOrder?.(d.orderId); else window.Messenger?.toggle?.(); break;
        case 'open_order':        if (d.orderId && !String(d.orderId).startsWith('demo_')) window.masterOpenOrderCard?.(d.orderId); else nav('master:work:queue', true); break;
        case 'sto_accept_lead':   nav('sto_dashboard', true); showToast?.('Вход выполнен. Выберите реальный лид.', 'success'); break;
        case 'sto_assign_master': nav('sto_dashboard', true); showToast?.('Вход выполнен. Назначение доступно для реальных заявок.', 'success'); break;
        case 'sto_open_client':   nav('sto_dashboard', true); showToast?.('Вход выполнен. Контакты доступны в реальных лидах.', 'success'); break;
        case 'sto_team':          nav('sto_dashboard', true); break;
        case 'sto_orders':        nav('myorders', true); break;
        case 'open_cabinet':      nav('cabinet', true); break;
        default: nav(({client:'home',master:'master:work:queue',sto:'sto_dashboard'})[getAuthRole() || getDemoRole()]||'home', true);
      }
    } catch(e) {}
  }

  function getRoleLanding(roleValue){
    const r = normalizeEntryRole(roleValue || getAuthRole() || getDemoRole() || getRememberedRole() || 'client');
    return ({client:'home', master:'master:work:queue', sto:'sto_dashboard'})[r] || 'home';
  }
  function canDemoViewRoute(key){
    const k = String(key || '');
    if (S.user?.phone) return false;
    const dr = getDemoRole();
    return (dr === 'master' && k === 'master') || (dr === 'sto' && k === 'sto_dashboard');
  }
  function canAccessRouteForNav(key){
    const route = ROUTES?.[key];
    if (!route) return false;
    if (!route.perm) return true;
    if (RBAC.can(S.user, route.perm)) return true;
    return canDemoViewRoute(key);
  }
  function requireDemoNavAuth(key){
    if (S.user?.phone) return false;
    const dr = getDemoRole();
    if (dr === 'master') {
      if (key === 'market' || key === 'master') return false;
      const action = key === 'messages' ? 'open_chat' : key === 'cabinet' ? 'open_cabinet' : key === 'schedule' ? 'master_workbench' : key === 'orders' ? 'master_workbench' : 'master_workbench';
      requireAuth(action, { role:'master' });
      return true;
    }
    if (dr === 'sto') {
      if (key === 'sto_dashboard') return false;
      const action = key === 'masters' ? 'sto_team' : key === 'myorders' ? 'sto_orders' : key === 'messages' ? 'open_chat' : 'open_cabinet';
      requireAuth(action, { role:'sto' });
      return true;
    }
    return false;
  }

