  /* helpers — переключают вкладки внутри уже открытой страницы или навигируют */
  function applyMasterPaneVisibility(tab){
    const paneKey = String(tab === 'chats' ? 'chats' : (tab || '')).trim();
    if(!paneKey) return false;
    let found = false;
    document.querySelectorAll('.mpane').forEach(pane=>{
      const active = pane.id === 'mp-' + paneKey;
      if(active) found = true;
      pane.hidden = !active;
      pane.setAttribute('data-master-pane-active', active ? '1' : '0');
      pane.classList.toggle('is-active', active);
      pane.classList.toggle('is-hidden', !active);
      pane.style.display = active ? 'block' : 'none';
    });
    try { syncChromeGeometry?.(); } catch(_e) {}
    return found;
  }
  window.applyMasterPaneVisibility = applyMasterPaneVisibility;

  function navMaster(tab){
    if(['stats','staff'].includes(tab)){
      return navMasterCabinet(tab==='stats' ? 'analytics' : 'contacts');
    }
    const openMasterPane = ()=>{
      document.querySelectorAll('[data-mtab]').forEach(b=>b.classList.toggle('active',b.dataset.mtab===tab));
      applyMasterPaneVisibility(tab);
      syncBnavActive(tab==='cabinet' ? 'cabinet' : tab==='schedule' ? 'schedule' : tab==='chats' ? 'chats' : tab==='clients' ? 'clients' : tab==='news' ? 'news' : tab==='work' ? 'market' : tab);
      try {
        const _sub = (() => {
          // Сохраняем активный sub-tab если он есть
          if (tab === 'work') {
            const activeSubtab = document.querySelector('[data-subtab].active');
            return activeSubtab ? ':' + activeSubtab.dataset.subtab : ':queue';
          }
          return '';
        })();
        karetaUrlPush('master:' + tab + _sub, 'navMaster:' + tab);
      } catch(_e) {}
    };
    if(page!=='master'){
      nav('master');
      setTimeout(openMasterPane, TIMING.NAV_SETTLE);
    } else {
      const el=document.getElementById('mp-'+tab);
      if(el){
        openMasterPane();
      } else {
        nav('master');
        setTimeout(openMasterPane, 200);
      }
    }
  }

  function navMasterCabinet(subtab){
    const openSubtab = ()=>{
      document.querySelectorAll('[data-mtab]').forEach(b=>b.classList.toggle('active',b.dataset.mtab==='cabinet'));
      applyMasterPaneVisibility('cabinet');
      try { karetaUrlPush('master:cabinet' + (subtab ? ':'+subtab : ''), 'navMasterCabinet'); } catch(_e) {}
      openMasterCabinetSection(subtab||'cabinet');
      syncBnavActive('cabinet');
    };
    if(page!=='master'){
      nav('master');
      setTimeout(openSubtab, TIMING.NAV_SETTLE);
    } else {
      openSubtab();
    }
  }

