  function syncNavLogoPageLabel(fallbackKey){
    const labelEl = document.getElementById('navActivePageLabel');
    if(!labelEl) return;
    const activeBnavLabel = document.querySelector('.bnav-item.active .bnav-label')?.textContent?.trim();
    const activeTopLabel = document.querySelector('.drawer-link.active')?.textContent?.trim();
    if(page === 'master_profile' && !activeTopLabel) return void(labelEl.textContent = 'Мастера');
    const fallbackLabel = document.querySelector(`.bnav-item[data-page="${fallbackKey||''}"] .bnav-label`)?.textContent?.trim()
      || document.querySelector(`.drawer-link[data-page="${fallbackKey||''}"]`)?.textContent?.trim()
      || LABELS[fallbackKey]
      || ROUTES[fallbackKey]?.label
      || 'Главная';
    labelEl.textContent = activeBnavLabel || activeTopLabel || fallbackLabel;
  }
  function bindNavLogoPageLabelSync(){
    const navRoot = document.getElementById('bottomNavInner');
    if(!navRoot || navRoot.__logoLabelBound) return;
    navRoot.__logoLabelBound = true;
    const refresh = ()=>syncNavLogoPageLabel(page || 'home');
    navRoot.addEventListener('click', ()=>setTimeout(refresh, 0));
    try{
      const mo = new MutationObserver(()=>refresh());
      mo.observe(navRoot, { subtree:true, childList:true, attributes:true, characterData:true, attributeFilter:['class'] });
    }catch(_e){}
  }
  function syncBnavActive(key){
    document.querySelectorAll('.bnav-item').forEach(el=>{
      const isActive = el.dataset.page===key;
      el.classList.toggle('active', isActive);
      if(isActive) el.setAttribute('aria-current','page');
      else if(el.getAttribute('aria-current') === 'page') el.removeAttribute('aria-current');
    });
    syncNavLogoPageLabel(key);
    try { syncChromeGeometry?.(); } catch(_e) {}
  }
  window.navMaster = navMaster;
