    const m = window.DB?.Masters?.get?.(mid) || allMasters.find(x=>String(x&&x.id||'')===mid);
    if (!m) { window.openMasterPublicProfile(mid); return; }

    const resume = (m.resume && typeof m.resume==='object' && !Array.isArray(m.resume)) ? m.resume : {};
    const stats  = window.DB?.Masters?.stats?.(m.id) || {};
    const posts  = window.DB?.MasterWall?.byMaster?.(m.id) || [];
    // Отзывы из master_reviews (приоритет) + fallback к order reports
    const _dbReviews = window.DB?.MasterPosts?.reviews?.(m.id) || [];
    const _orderReviews = (window.DB?.Orders?.forMaster?.(m.id)||[]).flatMap(o=>(o.reports||[]).filter(r=>r.rating)).slice(0,10);
    const reviews = _dbReviews.length ? _dbReviews : _orderReviews;
    const color = m.color || '#34d399';
    const colorDim = color+'1a'; const colorBrd = color+'35';

    const name   = m.name || 'Мастер';
    const spec   = resume.spec || m.spec || 'Специалист';
    const city   = resume.city || m.city || 'Усть-Каменогорск';
    const rating = Number(m.rating || resume.rating || stats.rating || 0);
    const exp    = resume.experience || m.experienceYears || '';
    const done   = Number(stats.done || m.completedOrders || resume.completedOrders || 0);
    const responseTime = m.responseTimeLabel || resume.responseTimeLabel || 'До 10 мин';
    const priceFrom = Number(m.startingPrice || resume.startingPrice || 5000);
    const bio    = resume.bio || `${name} — ${spec}.`;
    const workMode = m.workMode || resume.workMode || '';
    const isVerified = String(m.isVerified ?? resume.isVerified ?? true) !== 'false';
    const hasWarranty = String(m.hasWarranty ?? resume.hasWarranty ?? true) !== 'false';
    const guarantee  = resume.guarantee || m.guarantee || (hasWarranty ? 'Есть' : 'Нет');
    const minCheck   = resume.minCheck || m.minCheck || '';
    const workWithParts = resume.workWithOwnParts !== undefined ? (resume.workWithOwnParts ? 'Принимает' : 'Не работает') : 'Уточняется';
    const urgentWork    = resume.urgentWork !== undefined ? (resume.urgentWork ? 'Есть' : 'Нет') : 'Уточняется';
    const payMethods    = resume.paymentMethods || m.paymentMethods || 'Наличные, безнал';
    const primaryServices = (Array.isArray(m.primaryServices) ? m.primaryServices : [])
      .concat(String(resume.skills||resume.services||m.spec||'').split(/[;,\n]+/).map(s=>s.trim()).filter(Boolean))
      .filter((v,i,a)=>a.indexOf(v)===i).slice(0,6);
