      const nameEl = document.getElementById('pofm-name');
      const phoneEl = document.getElementById('pofm-phone');
      const commentEl = document.getElementById('pofm-comment');
      const vinEl = document.getElementById('pofm-vin');
      const oemEl = document.getElementById('pofm-oem');
      const qtyEl = document.getElementById('pofm-qty');
      const urgencyEl = document.getElementById('pofm-urgency');
      const makerEl = document.getElementById('pofm-maker');
