      if(vinEl && (meta.vin || order.vin || order.partsVin)) { vinEl.value = normalizePartVin(meta.vin || order.vin || order.partsVin); partsVinInput(vinEl); }
      if(oemEl && (meta.oem || order.partsOem)) oemEl.value = String(meta.oem || order.partsOem || '');
