  function getServicesCategoryUrl(cat, action=''){
    const token = String(cat || '').trim();
    const act = String(action || '').trim();
    if (token === 'parts_install') return 'parts';
    return token && token !== 'all' ? ('services:' + encodeURIComponent(token) + (act ? ':' + encodeURIComponent(act) : '')) : 'services';
  }
  window.getServicesCategoryUrl = window.getServicesCategoryUrl || getServicesCategoryUrl;

