  window._submitSvcRequestModal = async function(btn) {
    if(btn){btn.disabled=true;btn.textContent='⏳...';}
    const format=document.getElementById('srm-format')?.value||'sto';
    const urgency=document.getElementById('srm-urgency')?.value||'normal';
    const address=document.getElementById('srm-address')?.value?.trim()||'';
    const notes=document.getElementById('srm-notes')?.value?.trim()||'';
    if(format==='field'&&!address){showToast('Укажите адрес выезда','error');if(btn){btn.disabled=false;btn.textContent='▤ Отправить заявку';}return;}
    if(!notes){showToast('Опишите проблему','error');if(btn){btn.disabled=false;btn.textContent='▤ Отправить заявку';}return;}
    const pf=window._srm_prefill||{};
    try{
      const attachMeta=(window._svcAttachFiles||[]).filter(Boolean).map(f=>({name:f.name,type:f.type,mime:f.mime||'',size:f.size,dataUrl:f.dataUrl||''}));
      window._svcAttachFiles=[];
      const _u = window._appState?.user || window.S?.user || {};
      const _v = window.DB?.Vehicles?.getDefault?.() || null;
      await window.DB?.Orders?.create?.({
        type:'service_order', status:'waiting_responses',
        priority: urgency==='urgent' ? 'urgent' : 'normal',
        notes, address, workFormat:format, fieldService:format==='field',
        urgency, category:pf.category||'',
        serviceIds: (pf.serviceIds && pf.serviceIds.length) ? pf.serviceIds : ['general'],
        attachments: attachMeta,
        clientName:  String(_u.name || _u.phone || 'Клиент').trim(),
        clientPhone: String(_u.phone || '').trim(),
        clientCar:   (document.getElementById('srm-car')?.value?.trim() || String(_u.car || (_v && _v.title) || '')).trim(),
        clientVehicleId: String(_v?.id || '').trim(),
      });
      document.getElementById('svc-request-modal-wrap')?.classList.remove('open');
      document.body.style.overflow='';
      showToast('✅ Заявка создана! Мастера откликнутся.','success');
      setTimeout(()=>{try{App.go('myorders');}catch(_e){}},300);
    }catch(e){
      showToast(e?.message||'Ошибка при создании заявки','error');
      if(btn){btn.disabled=false;btn.textContent='▤ Отправить заявку';}
    }
  };

  function openClientServiceCategory(cat='all'){
    const id = String(cat || 'all').trim() || 'all';
    if (id === 'parts_install') {
      window._servicesActiveCat = 'all';
      App.go('parts', { canonicalHash: 'parts', source: 'services_parts_install' });
      return;
    }
    const def = getClientHomeCategoryDefs().find(x => String(x.id||'') === id);
    if (def && def.special && window.openSpecialService) {
      try { history.pushState({ serviceScenario:true, cat:id }, '', '#' + getServicesCategoryUrl(id)); } catch(_e) {}
      return window.openSpecialService(def.special, { from:'services_category', cat:id });
    }
    return openServicesCategoryPage(id);
  }
