  function initServicesHomeSlider(){
    const slider = document.querySelector('[data-services-home-slider="1"]');
    if(!slider) return;
    try{
      if(window.__servicesHomeSlider?.timer) clearInterval(window.__servicesHomeSlider.timer);
    }catch(_e){}
    const slides = Array.from(slider.querySelectorAll('.services-home-slide'));
    const dotsWrap = document.querySelector('[data-services-home-slider-dots="1"]');
    const dots = dotsWrap ? Array.from(dotsWrap.querySelectorAll('[data-slide-dot]')) : [];
    if(slides.length < 2) return;
    const ms = Math.max(1800, parseInt(slider.getAttribute('data-autoplay-ms') || '3140', 10) || 3140);
    let active = 0;
    let userPauseUntil = 0;
    let scrollTimer = 0;
    const setActive = (next) => {
      active = Math.max(0, Math.min(slides.length - 1, Number(next) || 0));
      slides.forEach((el,i)=>el.classList.toggle('is-active', i === active));
      dots.forEach((el,i)=>el.classList.toggle('is-active', i === active));
    };
    const goTo = (next, byUser=false) => {
      const index = (Number(next) + slides.length) % slides.length;
      const target = slides[index];
      if(!target) return;
      setActive(index);
      if(byUser) userPauseUntil = Date.now() + ms * 2;
      try{ slider.scrollTo({ left: target.offsetLeft - slider.offsetLeft, behavior: 'smooth' }); }
      catch(_e){ slider.scrollLeft = target.offsetLeft - slider.offsetLeft; }
    };
    const syncFromScroll = () => {
      const left = slider.scrollLeft;
      let nearest = 0;
      let dist = Infinity;
      slides.forEach((el,i)=>{
        const d = Math.abs((el.offsetLeft - slider.offsetLeft) - left);
        if(d < dist){ dist = d; nearest = i; }
      });
      setActive(nearest);
    };
    slider.addEventListener('scroll', ()=>{
      clearTimeout(scrollTimer);
      scrollTimer = setTimeout(syncFromScroll, 70);
    }, { passive:true });
    ['pointerdown','touchstart','wheel'].forEach(ev=>slider.addEventListener(ev, ()=>{ userPauseUntil = Date.now() + ms * 2; }, { passive:true }));
    dots.forEach((dot,i)=>dot.addEventListener('click', (ev)=>{ ev.preventDefault(); goTo(i, true); }));
    const timer = setInterval(()=>{
      if(!document.body.contains(slider)){ clearInterval(timer); return; }
      if(Date.now() < userPauseUntil) return;
      goTo(active + 1, false);
    }, ms);
    window.__servicesHomeSlider = { timer, goTo };
    setActive(0);
  }

  function initServices(){
    const initialCat = String(S._navOpts?.serviceCat || window._servicesActiveCat || 'all').trim();
    window._servicesInitialCat = initialCat || 'all';
    window._servicesActiveCat = window._servicesInitialCat;
    requestAnimationFrame(()=>{ try{ initServicesHomeSlider(); }catch(_e){} });
    if(S.pendingPricingTab || S._navOpts?.openPricing){
      S.pendingPricingTab = null;
      setTimeout(()=>{ try{ openServicesPricingSheet(); }catch(_e){} }, 60);
    }
    const pendingScenarioCat = S._navOpts?.serviceCat || '';
    const pendingScenarioAction = S._navOpts?.specialAction || '';
    if (pendingScenarioCat && pendingScenarioCat !== 'all') {
      const def = getClientHomeCategoryDefs().find(x => String(x.id||'') === String(pendingScenarioCat||''));
      if (def && def.special) {
        setTimeout(()=>{
          try {
            if (window.openServiceCategoryScenario) window.openServiceCategoryScenario(pendingScenarioCat, pendingScenarioAction);
          } catch(_e) { console.warn('[ServicesScenario] open from URL failed', _e); }
        }, 120);
      }
    }
    // Если в URL был #service:ID — открываем модалку после рендера
    const pendingServiceId = S._navOpts?.serviceId;
    if(pendingServiceId){
      function tryOpenSvcModal(){
        const svc = getServiceById(pendingServiceId);
        if(svc){
          try{ openServiceDetailsModal(pendingServiceId); }catch(_e){}
        } else {
          // DB ещё не загружена — ждём pull, потом открываем
          const unsub = DB.on('db.pull', function(){
            unsub();
            setTimeout(()=>{ try{ openServiceDetailsModal(pendingServiceId); }catch(_e){} }, 60);
          });
        }
      }
      setTimeout(tryOpenSvcModal, 80);
    }
  }

