  function getClientHomeCategoryDefs(){
    return CLIENT_HOME_CATEGORY_DEFS.map(x => Object.assign({}, x));
  }
  function _clientServiceSearchText(svc){
    return String([
      svc?.cat || '', svc?.name || '', svc?.shortDesc || '', svc?.whyText || '', svc?.priceLabel || '',
      Array.isArray(svc?.steps) ? svc.steps.join(' ') : '', Array.isArray(svc?.list) ? svc.list.join(' ') : ''
    ].join(' ')).toLowerCase();
  }
  function detectClientServiceCat(svc){
    const raw = String(svc?.cat || '').toLowerCase();
    const text = _clientServiceSearchText(svc);
    const has = rx => rx.test(text);
    if (raw === 'diagnostics' || has(/диагност|компьютерн|предпродаж|осмотр|провер/)) return 'diagnostics';
    if (raw === 'oil' || has(/замен[аы] масла|масл|фильтр|антифриз|жидкост|акпп|мкпп/)) return 'oil';
    if (raw === 'battery' || has(/акб|аккум|прикур|зарядк|доставить новый|подобрать аккумулятор/)) return 'battery';
    if (raw === 'tires' || has(/шин|колес|баланс|прокол|сезонн|резин/)) return 'tires';
    if (raw === 'brakes' || has(/тормоз|колодк|суппорт|abs|ручник|скрип|биени/)) return 'brakes';
    if (raw === 'body' || has(/кузов|покраск|рихтов|бампер|вмятин|сварк|дтп|стекл/)) return 'body';
    if (raw === 'chassis' || has(/ходов|подвес|амортиз|рычаг|сайлент|рулев|шаров|ступиц|стабилизатор|развал|шрус/)) return 'chassis';
    if (raw === 'electric' || raw === 'electrical' || raw === 'audio' || raw === 'security' || has(/генератор|стартер|проводк|освещ|предохран|датчик|ошибк|электрик|электрон|сигнализац|автозапуск|carplay|магнитол|акустик/)) return 'electric';
    if (raw === 'transmission' || has(/мкпп|акпп|коробк|сцеплен|кпп|хвостов|кардан.*вал|привод.*сальн/)) return 'transmission';
    if (raw === 'misc' || has(/слесарн|сварочн|простой.*авт|развал|схожден|уплотнит.*двер|промывк.*отоп/)) return 'misc';
    if (raw === 'parts_install' || has(/запчаст|подбор|детал|аналог|оригинал|установк/)) return 'parts_install';
    if (raw === 'engine' || has(/двигател|грм|не завод|троит|дымит|перегрев|теч|капрем|форсунк|помп|коллект|глушит|термост|антифриз|масл.*двс|замен.*масла/)) return 'engine';
    return 'diagnostics';
  }
  function getClientServiceHomeGroups(svcs){
    const defs = getClientHomeCategoryDefs();
    const byId = Object.fromEntries(defs.map(def => [def.id, { id:def.id, count:0, minPrice:Number.POSITIVE_INFINITY, minPriceLabel:def.priceFrom || 'Цена по запросу', preview:[...(def.examples||[])], items:[] }]));
    (Array.isArray(svcs) ? svcs : []).forEach(svc => {
      const id = detectClientServiceCat(svc);
      const bucket = byId[id] || byId.diagnostics;
      bucket.count += 1;
      bucket.items.push(svc);
      if (bucket.preview.length < 4 && svc?.name) bucket.preview.push(String(svc.name));
      const base = Number(svc?.basePrice || 0);
      if (base > 0 && base < bucket.minPrice){
        bucket.minPrice = base;
        bucket.minPriceLabel = 'от ' + base.toLocaleString('ru-RU') + ' ₸';
      } else if (!isFinite(bucket.minPrice) && svc?.priceLabel) {
        bucket.minPriceLabel = String(svc.priceLabel);
      }
    });
    Object.values(byId).forEach(bucket => {
      bucket.preview = Array.from(new Set(bucket.preview.filter(Boolean))).slice(0,4);
      if (!bucket.count && !bucket.preview.length) bucket.preview = [];
    });
    return { byId, defs };
  }
  const SERVICE_CATEGORY_META = Object.fromEntries(getClientHomeCategoryDefs().map(def => [def.id, { id:def.id, label:def.label, color:def.color, desc:def.desc, e:def.icon }]));
  const SERVICE_CAT_ICONS = Object.fromEntries(getClientHomeCategoryDefs().map(def => [def.id, def.icon]));
  const SERVICE_CATEGORY_ORDER = getClientHomeCategoryDefs().map(def => def.id);
  function normalizeServiceCat(cat, svc=null){
    const raw = String(cat || svc?.cat || '').trim().toLowerCase();
    if (SERVICE_CATEGORY_META[raw]) return raw;
    if (raw === 'electrical') return 'electric';
    if (svc) return detectClientServiceCat(svc);
    if (raw === 'audio' || raw === 'security') return 'electric';
    return raw || 'diagnostics';
  }
  function getServiceCategoryMeta(cat, svc=null){ return SERVICE_CATEGORY_META[normalizeServiceCat(cat, svc)] || SERVICE_CATEGORY_META.diagnostics; }
  function serviceCatLabel(cat, svc=null){ return getServiceCategoryMeta(cat, svc).label; }
  function serviceCatIcon(cat, svc=null){ return SERVICE_CAT_ICONS[normalizeServiceCat(cat, svc)] || '⌁'; }
  function serviceCatColor(cat, svc=null){ return getServiceCategoryMeta(cat, svc).color; }
  function openCategoryBooking(cat){
    const meta = getServiceCategoryMeta(cat);
    if(!window.App?.startServiceBooking) return false;
    return window.App.startServiceBooking({
      serviceCategoryId: meta.id,
      serviceCategoryLabel: meta.label,
      comment: 'Категория: ' + meta.label
    });
  }
  window.openCategoryBooking = window.openCategoryBooking || openCategoryBooking;

  function getServicesFaqContent(){
    const raw = getSiteContent('services_faq', [], 'FAQ по услугам').body;
    return Array.isArray(raw) ? raw : [];
  }


