  function servicesAppMainTiles(){
    return [
      {cat:'tires', label:'Шины'},
      {cat:'diagnostics', label:'Диагностика'},
      {cat:'repair', label:'Ремонт'},
      {cat:'oil', label:'Масла'},
      {cat:'wash', label:'Мойка'},
      {cat:'detailing', label:'Детейлинг'},
      {cat:'electric', label:'Электрика'},
      {cat:'brakes', label:'Тормоза'},
      {cat:'parts', label:'Запчасти', route:'parts'}
    ];
  }
  function servicesAppGetCategory(cat){
    const data = servicesAppCategoryData();
    const key = String(cat || '').trim();
    return data[key] ? Object.assign({key}, data[key]) : Object.assign({key:'repair'}, data.repair);
  }
  function servicesAppGetItem(cat, itemId){
    const meta = servicesAppGetCategory(cat);
    const id = String(itemId || '').trim();
    return (meta.items || []).find(x=>String(x.id)===id) || (meta.items || [])[0] || {id:'custom', title:meta.title, desc:meta.desc, price:'по заявке', iconKey:meta.iconKey};
  }
  function servicesAppCleanText(v, fallback=''){
    const s = String(v ?? '').replace(/\s+/g, ' ').trim();
    return s || fallback;
  }
  function servicesAppFirstNonEmpty(){
    for(let i=0;i<arguments.length;i++){
      const v = servicesAppCleanText(arguments[i]);
      if(v) return v;
    }
    return '';
  }
  const SERVICES_APP_FALLBACK_COVER = '/assets/services/kareta_service_cover.svg';
  const SERVICES_APP_FALLBACK_THUMB = '/assets/services/kareta_service_thumb.svg';
  const SERVICES_APP_LOGO_FULL = '/assets/onboarding/kareta_logo_full.png';
  function servicesAppToArray(v){
    if(Array.isArray(v)) return v.map(x=>servicesAppCleanText(x)).filter(Boolean);
    const s = servicesAppCleanText(v);
    if(!s) return [];
    return s.split(/[;,/|·]+/).map(x=>servicesAppCleanText(x)).filter(Boolean);
  }
  function servicesAppFormatPhone(v){ return String(v || '').replace(/[^+\d]/g,''); }
  function servicesAppProviderInitials(name){
    const words = servicesAppCleanText(name, 'СТО').split(/\s+/).filter(Boolean);
    return words.slice(0,2).map(w=>w[0] || '').join('').toUpperCase() || 'СТО';
  }
  function servicesAppNormalizeProviderChips(raw){
    const src = servicesAppToArray(raw);
    const out = [];
    const add = (label) => { label = servicesAppCleanText(label); if(label && !out.some(x=>x.toLowerCase()===label.toLowerCase())) out.push(label); };
    src.forEach(x=>{
      const low = x.toLowerCase();
      if(/диагност/.test(low)) add('Диагностика');
      else if(/шин|кол[её]с|резин/.test(low)) add('Шины');
      else if(/масл|то\b|фильтр/.test(low)) add('Масла');
      else if(/мойк|химчист|детейл/.test(low)) add('Мойка');
      else if(/электр|генератор|стартер|провод|сигнал/.test(low)) add('Электрика');
      else if(/тормоз/.test(low)) add('Тормоза');
      else if(/ремонт|ходов|двиг|кпп|акпп|мкпп|подвес/.test(low)) add('Ремонт');
      else add(x.length > 18 ? (x.slice(0,17).trim() + '…') : x);
    });
    ['Диагностика','Ремонт','Шины','Масла','Другое'].forEach(add);
    return out.slice(0,5);
  }
  function servicesAppProviderSummary(chips, limit=3){
    const list = Array.isArray(chips) ? chips : servicesAppNormalizeProviderChips(chips);
    return list.filter(x=>x && x !== 'Другое').slice(0, limit).join(', ') || 'Диагностика, Ремонт, Шины';
  }
  function servicesAppProviderImage(raw, mode='cover'){
    raw = raw && typeof raw === 'object' ? raw : {};
    const direct = servicesAppFirstNonEmpty(raw.cover, raw.coverUrl, raw.photo, raw.photoUrl, raw.avatar, raw.image, raw.logo, raw.img, raw.banner);
    if(direct) return direct;
    return mode === 'thumb' ? SERVICES_APP_FALLBACK_THUMB : SERVICES_APP_FALLBACK_COVER;
  }
  function servicesAppProviderWorkStatus(raw){
    raw = raw && typeof raw === 'object' ? raw : {};
    const explicit = servicesAppFirstNonEmpty(raw.workStatus, raw.statusLabel, raw.openStatus);
    if(explicit) return explicit;
    const until = servicesAppFirstNonEmpty(raw.workUntil, raw.openUntil, raw.closeTime, raw.closesAt);
    if(until) return 'Работает до ' + until;
    const work = servicesAppFirstNonEmpty(raw.worktime, raw.workTime, raw.schedule, raw.hours);
    if(work && /\d/.test(work)) return work;
    return 'Работает до 20:00';
  }
  function servicesAppNormalizeDistance(v){
    const s = servicesAppCleanText(v);
    if(!s) return '1,2 км';
    if(/км|м\b/.test(s.toLowerCase())) return s.replace('.', ',');
    const n = Number(String(s).replace(',', '.').replace(/[^0-9.]/g,''));
    return Number.isFinite(n) && n > 0 ? String(n).replace('.', ',') + ' км' : '1,2 км';
  }
  function servicesAppProviderFromSto(sto){
    sto = sto && typeof sto === 'object' ? sto : {};
    const id = servicesAppCleanText(sto.id || sto.stoId || sto.sto_id);
    if(!id) return null;
    const name = servicesAppFirstNonEmpty(sto.name, sto.title, sto.companyName, sto.serviceName, 'Автосервис');
    const chips = servicesAppNormalizeProviderChips(sto.services || sto.spec || sto.specialization || sto.categories || sto.tags);
    const phone = servicesAppFirstNonEmpty(sto.phone, sto.phoneLabel, sto.whatsapp, sto.mobile);
    const city = servicesAppFirstNonEmpty(sto.city, sto.region);
    const address = servicesAppFirstNonEmpty(sto.address, sto.location, [city, sto.street].filter(Boolean).join(', '), 'Адрес уточняется');
    const rating = Number(sto.rating || sto.avgRating || sto.stars || 4.8);
    const reviews = Number(sto.reviewsCount || sto.reviewCount || sto.reviews || 0);
    return {
      id:'sto_' + id, rawId:id, source:'sto', name,
      brand: servicesAppFirstNonEmpty(sto.brand, name).slice(0, 14).toUpperCase(),
      verified: sto.verified !== false,
      phone, site:servicesAppFirstNonEmpty(sto.site, sto.website, sto.url),
      address, city,
      worktime: servicesAppFirstNonEmpty(sto.worktime, sto.workTime, sto.schedule, sto.hours, '08:00 – 20:00, без выходных'),
      pay: servicesAppFirstNonEmpty(sto.pay, sto.payment, sto.paymentMethods, 'Наличный, Kaspi QR, Карта'),
      features: servicesAppFirstNonEmpty(sto.features, sto.options, sto.amenities, 'Wi‑Fi, Комната ожидания, Кофе'),
      rating: Number.isFinite(rating) ? rating : 4.8,
      reviews: Number.isFinite(reviews) && reviews > 0 ? reviews : 128,
      distance: servicesAppNormalizeDistance(sto.distance || sto.distanceKm),
      chips, summary: servicesAppProviderSummary(chips),
      image: servicesAppProviderImage(sto, 'cover'), thumb: servicesAppProviderImage(sto, 'thumb'),
      status: servicesAppProviderWorkStatus(sto)
    };
  }
  function servicesAppProviderFromMaster(master){
    master = master && typeof master === 'object' ? master : {};
    const id = servicesAppCleanText(master.id || master.masterId || master.master_id);
    if(!id) return null;
    const stoName = servicesAppFirstNonEmpty(master.stoName, master.sto_name, master.shopName, master.serviceName, master.companyName);
    const name = stoName || servicesAppFirstNonEmpty(master.name, 'Мастер сервиса');
    const chips = servicesAppNormalizeProviderChips(master.services || master.spec || master.specialization || master.role || master.tags);
    const phone = servicesAppFirstNonEmpty(master.phone, master.whatsapp, master.mobile);
    const city = servicesAppFirstNonEmpty(master.city, master.region);
    const address = servicesAppFirstNonEmpty(master.address, master.location, city, 'Адрес уточняется');
    const stats = window.DB?.Masters?.stats?.(id) || {};
    const rating = Number(master.rating || master.avgRating || stats.rating || 4.8);
    const reviews = Number(master.reviewsCount || master.reviewCount || master.reviews || stats.reviews || stats.done || 0);
    return {
      id:'master_' + id, rawId:id, source:'master', name,
      brand: servicesAppProviderInitials(name), masterName:servicesAppFirstNonEmpty(master.name),
      verified: master.verified !== false,
      phone, site:servicesAppFirstNonEmpty(master.site, master.website, master.url),
      address, city,
      worktime: servicesAppFirstNonEmpty(master.worktime, master.workTime, master.schedule, master.hours, '08:00 – 20:00, без выходных'),
      pay: servicesAppFirstNonEmpty(master.pay, master.payment, master.paymentMethods, 'Наличный, Kaspi QR, Карта'),
      features: servicesAppFirstNonEmpty(master.features, master.options, master.amenities, 'Выезд/бокс по согласованию'),
      rating: Number.isFinite(rating) ? rating : 4.8,
      reviews: Number.isFinite(reviews) && reviews > 0 ? reviews : 128,
      distance: servicesAppNormalizeDistance(master.distance || master.distanceKm),
      chips, summary: servicesAppProviderSummary(chips),
      image: servicesAppProviderImage(master, 'cover'), thumb: servicesAppProviderImage(master, 'thumb'),
      status: servicesAppProviderWorkStatus(master)
    };
  }
  function servicesAppFallbackProvider(){
    const chips = ['Диагностика','Ремонт','Шины','Масла','Другое'];
    return {
      id:'kareta_service', rawId:'kareta_service', source:'local',
      name:'KARETA.KZ Service', brand:'KARETA.KZ', verified:true,
      phone:'+77072980649', site:'', address:'Алматы, Бостандыкский район', city:'Алматы',
      worktime:'08:00 – 20:00, без выходных', pay:'Наличный, Kaspi QR, Карта',
      features:'Wi‑Fi, Комната ожидания, Кофе', rating:4.8, reviews:128, distance:'1,2 км',
      chips, summary:'Диагностика, Ремонт, Шины', image:SERVICES_APP_FALLBACK_COVER, thumb:SERVICES_APP_FALLBACK_THUMB,
      status:'Работает до 20:00'
    };
  }
  function servicesAppGetProviders(){
    const out = [];
    try { (window.DB?.STO?.profiles?.() || []).forEach(s=>{ const p = servicesAppProviderFromSto(s); if(p) out.push(p); }); } catch(_e) {}
    try { (window.DB?.Masters?.getAll?.(false) || window.DB?.Masters?.getAll?.() || []).forEach(m=>{ if(!m || m.active === false) return; const p = servicesAppProviderFromMaster(m); if(p) out.push(p); }); } catch(_e) {}
    const seen = new Set();
    return out.filter(p=>{ const k = p.id; if(seen.has(k)) return false; seen.add(k); return true; });
  }
  function servicesAppGetFeaturedProvider(){
    const providers = servicesAppGetProviders();
    if(!providers.length) return servicesAppFallbackProvider();
    return providers.slice().sort((a,b)=>{
      const av = (a.source === 'sto' ? 0 : 1) + (a.verified ? -0.2 : 0);
      const bv = (b.source === 'sto' ? 0 : 1) + (b.verified ? -0.2 : 0);
      return av - bv || String(a.name||'').localeCompare(String(b.name||''),'ru');
    })[0];
  }
  function servicesAppGetProviderByToken(token){
    const key = servicesAppCleanText(token || '');
    if(!key || key === 'autopro' || key === 'kareta' || key === 'kareta_service') return servicesAppGetFeaturedProvider();
    return servicesAppGetProviders().find(p=>String(p.id)===key || String(p.rawId)===key) || servicesAppGetFeaturedProvider();
  }
  function servicesAppProviderRoute(p){ return p && p.source !== 'demo' && p.source !== 'local' ? ('services:provider:' + encodeURIComponent(p.id)) : 'services:autopro'; }
  function servicesAppProviderPhotoStyle(p, mode='cover'){
    const img = servicesAppCleanText((mode === 'thumb' && p && p.thumb) || (p && p.image) || servicesAppProviderImage(p || {}, mode));
    return img ? ` style="background-image:linear-gradient(0deg,rgba(15,23,42,.14),rgba(15,23,42,.14)),url('${escAttr(img)}')"` : '';
  }
  function servicesAppProviderRatingLine(p, full=false){
    const rating = Number(p?.rating || 0);
    const ratingText = Number.isFinite(rating) && rating > 0 ? rating.toFixed(1).replace('.', ',') : '4,8';
    const reviews = Number(p?.reviews || 0);
    const reviewText = reviews > 0 ? (full ? `(${reviews} отзывов)` : `(${reviews})`) : (full ? '(отзывов пока нет)' : '(0)');
    return {ratingText, reviewText};
  }
  
  // functional actions for .services-home-head-actions.
  function servicesHeadCityLabel(){
    try {
      const st = window.App?.getState?.() || S || {};
      const flow = window.App?.getEntryFlow?.() || {};
      const city = String(st.user?.city || st.user?.entryCity || flow.city || localStorage.getItem('kareta.entryCity') || localStorage.getItem('kareta_city') || '').trim();
      return city || 'Город';
    } catch(_e) { return 'Город'; }
  }
  function servicesHeadFavoritesCount(){
    try {
      const raw = localStorage.getItem('kareta.favorites') || localStorage.getItem('kareta_favorites') || '[]';
      const list = JSON.parse(raw);
      return Array.isArray(list) ? list.length : 0;
    } catch(_e) { return 0; }
  }
  function servicesHeadUnreadCount(){
    try {
      const dbCount = window.DB?.Notifications?.unreadMineCount?.();
      const n = Number(dbCount ?? S.unread ?? 0);
      return Number.isFinite(n) && n > 0 ? n : 0;
    } catch(_e) {
      const n = Number(S.unread || 0);
      return Number.isFinite(n) && n > 0 ? n : 0;
    }
  }
  function servicesHeadRefreshActions(root=document){
    try {
      const city = servicesHeadCityLabel();
      root.querySelectorAll?.('.services-home-head-actions .services-home-loc b').forEach(el=>{ el.textContent = city; });
      const fav = servicesHeadFavoritesCount();
      root.querySelectorAll?.('.services-home-head-actions .services-home-fav').forEach(btn=>{
        let badge = btn.querySelector('.services-head-action-badge');
        if(!badge && fav > 0){ badge = document.createElement('i'); badge.className='services-head-action-badge'; btn.appendChild(badge); }
        if(badge){ badge.textContent = fav > 99 ? '99+' : String(fav); badge.hidden = fav <= 0; }
      });
      const unread = servicesHeadUnreadCount();
      root.querySelectorAll?.('.services-home-head-actions .services-home-bell i').forEach(el=>{ el.textContent = unread > 99 ? '99+' : String(unread); el.hidden = unread <= 0; });
    } catch(_e) {}
  }
  function servicesHeadCloseCityModal(){
    document.getElementById('services-head-city-modal')?.remove();
    try { window.App?.LayerManager?.close?.('services-head-city'); } catch(_e) {}
  }
  function servicesHeadCityModal(){
    const esc = window.escHtml || (v=>String(v||''));
    const current = servicesHeadCityLabel();
    const cities = (window.App?.ENTRY_CITY_OPTIONS || ENTRY_CITY_OPTIONS || ['Усть-Каменогорск','Семей','Алматы','Астана']).filter(Boolean);
    servicesHeadCloseCityModal();
    const html = `<div class="services-head-modal" id="services-head-city-modal" role="dialog" aria-modal="true" aria-label="Выбор города">
      <div class="services-head-modal__card">
        <div class="services-head-modal__head"><div><span>Город обслуживания</span><b>Выберите город или район</b></div><button type="button" onclick="servicesHeadCloseCityModal()" aria-label="Закрыть">×</button></div>
        <div class="services-head-modal__body">
          <input class="services-head-city-input" id="services-head-city-input" value="${esc(current === 'Город' ? '' : current)}" placeholder="Например: Усть-Каменогорск" autocomplete="address-level2">
          <div class="services-head-city-grid">${cities.map(city=>`<button type="button" class="${String(city)===current?'is-active':''}" onclick="servicesHeadChooseCity('${escJs(city)}')">${esc(city)}</button>`).join('')}</div>
          <p>Город будет использоваться в поиске сервисов, запчастей и заявках.</p>
        </div>
        <div class="services-head-modal__foot"><button type="button" onclick="servicesHeadCloseCityModal()">Отмена</button><button type="button" onclick="servicesHeadSaveCity()">Сохранить</button></div>
      </div>
    </div>`;
    const wrap = document.createElement('div');
    wrap.innerHTML = html;
    document.body.appendChild(wrap.firstElementChild);
    try { window.App?.LayerManager?.open?.('services-head-city'); } catch(_e) {}
    setTimeout(()=>document.getElementById('services-head-city-input')?.focus(), 30);
    return false;
  }
  function servicesHeadChooseCity(city){
    const input = document.getElementById('services-head-city-input');
    if(input) input.value = String(city || '').trim();
    document.querySelectorAll('.services-head-city-grid button').forEach(btn=>btn.classList.toggle('is-active', btn.textContent.trim() === String(city||'').trim()));
    return false;
  }
  async function servicesHeadSaveCity(){
    const input = document.getElementById('services-head-city-input');
    const city = String(input?.value || '').trim();
    if(!city){ try { window._showToast?.('Укажите город','error'); } catch(_e) {} return false; }
    const patch = { city, entryCity: city };
    const isAuthed = !!S.user?.phone;
    try {
      if(isAuthed && window.App?.persistServerProfile){
        const saved = await window.App.persistServerProfile(patch);
        if(!saved){
          try { window._showToast?.('Сервер не подтвердил сохранение города','error'); } catch(_e) {}
          return false;
        }
        const savedCity = String((saved && typeof saved === 'object' && (saved.city || saved.entryCity)) || city).trim() || city;
        window.App?.mergeUserPatch?.({ city: savedCity, entryCity: savedCity });
        try { localStorage.setItem('kareta.entryCity', savedCity); localStorage.setItem('kareta_city', savedCity); } catch(_e) {}
        try {
          const flow = window.App?.getEntryFlow?.() || {};
          window.App?.setEntryFlow?.(Object.assign({}, flow, { city: savedCity }));
        } catch(_e) {}
      } else {
        try { localStorage.setItem('kareta.entryCity', city); localStorage.setItem('kareta_city', city); } catch(_e) {}
        try {
          const flow = window.App?.getEntryFlow?.() || {};
          window.App?.setEntryFlow?.(Object.assign({}, flow, { city }));
        } catch(_e) {}
      }
      servicesHeadCloseCityModal();
      servicesHeadRefreshActions(document);
      try { window._showToast?.('Город обновлён','success'); } catch(_e) {}
    } catch(_e) {
      try { window._showToast?.('Не удалось сохранить город','error'); } catch(__e) {}
    }
    return false;
  }
  function servicesHeadAction(action){
    const a = String(action || '').toLowerCase();
    try { window.App?.closeTransientPanels?.(); } catch(_e) {}
    if(a === 'city') return servicesHeadCityModal();
    if(a === 'favorites') { App.go('favorites'); return false; }
    if(a === 'notifications' || a === 'notifs') {
      if(!S.user?.phone){ try { requireAuth('open_myorders',{role:'client'}); } catch(_e) { window.App?.showAuth?.('cabinet'); } return false; }
      App.go('cabinet:notifs');
      try { scheduleNotificationsRefresh?.({ force:true, reason:'services-head-open-notifs' }); servicesHeadRefreshActions(document); } catch(_e) {}
      return false;
    }
    if(a === 'menu') { window.toggleDrawer?.(); return false; }
    return false;
  }
  window.servicesHeadAction = servicesHeadAction;
  window.servicesHeadRefreshActions = servicesHeadRefreshActions;
  window.servicesHeadCityModal = servicesHeadCityModal;
  window.servicesHeadCloseCityModal = servicesHeadCloseCityModal;
  window.servicesHeadChooseCity = servicesHeadChooseCity;
  window.servicesHeadSaveCity = servicesHeadSaveCity;

  // central UI action bus for header/buttons.
  // Keeps new buttons modular: data-k-action / data-action-go instead of scattered inline onclick.
  function actionBusNormalize(raw){
    const a = String(raw || '').trim().toLowerCase().replace(/^#/, '').replace(/[\s-]+/g, '_');
    const aliases = {
      fav: 'favorites', favourite: 'favorites', favorites: 'favorites',
      notify: 'notifications', notification: 'notifications', notifs: 'notifications',
      city: 'city', location: 'city', geo: 'city',
      menu: 'menu', drawer: 'menu', more: 'menu',
      quick: 'quick_request', quick_request: 'quick_request', quickrequest: 'quick_request',
      request: 'quick_request', service_request: 'quick_request', new_service: 'quick_request',
      parts: 'parts', parts_request: 'parts', create_request: 'parts',
      masters: 'masters', services: 'services', sales: 'sales', about: 'about',
      garage: 'garage', car: 'garage', vehicles: 'garage', vehicle_garage: 'garage',
      profile: 'profile', account: 'profile', cabinet: 'profile', user: 'profile', notifs_page: 'notifications',
      myorders: 'myorders', orders: 'myorders', messages: 'messages', chats: 'messages',
      order: 'open_order', open_order: 'open_order', order_open: 'open_order', full_order: 'open_order', order_full: 'open_order',
      vehicle_order: 'vehicle_order', order_vehicle: 'vehicle_order', repair_record: 'vehicle_order',
      chat_order: 'chat_order', order_chat: 'chat_order', contact_order: 'chat_order',
      review_order: 'review_order', order_review: 'review_order',
      parts_vehicle: 'parts_vehicle', vehicle_parts: 'parts_vehicle',
      service_vehicle: 'service_vehicle', vehicle_service: 'service_vehicle',
      notif_read: 'notif_read', read_notif: 'notif_read', notification_read: 'notif_read',
      notifs_read_all: 'notifs_read_all', notifications_read_all: 'notifs_read_all', mark_all_notifs: 'notifs_read_all'
    };
    return aliases[a] || a;
  }
  function actionBusRoute(route, source){
    const r = String(route || '').trim().replace(/^#/, '');
    if(!r) return false;
    try {
      if(window.KaretaNav?.go) return KaretaNav.go(r, { source: source || 'action-bus' });
    } catch(_e) {}
    try { App.go(r); } catch(_e2) { try { nav(r, true); } catch(_e3) {} }
    return false;
  }

  // shared action payload helpers. Keeps cards/buttons modular without layout rewrites.
  function actionBusNodeAttr(payload, name, fallback){
    try {
      const node = payload?.node || null;
      if(node?.getAttribute) {
        const direct = node.getAttribute(name);
        if(direct != null && String(direct).trim() !== '') return String(direct).trim();
      }
    } catch(_e) {}
    return fallback == null ? '' : String(fallback || '').trim();
  }
  function actionBusOrderId(payload){
    return actionBusNodeAttr(payload, 'data-order-id', actionBusNodeAttr(payload, 'data-oid', payload?.orderId || ''));
  }
  function actionBusVehicleId(payload){
    return actionBusNodeAttr(payload, 'data-vehicle-id', actionBusNodeAttr(payload, 'data-vid', payload?.vehicleId || ''));
  }
  function actionBusVehicleTitle(payload){
    return actionBusNodeAttr(payload, 'data-vehicle-title', payload?.vehicleTitle || '');
  }
  function actionBusOpenOrder(orderId){
    const id = String(orderId || '').trim();
    if(!id) return actionBusRoute('myorders', 'action-order-empty');
    try { if(window.KaretaOrderActions?.openFull) return KaretaOrderActions.openFull(id); } catch(_e) {}
    try { if(window.openClientOrderModal) { openClientOrderModal(id); return false; } } catch(_e2) {}
    return actionBusRoute('myorders', 'action-order-fallback');
  }
  function actionBusOpenOrderChat(orderId){
    const id = String(orderId || '').trim();
    if(!id) return actionBusRoute('messages', 'action-order-chat-empty');
    try { if(window.KaretaOrderActions?.openChat) return KaretaOrderActions.openChat(id); } catch(_e) {}
    try { if(window.Messenger?.openByOrder) { Messenger.openByOrder(id); return false; } } catch(_e2) {}
    return actionBusRoute('messages', 'action-order-chat-fallback');
  }
  function actionBusOpenVehicleOrder(vehicleId, orderId){
    const vid = String(vehicleId || '').trim();
    const oid = String(orderId || '').trim();
    if(vid && oid) {
      try { if(window.KaretaOrderFlow?.open) return KaretaOrderFlow.open(vid, oid); } catch(_e) {}
      return actionBusRoute('cabinet:car:order:' + encodeURIComponent(vid) + ':' + encodeURIComponent(oid), 'action-vehicle-order');
    }
    return actionBusOpenOrder(oid);
  }
  function actionBusRun(rawAction, payload){
    const action = actionBusNormalize(rawAction);
    const data = payload || {};
    try { window.App?.closeTransientPanels?.(); } catch(_e) {}
    if(action === 'city') return servicesHeadCityModal();
    if(action === 'favorites') return actionBusRoute('favorites', 'action-favorites');
    if(action === 'notifications') {
      if(!S.user?.phone){
        try { requireAuth('open_myorders',{role:'client'}); }
        catch(_e) { try { window.App?.showAuth?.('cabinet:notifs'); } catch(_e2) {} }
        return false;
      }
      const res = actionBusRoute('cabinet:notifs', 'action-notifs');
      try { scheduleNotificationsRefresh?.({ force:true, reason:'action-bus-notifs' }); servicesHeadRefreshActions(document); } catch(_e) {}
      return res;
    }
    if(action === 'menu') { try { window.toggleDrawer?.(); } catch(_e) {} return false; }
    if(action === 'open_order') return actionBusOpenOrder(actionBusOrderId(data));
    if(action === 'vehicle_order') return actionBusOpenVehicleOrder(actionBusVehicleId(data), actionBusOrderId(data));
    if(action === 'chat_order') return actionBusOpenOrderChat(actionBusOrderId(data));
    if(action === 'review_order') { const oid = actionBusOrderId(data); try { if(oid && window.openServiceReviewModal) { openServiceReviewModal(oid); return false; } } catch(_e) {} return actionBusOpenOrder(oid); }
    if(action === 'parts_vehicle') { const vid = actionBusVehicleId(data); const title = actionBusVehicleTitle(data); try { if(window.KaretaOrderActions?.parts) return KaretaOrderActions.parts(vid, title); } catch(_e) {} return actionBusRoute('parts', 'action-parts-vehicle'); }
    if(action === 'service_vehicle') { const vid = actionBusVehicleId(data); const title = actionBusVehicleTitle(data); try { if(window.KaretaOrderActions?.service) return KaretaOrderActions.service(vid, title); } catch(_e) {} return actionBusRoute('services:quick', 'action-service-vehicle'); }
    if(action === 'notif_read') { try { markNotifRead(actionBusNodeAttr(data,'data-notif-id',''), actionBusNodeAttr(data,'data-notif-url','')); } catch(_e) {} return false; }
    if(action === 'notifs_read_all') { try { markAllNotifsRead(data?.node || null); } catch(_e) {} return false; }
    if(action === 'quick_request') return actionBusRoute('services:quick', 'action-quick');
    if(action === 'parts') return actionBusRoute('parts', 'action-parts');
    if(action === 'masters') return actionBusRoute('masters', 'action-masters');
    if(action === 'services') return actionBusRoute('services', 'action-services');
    if(action === 'sales') return actionBusRoute('services:tires', 'action-sales');
    if(action === 'about') return actionBusRoute('about', 'action-about');
    if(action === 'garage') { try { if(window.KaretaCabinetRoleNav?.go) return KaretaCabinetRoleNav.go('car'); } catch(_e) {} return actionBusRoute('cabinet:car', 'action-garage'); }
    if(action === 'profile') { try { if(window.KaretaCabinetRoleNav?.go) return KaretaCabinetRoleNav.go('profile'); } catch(_e) {} return actionBusRoute('cabinet:profile', 'action-profile'); }
    if(action === 'myorders') return actionBusRoute('myorders', 'action-orders');
    if(action === 'messages') return actionBusRoute('messages', 'action-messages');
    if(data.route) return actionBusRoute(data.route, 'action-route');
    return false;
  }
  function actionBusBind(){
    if(window.__KARETA_ACTION_BUS_BIND__) return;
    window.__KARETA_ACTION_BUS_BIND__ = true;
    document.addEventListener('click', function(ev){
      const node = ev.target?.closest?.('[data-k-action],[data-action-go],[data-head-action]');
      if(!node) return;
      const action = node.getAttribute('data-k-action') || node.getAttribute('data-action-go') || node.getAttribute('data-head-action') || '';
      if(!action) return;
      ev.preventDefault();
      ev.stopPropagation();
      if(typeof ev.stopImmediatePropagation === 'function') ev.stopImmediatePropagation();
      try { node.classList.add('kareta-action-tap'); setTimeout(()=>node.classList.remove('kareta-action-tap'), 220); } catch(_e) {}
      actionBusRun(action, {
        route: node.getAttribute('data-kroute') || node.getAttribute('data-route-go') || node.getAttribute('data-kareta-route') || '',
        orderId: node.getAttribute('data-order-id') || node.getAttribute('data-oid') || '',
        vehicleId: node.getAttribute('data-vehicle-id') || node.getAttribute('data-vid') || '',
        vehicleTitle: node.getAttribute('data-vehicle-title') || '',
        source: 'delegated-action',
        node
      });
    }, true);
  }
  window.KaretaActionBus = Object.assign(window.KaretaActionBus || {}, {
    normalize: actionBusNormalize,
    run: actionBusRun,
    route: actionBusRoute,
    bind: actionBusBind,
    openOrder: actionBusOpenOrder,
    openOrderChat: actionBusOpenOrderChat,
    openVehicleOrder: actionBusOpenVehicleOrder
  });
  actionBusBind();

  const SERVICES_MOBILE_HEAD_TITLES = Object.freeze({
    services:'Главная',
    masters:'Сервисы',
    quick:'Запись',
    parts:'Запчасти',
    sales:'Акции',
    about:'О нас',
    account:'Профиль',
    myorders:'Заказы',
    messages:'Чаты',
    cabinet:'Профиль',
    news:'Новости'
  });

  function servicesMobileHeadTitle(active='services', options={}){
    const opts = options || {};
    const explicit = String(opts.mobileTitle || opts.title || '').trim();
    if(explicit) return explicit;
    const page = String(opts.page || '').toLowerCase().trim();
    if(page && SERVICES_MOBILE_HEAD_TITLES[page]) return SERVICES_MOBILE_HEAD_TITLES[page];
    const key = String(active || 'services').toLowerCase().trim();
    return SERVICES_MOBILE_HEAD_TITLES[key] || 'Kareta';
  }

  function servicesDesktopChromeNav(active='services'){
    const is = (key)=> String(active || 'services') === key ? 'is-active' : '';
    return `<div class="services-desktop-chrome" data-k-desktop-header="stable" data-k-mobile-hidden="1" aria-hidden="true" hidden>
          <nav class="services-home-desktop-nav" data-k-desktop-nav="1" data-k-mobile-hidden="1" data-nav-level="desktop-primary" aria-hidden="true" hidden aria-label="Разделы главной">
            <button type="button" class="${is('services')}" data-services-nav-key="services" data-kroute="services">Главная</button>
            <button type="button" class="${is('masters')}" data-services-nav-key="masters" data-kroute="masters">Сервисы</button>
            <button type="button" class="${is('quick')}" data-services-nav-key="quick" data-kroute="services:quick">Запись онлайн</button>
            <button type="button" class="${is('parts')}" data-services-nav-key="parts" data-kroute="parts">Запчасти</button>
            <button type="button" class="${is('sales')}" data-services-nav-key="sales" data-kroute="services:tires">Акции</button>
            <button type="button" class="${is('about')}" data-services-nav-key="about" data-kroute="about">О нас</button>
            <button type="button" class="${is('account')}" data-services-nav-key="account" data-k-action="profile">Аккаунт</button>
          </nav>
        </div>`;
  }

  function servicesHomeHeadPersistent(active='services', options={}){
    const cityLabel = servicesHeadCityLabel();
    const favCount = servicesHeadFavoritesCount();
    const unread = servicesHeadUnreadCount();
    const mobileTitle = servicesMobileHeadTitle(active, options);
    const favBadge = favCount > 0 ? `<i class="services-head-action-badge">${favCount > 99 ? '99+' : favCount}</i>` : '';
    const notifBadge = `<i ${unread <= 0 ? 'hidden' : ''}>${unread > 99 ? '99+' : unread}</i>`;
    return `<header class="services-home-head" data-services-head-contract="single-shell" data-services-head-persistent="stable" data-k-mobile-header="stable" data-k-mobile-title="${escAttr(mobileTitle)}" data-k-header-split="mobile-only">
          <button class="services-home-brand" type="button" data-kroute="services" aria-label="Kareta.kz — на главную">
            <img class="services-home-logo" src="/assets/onboarding/kareta_logo_icon.png" alt="KARETA.KZ" loading="eager" onerror="this.onerror=null;this.src='/assets/onboarding/kareta_logo_full.png'">
            <span class="services-home-brand-text">Kareta.kz</span>
          </button>
          <div class="services-home-mobile-title" data-k-mobile-head-title="1" aria-live="polite">${escHtml(mobileTitle)}</div>
          <div class="services-home-head-actions" data-services-head-actions="1" data-kareta-action-scope="services-head">
            <button class="services-app-icon-btn services-home-loc" type="button" aria-label="Выбрать город" title="Город обслуживания" data-k-action="city" data-head-action="city"><span>${serviceMiniIconSvg('pin')}</span><b>${escHtml(cityLabel)}</b></button>
            <button class="services-app-icon-btn services-home-fav" type="button" aria-label="Избранное" title="Избранное" data-k-action="favorites" data-head-action="favorites"><span aria-hidden="true">♡</span>${favBadge}</button>
            <button class="services-app-icon-btn services-app-bell-btn services-home-bell" type="button" aria-label="Уведомления" title="Уведомления" data-k-action="notifications" data-head-action="notifications">${serviceMiniIconSvg('bell')}${notifBadge}</button>
            <button class="services-home-menu" type="button" aria-label="Меню" title="Меню" data-k-action="menu" data-head-action="menu"><span></span><span></span><span></span></button>
          </div>
        </header>`;
  }


    try { window.__KARETA_SERVICES_LAYOUT = true; } catch(_e) {}

  const SERVICES_HEAD_NAV_KEYS = ['services','masters','quick','parts','sales','about','account'];

  const KARETA_SHELL_BRANCH_CLASSES = Object.freeze(['k-main-shell--public','k-main-shell--account','k-main-shell--staff','k-main-shell--services']);

  function canonicalShellBranch(value){
    const v = String(value || '').toLowerCase().trim();
    if(v === 'services' || v === 'home' || v === 'client' || v === 'guest') return 'public';
    if(v === 'public' || v === 'account' || v === 'staff') return v;
    if(typeof routeLayoutLayer === 'function') return routeLayoutLayer(v);
    return 'public';
  }

  function shellBranchForElement(el, branch){
    const requested = canonicalShellBranch(branch);
    if(!el || !el.getAttribute) return requested;
    const id = String(el.id || '');
    if(id === 'services-lite-page') return 'public';
    const own = canonicalShellBranch(el.getAttribute('data-client-shell-kind') || el.getAttribute('data-k-shell-layer') || '');
    if(id === 'account-shell-page') return own === 'staff' ? 'staff' : 'account';
    if(el.classList?.contains('services-app-page--shell') && el.getAttribute('data-client-services-shell') === 'stable'){
      const explicit = String(el.getAttribute('data-client-shell-kind') || el.getAttribute('data-k-shell-layer') || '').trim();
      if(explicit) return canonicalShellBranch(explicit);
    }
    return requested;
  }

  function setExclusiveShellBranch(el, branch, source){
    if(!el || !el.classList) return el;
    const b = shellBranchForElement(el, branch);
    KARETA_SHELL_BRANCH_CLASSES.forEach(cls=>el.classList.remove(cls));
    el.classList.add('k-main-shell', 'k-main-shell--' + b);
    el.setAttribute('data-k-shell-layer', b);
    el.setAttribute('data-client-shell-kind', b);
    el.setAttribute('data-k-shell-exclusive','1');
    if(source) el.setAttribute('data-k-shell-branch-source', String(source));
    return el;
  }

  function connectedServicesShell(root=document.getElementById('app'), expectedBranch=null){
    if(!root) return null;
    const heads = root.querySelectorAll('.services-home-head');
    if(heads.length !== 1) return null;
    const head = heads[0];
    const phone = head.parentElement;
    const page = phone?.parentElement;
    if(!phone || !page || page.parentElement !== root) return null;
    if(!page.matches('.services-app-page--shell[data-client-services-shell="stable"]')) return null;
    if(!phone.matches('.services-app-phone.services-home[data-client-services-shell-body="stable"]')) return null;
    const branch = mountedShellBranchFromPage(page);
    if(expectedBranch && branch !== canonicalShellBranch(expectedBranch)) return null;
    return { root, head, phone, page, branch };
  }

  try {
    window.KaretaShellBranch = Object.assign(window.KaretaShellBranch || {}, {
      version:'stable',
      canonical:canonicalShellBranch,
      setExclusive:setExclusiveShellBranch,
      classes:KARETA_SHELL_BRANCH_CLASSES
    });
  } catch(_e) {}

  function mountedShellBranchFromPage(page){
    if(!page) return 'public';
    if(String(page.id || '') === 'services-lite-page') return 'public';
    const explicit = String(page.getAttribute?.('data-client-shell-kind') || page.getAttribute?.('data-k-shell-layer') || '').trim();
    if(String(page.id || '') === 'account-shell-page') return canonicalShellBranch(explicit || 'account');
    return canonicalShellBranch(explicit || 'public');
  }

  function freezeChromeShell(root=document.getElementById('app'), source='chrome-freeze'){
    try{
      const scope = root || document.getElementById('app');
      if(!scope) return null;
      scope.setAttribute('data-k-chrome-immutable','stable');
      scope.setAttribute('data-k-chrome-freeze-version','stable');
      const shell = scope.querySelector(':scope > .services-app-page--shell[data-client-services-shell="stable"]');
      if(!shell) return null;
      const branch = mountedShellBranchFromPage(shell);
      setExclusiveShellBranch(shell, branch, source);
      shell.classList.add('active');
      shell.setAttribute('data-k-chrome-shell','stable');
      shell.setAttribute('data-k-chrome-shell-id', shell.id || 'services-shell-page');
      const phone = shell.querySelector(':scope > .services-app-phone.services-home');
      if(phone){
        phone.setAttribute('data-client-shell-kind', branch);
        phone.setAttribute('data-k-shell-layer', branch);
        phone.setAttribute('data-k-chrome-frame','stable');
        phone.classList.add('k-main-frame');
      }
      const head = phone?.querySelector?.(':scope > .services-home-head') || shell.querySelector(':scope .services-home-head');
      if(head){
        head.setAttribute('data-k-chrome-head','stable');
        head.setAttribute('data-services-head-persistent','stable');
      }
      return shell;
    }catch(_e){ return null; }
  }

  function enforceMountedShellInvariant(root=document.getElementById('app'), source='invariant'){
    try{
      const scope = root || document.getElementById('app');
      if(!scope) return false;
      const shells = Array.from(scope.querySelectorAll(':scope > .services-app-page--shell[data-client-services-shell="stable"]'));
      shells.forEach(shell=>{
        const branch = mountedShellBranchFromPage(shell);
        setExclusiveShellBranch(shell, branch, source);
        shell.classList.add('active');
        shell.setAttribute('data-k-shell-exclusive','1');
        const phone = shell.querySelector(':scope > .services-app-phone.services-home');
        if(phone){
          phone.setAttribute('data-client-shell-kind', branch);
          phone.setAttribute('data-k-shell-layer', branch);
          phone.classList.add('k-main-frame');
        }
      });
      scope.setAttribute('data-k-shell-count', String(shells.length));
      scope.setAttribute('data-k-shell-conflict-count', '0');
      freezeChromeShell(scope, source + '-chrome');
      return true;
    }catch(_e){ return false; }
  }

  try {
    window.KaretaShellBranchStable = Object.assign(window.KaretaShellBranchStable || {}, {
      version:'stable',
      mountedBranch:mountedShellBranchFromPage,
      freezeChrome:freezeChromeShell,
      enforce:enforceMountedShellInvariant
    });
  } catch(_e) {}

  function servicesRoutePayload(active='services', bodyHtml='', branch='public', options={}){
    const key = SERVICES_HEAD_NAV_KEYS.includes(String(active || '')) ? String(active) : 'services';
    const shellBranch = canonicalShellBranch(branch);
    const mobileTitle = servicesMobileHeadTitle(key, options || {});
    return `<template data-services-route-payload="stable" data-services-active="${key}" data-services-shell-branch="${shellBranch}" data-services-mobile-title="${escAttr(mobileTitle)}">${String(bodyHtml ?? '')}</template>`;
  }

  function syncServicesHomeHeadActiveKey(head, active='services', options={}){
    if(!head) return;
    const key = SERVICES_HEAD_NAV_KEYS.includes(String(active || '')) ? String(active) : 'services';
    const navScope = head.closest('.services-app-phone.services-home') || head.parentElement || head;
    Array.from(navScope.querySelectorAll('.services-home-desktop-nav button')).forEach((button, index)=>{
      const buttonKey = String(button.getAttribute('data-services-nav-key') || SERVICES_HEAD_NAV_KEYS[index] || '');
      if(!button.hasAttribute('data-services-nav-key') && buttonKey) button.setAttribute('data-services-nav-key', buttonKey);
      const isActive = buttonKey === key;
      button.classList.toggle('is-active', isActive);
      if(isActive) button.setAttribute('aria-current','page');
      else button.removeAttribute('aria-current');
    });
    const title = servicesMobileHeadTitle(key, options || {});
    head.setAttribute('data-services-head-persistent','stable');
    head.setAttribute('data-k-mobile-header','stable');
    head.setAttribute('data-k-mobile-title', title);
    const mobileTitle = head.querySelector('.services-home-mobile-title');
    if(mobileTitle) mobileTitle.textContent = title;
  }

  function renderClientServicesShell(active='services', contentHtml='', options={}){
    const opts = options || {};
    const pageId = String(opts.id || 'services-shell-page').replace(/[^a-zA-Z0-9_-]/g,'') || 'services-shell-page';
    const pageExtra = opts.topShell ? ' services-top-shell' : '';
    const layout = String(opts.layout || 'single').replace(/[^a-zA-Z0-9_-]/g,'') || 'single';
    const phoneExtra = `${opts.persistent ? ' services-home--persistent' : ''} services-home--shell services-home--layout-${layout}`;
    const body = String(contentHtml ?? '');
    const aside = String(opts.asideHtml ?? '');
    const wrapContent = opts.wrapContent !== false;
    const bodyClass = String(opts.bodyClass || 'services-shell-content').replace(/[^a-zA-Z0-9_ -]/g,'') || 'services-shell-content';
    const shellKind = canonicalShellBranch(String(opts.shellKind || (pageId === 'account-shell-page' ? 'account' : 'public')).replace(/[^a-zA-Z0-9_-]/g,'') || 'public');
    // native unified shell. Single-column pages no longer get an extra grid wrapper.
    const contentClass = (bodyClass + ' k-main-content').replace(/\s+/g,' ').trim();
    const hasAside = !!aside;
    const needsGrid = hasAside || layout !== 'single';
    const shellBody = wrapContent
      ? `<div class="${contentClass}" data-shell-layout="${layout}" data-k-shell-single="${needsGrid ? '0' : '1'}">
          ${needsGrid
            ? `<div class="services-shell-layout services-shell-layout--${layout} k-main-grid">
                <main class="services-shell-main k-main-main" data-layout-reduced="0">${body}</main>
                ${aside ? `<aside class="services-shell-aside k-main-aside">${aside}</aside>` : ''}
              </div>`
            : `<main class="services-shell-main k-main-main" data-layout-reduced="single-route">${body}</main>`}
        </div>`
      : body;
    /* once the canonical services shell is mounted, render only route body.
       The persistent header and its shell are not generated again for top-menu transitions. */
    if(opts.bodyOnlyWhenMounted !== false && pageId === 'services-lite-page' && connectedServicesShell(document.getElementById('app'), shellKind)){
      return servicesRoutePayload(active, shellBody, shellKind, opts);
    }
    return `<div class="page services-app-page services-app-page--home services-app-page--shell${pageExtra} k-main-shell k-main-shell--${shellKind} k-route-shell active" data-client-services-shell="stable" data-client-shell-kind="${shellKind}" data-k-shell-layer="${shellKind}" data-k-shell-version="stable" data-k-chrome-shell="stable" data-k-shell-exclusive="1" id="${pageId}">
      <div class="services-app-phone services-home${phoneExtra} k-main-frame" data-client-services-shell-body="stable" data-client-shell-kind="${shellKind}" data-k-shell-layer="${shellKind}" data-k-chrome-frame="stable">
        ${servicesHomeHeadPersistent(active, opts)}
        ${servicesDesktopChromeNav(active)}
        ${shellBody}
      </div>
    </div>`;
  }

  function servicesMarkupHasTopHead(html){
    return /<header\b[^>]*class=[\"'][^\"']*\bservices-home-head\b/i.test(String(html || ''));
  }

  function withServicesTopMenu(html, active='services'){
    const body = String(html ?? '');
    if (servicesMarkupHasTopHead(body)) return body;
    /* all top-menu routes reuse the exact #services home shell.
       The page id, parent classes and header context stay unchanged; only the route body is replaced. */
    return renderClientServicesShell(active, body, {
      id:'services-lite-page',
      topShell:false,
      persistent:false,
      wrapContent:true,
      bodyClass:'services-shell-content services-top-shell__body services-shell-content--route',
      layout:'single',
      shellKind:'public'
    });
  }


  // shared top shell for account/workbench pages.
  // Reuses services-home-head above role-specific inner shells.
  function accountTopShellActive(active){
    const a = String(active || 'account').trim().toLowerCase();
    return SERVICES_HEAD_NAV_KEYS.includes(a) ? a : 'account';
  }
  // account shell owns the global top header. Some legacy pages, especially
  // My Orders, still render their own local reference header. Strip it only when the
  // page is mounted inside account shell to avoid duplicate tops in services-shell-main.
  function accountTopShellStripLegacyHeads(html, page){
    let out = String(html ?? '');
    const p = String(page || '').toLowerCase();
    if (p === 'myorders') {
      out = out.replace(/<header\s+class=["']myorders-ref-head["'][\s\S]*?<\/header>\s*/i, '');
    }
    return out;
  }

  function withAccountTopShell(html, opts={}){
    const options = opts || {};
    const page = String(options.page || 'account').replace(/[^a-zA-Z0-9_-]/g,'') || 'account';
    let body = String(html ?? '');
    if (servicesMarkupHasTopHead(body)) return body;
    body = accountTopShellStripLegacyHeads(body, page);
    const roleKey = (()=>{ try { return String((typeof role === 'function' ? role() : '') || effectiveRole?.() || S.user?.role || 'guest').toLowerCase(); } catch(_e){ return String(S.user?.role || 'guest').toLowerCase(); } })();
    const isStaff = !!options.staff || ['master','sto','admin','owner'].includes(roleKey);
    const isClientChrome = !isStaff && ['myorders','messages','cabinet','account'].includes(page);
    const shell = `<div class="account-top-shell account-top-shell--${escAttr(page)} ${isStaff ? 'account-top-shell--staff' : 'account-top-shell--client'}" data-account-top-shell="stable" data-account-page="${escAttr(page)}" data-account-role="${escAttr(roleKey)}" data-k-route-family="${isClientChrome ? 'client' : (isStaff ? 'staff' : 'account')}">${body}</div>`;
    /* client account routes (#myorders/#messages/#cabinet) must use the same
       immutable public chrome as #services and #parts. Only staff/admin panels keep a
       separate staff shell. This prevents #app/#services-lite-page class repacking and
       stops services-home-head from changing design/offsets between client routes. */
    if(isClientChrome){
      return renderClientServicesShell(accountTopShellActive(options.active), shell, {
        id:'services-lite-page',
        topShell:false,
        persistent:false,
        wrapContent:true,
        bodyClass:'services-shell-content services-shell-content--route-body services-shell-content--account services-shell-content--client-account',
        layout:'single',
        bodyOnlyWhenMounted:true,
        shellKind:'public',
        page,
        mobileTitle: servicesMobileHeadTitle(options.active || 'account', { page })
      });
    }
    return renderClientServicesShell(accountTopShellActive(options.active), shell, {
      id:'account-shell-page',
      topShell:true,
      persistent:true,
      wrapContent:true,
      bodyClass:'services-shell-content services-shell-content--route-body services-shell-content--account',
      layout:'single',
      bodyOnlyWhenMounted:false,
      shellKind:isStaff ? 'staff' : 'account',
      page,
      mobileTitle: servicesMobileHeadTitle(options.active || 'account', { page })
    });
  }
  window.withAccountTopShell = withAccountTopShell;

  // account shell layout contract guard.
  // The account shell already owns services-home-head and services-shell-main.
  // Nested routes must not behave like standalone pages with another .page/.spa-content/.container stack.
  function normalizeAccountShellLayout(root, pageKey, canonicalHash){
    const scope = root || document.getElementById('app');
    if(!scope) return;
    const shell = scope.querySelector('.account-top-shell');
    if(!shell) return;
    shell.setAttribute('data-layout-contract','stable');
    shell.setAttribute('data-layout-page', String(pageKey || shell.getAttribute('data-account-page') || 'account'));
    shell.setAttribute('data-layout-route', String(canonicalHash || location.hash || '').replace(/^#/,''));
    const directPages = Array.from(shell.children || []).filter(el => el && el.nodeType === 1 && el.classList && el.classList.contains('page'));
    directPages.forEach(el=>{
      el.classList.add('account-embedded-page');
      el.classList.remove('active');
      el.setAttribute('data-embedded-page','stable');
    });
    shell.querySelectorAll('.page .page, .spa-content .spa-content, .container .container').forEach(el=>{
      el.setAttribute('data-nested-layout-warning','stable');
    });
  }
  window.normalizeAccountShellLayout = normalizeAccountShellLayout;

  // one structural contract for public, client and staff main pages.
  // Rule: ROUTES choose the main branch, tier-2 navigation chooses a subsection, CSS owns the visual state.
  const KARETA_LAYOUT_BRANCH_RULES = Object.freeze({
    page: '#app > .k-main-shell > .k-main-frame > .services-home-head + .k-main-content > .k-main-grid > main.k-main-main > .k-main-page',
    account: 'account pages use the same outer services shell; inner route markup is embedded, not a new standalone page tree',
    modal: 'body > .k-modal-overlay > .k-modal-card > header/body/actions; modal never owns a route shell',
    nav1: 'tier-1 nav changes ROUTES and URL hash through App.go/nav helpers',
    nav2: 'tier-2 nav changes page:tab[:subtab] through KaretaUrlSync and aria-current',
    forbidden: ['versioned class names for layout', 'container inside container', 'duplicate class attributes', 'inline active colors'],
    cleanupBranch: {
      owner: 'frontend-layout',
      activeTaskSet: 'cleanup-main-shell-css-nav-modal-stable',
      sequence: ['css-layer-collapse', 'important-reduction', 'version-marker-removal', 'inline-style-extraction', 'account-shell-embedding', 'router-owned-navigation'],
      rule: 'each step must reduce one competing source of layout truth without creating new versioned CSS/JS filenames'
    }
  });

  function routeLayoutLayer(pageKey){
    const p = String(pageKey || '').toLowerCase();
    if(['master','sto_dashboard','admin','owner'].includes(p)) return 'staff';
    if(['cabinet','myorders','messages'].includes(p)) return 'account';
    return 'public';
  }
  function safeRouteClass(value){
    return String(value || 'page').toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'') || 'page';
  }
  function addClass(el, cls){
    if(el && cls) String(cls).split(/\s+/).filter(Boolean).forEach(c=>el.classList.add(c));
    return el;
  }
  function markPassThrough(el, reason){
    if(!el || el.nodeType !== 1) return false;
    el.setAttribute('data-layout-pass-through','stable');
    if(reason) el.setAttribute('data-layout-pass-through-reason', reason);
    addClass(el, 'k-layout-pass-through');
    return true;
  }
  function compactDuplicateContainers(scope){
    if(!scope) return 0;
    let count = 0;
    scope.querySelectorAll('.container > .container, .spa-content > .container > .container, .msng-page-content-wrap > .container.msng-page-content').forEach(el=>{
      const parent = el.parentElement;
      if(!parent || parent.id || parent.getAttribute('role')) return;
      const significant = Array.from(parent.childNodes || []).filter(n => n.nodeType === 1 || (n.nodeType === 3 && String(n.textContent||'').trim()));
      if(significant.length === 1){ markPassThrough(parent, 'duplicate-container-parent'); count++; }
      el.setAttribute('data-layout-depth','content-root');
      addClass(el, 'k-main-page k-main-section');
    });
    scope.querySelectorAll('.account-top-shell > .page.account-embedded-page').forEach(el=>{
      if(!el.id){ markPassThrough(el, 'account-embedded-page'); count++; }
      addClass(el, 'k-main-page');
    });
    scope.querySelectorAll('.account-top-shell :is(.spa-content,.msng-page-content-wrap)').forEach(el=>{
      markPassThrough(el, 'message-content-wrapper'); count++;
    });
    return count;
  }
  function normalizeModalContract(root){
    const scope = root || document;
    const overlays = new Set();
    scope.querySelectorAll('.cmodal-overlay,.k-overlay,.modal-overlay,.mmaster-overlay,#auth-overlay,#drawer-overlay,[data-modal-overlay]').forEach(el=>overlays.add(el));
    document.querySelectorAll('body > .cmodal-overlay,body > .k-overlay,body > .modal-overlay,body > .mmaster-overlay,body > [data-modal-overlay]').forEach(el=>overlays.add(el));
    overlays.forEach(el=>{
      addClass(el, 'k-modal-overlay');
      if(!el.getAttribute('data-modal-tier')) el.setAttribute('data-modal-tier', el.id === 'drawer-overlay' ? 'system' : 'overlay');
      const card = el.querySelector(':scope > .cmodal-card,:scope > .k-modal-card,:scope > .modal-card,:scope > .mmaster-panel,:scope > .auth-modal') || el.querySelector('.cmodal-card,.k-modal-card,.modal-card,.mmaster-panel,.auth-modal');
      if(card){
        addClass(card, 'k-modal-card');
        card.setAttribute('data-modal-card','stable');
        card.querySelectorAll('.cmodal-actions,.modal-actions,.auth-actions').forEach(a=>addClass(a, 'k-modal-actions'));
      }
    });
  }
  function isDesktopChromeNavViewport(){
    try{
      return !!(window.matchMedia && window.matchMedia('(min-width: 1024px) and (pointer: fine)').matches);
    }catch(_e){ return false; }
  }

  function enforceDesktopChromeNavVisibility(root){
    const scope = root || document;
    let count = 0;
    try{
      const desktop = isDesktopChromeNavViewport();
      scope.querySelectorAll('.services-home-desktop-nav').forEach(nav=>{
        count++;
        nav.setAttribute('data-k-desktop-nav','1');
        nav.setAttribute('data-k-mobile-hidden','1');
        nav.setAttribute('data-nav-level','desktop-primary');
        if(desktop){
          nav.hidden = false;
          nav.inert = false;
          nav.removeAttribute('aria-hidden');
          nav.style.removeProperty('display');
          nav.style.removeProperty('visibility');
          nav.style.removeProperty('position');
          nav.style.removeProperty('left');
          nav.style.removeProperty('width');
          nav.style.removeProperty('height');
          nav.classList.remove('k-nav-tier','k-nav-tier--primary','active','is-active','selected','open','is-open');
          nav.classList.add('services-home-desktop-nav--ready');
          nav.setAttribute('data-nav-level','desktop-primary');
          nav.setAttribute('data-k-mobile-hidden-state','off');
        }else{
          nav.hidden = true;
          nav.inert = true;
          nav.setAttribute('aria-hidden','true');
          nav.classList.remove('k-nav-tier','k-nav-tier--primary');
          nav.style.setProperty('display','none','important');
          nav.style.setProperty('visibility','hidden','important');
          nav.style.setProperty('position','absolute','important');
          nav.style.setProperty('left','-10000px','important');
          nav.style.setProperty('width','0','important');
          nav.style.setProperty('height','0','important');
          nav.setAttribute('data-k-mobile-hidden-state','on');
        }
      });
    }catch(_e){}
    return count;
  }

  function enforceMobileHeaderContract(root){
    const scope = root || document;
    try{
      const isMobile = !!(window.matchMedia && window.matchMedia('(max-width: 767px), (max-width: 920px) and (pointer: coarse)').matches);
      scope.querySelectorAll('.services-home-head[data-k-mobile-header]').forEach(head=>{
        head.setAttribute('data-k-mobile-header-contract','stable');
        head.querySelectorAll('.services-home-desktop-nav').forEach(nav=>{
          nav.setAttribute('data-k-desktop-nav','1');
          nav.setAttribute('data-k-mobile-hidden','1');
          nav.setAttribute('data-nav-level','desktop-primary');
          if(isMobile){
            nav.hidden = true;
            nav.inert = true;
            nav.setAttribute('aria-hidden','true');
            nav.classList.remove('k-nav-tier','k-nav-tier--primary');
            nav.style.setProperty('display','none','important');
            nav.style.setProperty('visibility','hidden','important');
            nav.style.setProperty('position','absolute','important');
            nav.style.setProperty('left','-10000px','important');
            nav.style.setProperty('width','0','important');
            nav.style.setProperty('height','0','important');
          }
        });
        if(isMobile){
          head.querySelectorAll('.services-home-loc,.services-home-fav').forEach(el=>{ el.hidden = true; el.setAttribute('aria-hidden','true'); });
          head.querySelectorAll('.services-home-bell,.services-home-menu').forEach(el=>{ el.hidden = false; el.removeAttribute('aria-hidden'); });
        }
      });
    }catch(_e){}
  }

  function normalizeTwoTierNavContract(root){
    const scope = root || document;
    const primary = ['#bottom-nav','.drawer-links','.admin-nav','.owner-tabs','.master-tabs'];
    primary.forEach(sel=>scope.querySelectorAll(sel).forEach(el=>{
      if(el.matches && el.matches('.services-home-desktop-nav')){
        enforceDesktopChromeNavVisibility(el.parentNode || scope);
        return;
      }
      el.setAttribute('data-nav-level','primary');
      addClass(el, 'k-nav-tier k-nav-tier--primary');
    }));
    const secondary = ['.master-work-subtabs','.master-cabinet-tile-nav','[data-subtabs]','.cab-tabs','.kr-tabs','.myorders-tabs'];
    secondary.forEach(sel=>scope.querySelectorAll(sel).forEach(el=>{
      el.setAttribute('data-nav-level','secondary');
      addClass(el, 'k-nav-tier k-nav-tier--secondary');
    }));
    scope.querySelectorAll('.k-nav-tier :is(button,a,[role="tab"],[data-subtab],[data-mtab],.owner-tab,.admin-nav-item,.cab-tab,.kr-tab)').forEach(item=>{
      const active = item.classList.contains('active') || item.classList.contains('is-active') || item.getAttribute('aria-selected') === 'true';
      if(active) item.setAttribute('aria-current','page');
      else if(item.getAttribute('aria-current') === 'page') item.removeAttribute('aria-current');
    });
  }

  // stable route chrome geometry lock.
  // The route may change content, but top header, bottom nav and tier-2 nav keep invariant geometry.
  let routeGeometryLockTimer = 0;
  function syncChromeGeometry(){
    try{
      const root = document.documentElement;
      const wide = window.matchMedia && window.matchMedia('(min-width: 768px)').matches;
      const desktop = window.matchMedia && window.matchMedia('(min-width: 1024px)').matches;
      const bnavH = wide ? '78px' : '72px';
      const bnavBottom = wide ? '24px' : 'max(10px, env(safe-area-inset-bottom,0px))';
      const bnavMax = desktop ? '820px' : (wide ? '760px' : '430px');
      root.style.setProperty('--k-bnav-h-stable', bnavH);
      root.style.setProperty('--k-bnav-bottom-stable', bnavBottom);
      root.style.setProperty('--k-bnav-max-stable', bnavMax);
      root.style.setProperty('--bottom-nav-h', bnavH);
      root.style.setProperty('--bnav-bar', bnavH);
      root.style.setProperty('--bnav-ref-h', bnavH);
      root.style.setProperty('--bnav-h', 'calc(' + bnavH + ' + env(safe-area-inset-bottom,0px))');
      root.style.setProperty('--ui-bottom-nav-h', bnavH);
      root.style.setProperty('--ui-bnav-item-h', 'calc(' + bnavH + ' - 18px)');
      const inner = document.getElementById('bottomNavInner');
      const nav = document.getElementById('bottom-nav');
      if(inner){
        const count = inner.querySelectorAll('.bnav-item').length || Number(inner.dataset.count || 0) || 0;
        inner.dataset.count = String(count);
        if(nav) nav.setAttribute('data-count', String(count));
      }
      document.querySelectorAll('.bnav-item').forEach(btn=>{
        const active = btn.classList.contains('active') || btn.classList.contains('is-active');
        if(active) btn.setAttribute('aria-current','page');
        else if(btn.getAttribute('aria-current') === 'page') btn.removeAttribute('aria-current');
      });
      const app = document.getElementById('app');
      if(app){
        app.setAttribute('data-kareta-layout','stable');
        app.setAttribute('data-kareta-layout-mode','unified-shell');
        if(!app.getAttribute('data-kareta-layout-version')) app.setAttribute('data-kareta-layout-version','stable');
        app.setAttribute('data-k-chrome-stable','stable');
      }
      document.body?.setAttribute('data-k-chrome-stable','stable');
      try{ enforceDesktopChromeNavVisibility(document); enforceMobileHeaderContract(document); }catch(_e){}
    }catch(_e){}
  }
  function beginRouteGeometryLock(pageKey, canonicalHash){
    try{
      clearTimeout(routeGeometryLockTimer);
      syncChromeGeometry();
      document.body?.classList.add('k-route-switching');
      const app = document.getElementById('app');
      if(app){
        const lockedHeight = Math.max(Math.ceil(app.getBoundingClientRect?.().height || 0), app.offsetHeight || 0, window.innerHeight || 0);
        if(lockedHeight > 0){
          app.style.setProperty('--k-route-prev-app-h', lockedHeight + 'px');
          app.setAttribute('data-k-route-locked-h', String(lockedHeight));
        }
        app.setAttribute('data-k-route-switching','1');
        app.setAttribute('data-kareta-next-route', safeRouteClass(pageKey || 'home'));
        app.setAttribute('data-kareta-next-hash', String(canonicalHash || location.hash || '').replace(/^#/,''));
      }
    }catch(_e){}
  }
  function endRouteGeometryLock(){
    try{
      const release = ()=>{
        try{ syncChromeGeometry(); }catch(_e){}
        document.body?.classList.remove('k-route-switching');
        const app = document.getElementById('app');
        if(app){
          app.removeAttribute('data-k-route-switching');
          app.removeAttribute('data-kareta-next-route');
          app.removeAttribute('data-kareta-next-hash');
          app.removeAttribute('data-k-route-locked-h');
          app.style.removeProperty('--k-route-prev-app-h');
        }
      };
      if(typeof requestAnimationFrame === 'function') requestAnimationFrame(()=>requestAnimationFrame(release));
      else routeGeometryLockTimer = setTimeout(release, 32);
    }catch(_e){}
  }
  try{
    window.enforceDesktopChromeNavVisibility = enforceDesktopChromeNavVisibility;
    window.enforceMobileHeaderContract = enforceMobileHeaderContract;
    window.syncChromeGeometry = syncChromeGeometry;
    window.beginRouteGeometryLock = beginRouteGeometryLock;
    window.endRouteGeometryLock = endRouteGeometryLock;
    if(typeof addEventListener === 'function'){
      addEventListener('resize', ()=>{ clearTimeout(routeGeometryLockTimer); routeGeometryLockTimer = setTimeout(syncChromeGeometry, 80); }, { passive:true });
      addEventListener('orientationchange', ()=>{ clearTimeout(routeGeometryLockTimer); routeGeometryLockTimer = setTimeout(syncChromeGeometry, 120); }, { passive:true });
    }
  }catch(_e){}

  function primeMainLayoutState(root, pageKey, canonicalHash){
    const scope = root || document.getElementById('app');
    if(!scope) return false;
    const p = safeRouteClass(pageKey || window._karetaPage || 'home');
    const layer = routeLayoutLayer(p);
    scope.setAttribute('data-kareta-layout','stable');
    scope.setAttribute('data-kareta-layout-version','stable');
    scope.setAttribute('data-kareta-layout-mode','unified-shell');
    scope.setAttribute('data-kareta-route', p);
    scope.setAttribute('data-kareta-route-layer', layer);
    scope.setAttribute('data-kareta-hash', String(canonicalHash || location.hash || '').replace(/^#/,''));
    try {
      document.body.setAttribute('data-k-layout','stable');
      document.body.setAttribute('data-k-route-layer', layer);
      document.body.classList.toggle('k-route-public', layer === 'public');
      document.body.classList.toggle('k-route-account', layer === 'account');
      document.body.classList.toggle('k-route-staff', layer === 'staff');
    } catch(_e) {}
    try { syncChromeGeometry(); } catch(_e) {}
    return true;
  }
  window.primeMainLayoutState = primeMainLayoutState;

  function normalizeMainPageLayout(root, pageKey, canonicalHash){
    const scope = root || document.getElementById('app');
    if(!scope) return false;
    const p = safeRouteClass(pageKey || window._karetaPage || 'home');
    const layer = routeLayoutLayer(p);
    scope.setAttribute('data-kareta-layout','stable');
    scope.setAttribute('data-kareta-layout-version','stable');
    scope.setAttribute('data-kareta-layout-mode','unified-shell');
    scope.setAttribute('data-kareta-route', p);
    scope.setAttribute('data-kareta-route-layer', layer);
    scope.setAttribute('data-kareta-hash', String(canonicalHash || location.hash || '').replace(/^#/,''));
    try {
      document.body.setAttribute('data-k-layout','stable');
      document.body.setAttribute('data-k-route-layer', layer);
      document.body.classList.toggle('k-route-public', layer === 'public');
      document.body.classList.toggle('k-route-account', layer === 'account');
      document.body.classList.toggle('k-route-staff', layer === 'staff');
    } catch(_e) {}
    scope.querySelectorAll(':scope > .services-app-page--shell[data-client-services-shell="stable"]').forEach(el=>setExclusiveShellBranch(el, mountedShellBranchFromPage(el), 'normalize-main-layout'));
    scope.querySelectorAll('.services-app-phone').forEach(el=>addClass(el, 'k-main-frame'));
    scope.querySelectorAll('.services-shell-content').forEach(el=>addClass(el, 'k-main-content'));
    scope.querySelectorAll('.services-shell-layout').forEach(el=>addClass(el, 'k-main-grid'));
    scope.querySelectorAll('.services-shell-main').forEach(el=>{
      addClass(el, 'k-main-main');
      el.setAttribute('data-main-route', p);
    });
    scope.querySelectorAll('.account-top-shell').forEach(el=>{
      addClass(el, 'k-main-account k-main-page');
      el.setAttribute('data-main-layer', layer);
    });
    scope.querySelectorAll('.services-shell-main > :is(.page,.spa-page,.kcab-page,.myorders-ref-page,.parts-reference,.masters-reference,.messages-page--embedded,.msng-full-page--embedded), .account-top-shell > :is(.page,.spa-page,.kcab-page,.myorders-ref-page,.messages-page--embedded,.msng-full-page--embedded)').forEach(el=>{
      addClass(el, 'k-main-page k-main-page--' + p);
      el.setAttribute('data-main-page', p);
    });
    const reduced = compactDuplicateContainers(scope);
    normalizeTwoTierNavContract(scope);
    normalizeTwoTierNavContract(document);
    normalizeModalContract(scope);
    try { syncChromeGeometry(); } catch(_e) {}
    try { window.KaretaLayoutRules = Object.assign(window.KaretaLayoutRules || {}, { version:'stable', rules:KARETA_LAYOUT_BRANCH_RULES, normalize:normalizeMainPageLayout, compactedLastRun:reduced }); } catch(_e) {}
    return true;
  }
  window.normalizeMainPageLayout = normalizeMainPageLayout;

  // deeper layout audit and finalizer.
  // Goal: one route shell, one content shell, one page body. Everything else is passive.
  function reduceSingleColumnShell(scope){
    if(!scope) return 0;
    let reduced = 0;
    scope.querySelectorAll('.services-shell-content[data-shell-layout="single"] > .services-shell-layout--single').forEach(grid=>{
      const hasAside = !!grid.querySelector(':scope > .services-shell-aside');
      const main = grid.querySelector(':scope > .services-shell-main');
      if(!hasAside && main){
        markPassThrough(grid, 'single-column-grid-wrapper');
        main.setAttribute('data-layout-reduced','legacy-single-grid');
        reduced++;
      }
    });
    scope.querySelectorAll('.services-shell-main > :is(.page,.spa-page):only-child, .account-top-shell > :is(.page,.spa-page):only-child').forEach(pageEl=>{
      addClass(pageEl, 'k-main-page');
      pageEl.setAttribute('data-route-body','stable');
    });
    return reduced;
  }

  function auditLayoutDepth(root, pageKey, canonicalHash){
    const scope = root || document.getElementById('app');
    if(!scope) return { depth:0, over:0, containers:0 };
    const layoutSel = '.page,.spa-page,.container,.spa-content,.services-shell-layout,.services-shell-content,.services-shell-main,.account-top-shell,.msng-page-content-wrap,.msng-page-content,.k-main-shell,.k-main-frame,.k-main-content,.k-main-grid,.k-main-main,.k-main-page';
    let maxDepth = 0, over = 0, containers = 0;
    scope.querySelectorAll(layoutSel).forEach(el=>{
      let depth = 0;
      let n = el.parentElement;
      while(n && n !== scope){
        if(n.matches && n.matches(layoutSel)) depth++;
        n = n.parentElement;
      }
      maxDepth = Math.max(maxDepth, depth);
      if(el.classList && el.classList.contains('container')) containers++;
      if(depth > 7){
        el.setAttribute('data-layout-overdepth','1');
        over++;
      } else if(el.hasAttribute('data-layout-overdepth')) {
        el.removeAttribute('data-layout-overdepth');
      }
    });
    scope.setAttribute('data-layout-depth-max', String(maxDepth));
    scope.setAttribute('data-layout-overdepth-count', String(over));
    scope.setAttribute('data-layout-container-count', String(containers));
    scope.setAttribute('data-layout-audit-route', safeRouteClass(pageKey || window._karetaPage || 'home'));
    scope.setAttribute('data-layout-audit-hash', String(canonicalHash || location.hash || '').replace(/^#/, ''));
    try{
      window.KaretaLayoutAudit = { version:'stable', depth:maxDepth, overdepth:over, containers:containers, route:scope.getAttribute('data-layout-audit-route'), hash:scope.getAttribute('data-layout-audit-hash'), at:Date.now() };
    }catch(_e){}
    return { depth:maxDepth, over:over, containers:containers };
  }

  function finalizeRouteLayout(root, pageKey, canonicalHash){
    const scope = root || document.getElementById('app');
    if(!scope) return false;
    const p = safeRouteClass(pageKey || window._karetaPage || 'home');
    const layer = routeLayoutLayer(p);
    scope.setAttribute('data-kareta-layout-version','stable');
    scope.setAttribute('data-kareta-layout-mode','unified-shell');
    scope.setAttribute('data-k-shell-owner','router');
    scope.querySelectorAll(':scope > .services-app-page--shell').forEach(el=>setExclusiveShellBranch(el, mountedShellBranchFromPage(el), 'finalize-route-layout'));
    scope.querySelectorAll('.services-shell-content[data-k-shell-single="1"] > .services-shell-main').forEach(main=>{
      addClass(main, 'k-main-main');
      main.setAttribute('data-shell-main','single');
    });
    const reduced = reduceSingleColumnShell(scope);
    enforceMountedShellInvariant(scope, 'finalize-route-layout');
    normalizeTwoTierNavContract(scope);
    normalizeModalContract(scope);
    const audit = auditLayoutDepth(scope, p, canonicalHash);
    try{ syncChromeGeometry(); }catch(_e){}
    try{
      window.KaretaLayoutRules = Object.assign(window.KaretaLayoutRules || {}, {
        version:'stable',
        activeLayer:layer,
        lastReducedSingleShells:reduced,
        lastAudit:audit,
        finalize:finalizeRouteLayout,
        audit:auditLayoutDepth
      });
    }catch(_e){}
    return true;
  }
  window.auditLayoutDepth = auditLayoutDepth;
  window.finalizeRouteLayout = finalizeRouteLayout;


  // client cabinet blank-screen guard.
  // If renderCabinet() throws or returns markup hidden by legacy role flags, render a minimal
  // client cabinet instead of leaving only services-home-head on screen.
  function clientCabinetFallback(reason){
    const u = S.user || {};
    const name = String(u.name || 'Клиент').trim() || 'Клиент';
    const phone = String(u.phone || '').trim();
    const city = String(u.city || '').trim();
    try{
      document.body?.classList.remove('kareta-role-cabinet-legacy');
      document.body?.classList.add('kareta-role-cabinet-client','kareta-cabinet-client-safe');
    }catch(_e){}
    return `<div class="page kcab-page kcab-page--home client-cabinet-safe" data-kcab-section="home" data-kcab-level="1" data-cabinet-safe="stable">
      <section class="kcab-shell">
        <div class="kcab-phone">
          <header class="kcab-head">
            <div class="kcab-head-left"><div><h1>Профиль</h1><p>Личный кабинет клиента KARETA.KZ</p></div></div>
            <div class="kcab-head-actions"><button type="button" class="kcab-logout" id="logoutBtn">Выйти</button></div>
          </header>
          <section class="kcab-user-card">
            <span class="kcab-avatar"><b>${escHtml((name[0] || 'К').toUpperCase())}</b></span>
            <span class="kcab-user-main"><strong>${escHtml(name)}</strong><em>${escHtml(phone ? formatPhone(phone) : 'Телефон не указан')}</em><small>${escHtml(city || 'Город не указан')}</small></span>
            <button type="button" class="kcab-edit" data-kroute="cabinet:profile:edit">Изменить</button>
          </section>
          <section class="kcab-section"><h2>Быстрые разделы</h2><div class="kcab-grid">
            <button type="button" class="kcab-tile" data-kroute="cabinet:car"><span>▱</span><b>Мои автомобили</b><small>Гараж и карточки машин</small></button>
            <button type="button" class="kcab-tile" data-kroute="cabinet:history"><span>▤</span><b>История</b><small>Заявки и сервисная книжка</small></button>
            <button type="button" class="kcab-tile" data-kroute="cabinet:notifs"><span>○</span><b>Напоминания</b><small>Уведомления и сроки ТО</small></button>
            <button type="button" class="kcab-tile" data-kroute="services:quick"><span>+</span><b>Записаться</b><small>Быстрая заявка</small></button>
          </div></section>
          <section class="kcab-empty client-cabinet-safe__note"><span>!</span><b>Кабинет открыт в безопасном режиме</b><p>Основной рендер не отдал контент. Навигация сохранена, можно перейти в гараж, историю или создать заявку.</p><small>${escHtml(reason || 'render fallback')}</small></section>
        </div>
      </section>
    </div>`;
  }

  function cabinetMarkupLooksValid(html){
    const body = String(html || '').trim();
    if(!body) return false;
    return /\b(kcab-page|cab-locked|cabinet-ref|cab-hero|route-role-fallback|client-cabinet-safe)\b/.test(body);
  }

  function renderCabinetSafe(){
    const roleKey = String(S.user?.role || 'guest').toLowerCase();
    try{
      // Client cabinet must not inherit stale staff/legacy body flags from previous routes.
      if(roleKey === 'client'){
        try{ document.body?.classList.remove('kareta-role-cabinet-legacy'); }catch(_e){}
        try{ document.body?.classList.add('kareta-role-cabinet-client'); }catch(_e){}
      }
      const html = renderCabinet();
      if(cabinetMarkupLooksValid(html)) return html;
      console.warn('[r66e] empty/invalid cabinet markup, fallback used', { role:roleKey, htmlLen:String(html||'').length });
      return clientCabinetFallback('empty cabinet markup');
    }catch(e){
      console.error('[r66e] renderCabinet failed, fallback used', e);
      return clientCabinetFallback(String(e && e.message || e || 'render error'));
    }
  }
  window.renderCabinetSafe = renderCabinetSafe;


  function ensureCabinetContentVisible(pageKey, canonicalHash){
    if(String(pageKey || '') !== 'cabinet') return;
    const app = document.getElementById('app');
    if(!app) return;
    const main = app.querySelector('.services-shell-main');
    const hasContent = !!app.querySelector('.kcab-page, .cab-locked, .cabinet-ref, .cab-hero, .client-cabinet-safe');
    if(hasContent) return;
    console.warn('[r66e] cabinet committed without content, injecting safe fallback', { canonicalHash });
    const safe = document.createElement('div');
    safe.innerHTML = `<div class="account-top-shell account-top-shell--client" data-account-top-shell="stable" data-account-page="cabinet" data-account-role="client">${clientCabinetFallback('committed without content')}</div>`;
    if(main) main.replaceChildren(...Array.from(safe.childNodes));
    else app.appendChild(safe);
  }
  window.ensureCabinetContentVisible = ensureCabinetContentVisible;

  /* r64h/r64i — preserve the real services-home-head DOM node and keep its
     canonical home-shell parents immutable between top-menu routes. Incoming route HTML
     is parsed off-DOM; only content below the connected header is replaced. */
  const servicesHeadCommitStats = {
    commits:0, preserved:0, routePayload:0, bodyPatched:0, immutableShell:0, moved:0, replaced:0,
    lastSource:'', lastMode:'replace', lastPreserved:false
  };

  function syncServicesHomeHeadState(currentHead, nextHead){
    if(!currentHead || !nextHead) return;
    const nextNavScope = nextHead.closest?.('.services-app-phone.services-home') || nextHead.parentElement || nextHead;
    const nextButtons = Array.from(nextNavScope.querySelectorAll('.services-home-desktop-nav button'));
    const activeIndex = nextButtons.findIndex(button=>button.classList.contains('is-active'));
    const activeButton = activeIndex >= 0 ? nextButtons[activeIndex] : null;
    const activeKey = String(activeButton?.getAttribute('data-services-nav-key') || SERVICES_HEAD_NAV_KEYS[activeIndex] || 'services');
    syncServicesHomeHeadActiveKey(currentHead, activeKey, { mobileTitle: nextHead.getAttribute('data-k-mobile-title') || nextHead.querySelector('.services-home-mobile-title')?.textContent || '' });
  }

  function syncElementAttributes(current, next){
    if(!current || !next) return;
    Array.from(current.attributes || []).forEach(attr=>{
      if(!next.hasAttribute(attr.name)) current.removeAttribute(attr.name);
    });
    Array.from(next.attributes || []).forEach(attr=> current.setAttribute(attr.name, attr.value));
  }

  function patchConnectedServicesShell(root, currentHead, nextHead, template){
    const currentPhone = currentHead?.parentElement;
    const nextPhone = nextHead?.parentElement;
    const currentPage = currentPhone?.parentElement;
    const nextPage = nextPhone?.parentElement;
    const nextTopElements = Array.from(template.content.children || []);
    const compatible = !!(
      currentPhone && nextPhone && currentPage && nextPage &&
      currentPage.parentElement === root && nextPage.parentNode === template.content &&
      root.children.length === 1 && nextTopElements.length === 1 &&
      currentPage.matches('.services-app-page--shell') &&
      nextPage.matches('.services-app-page--shell') &&
      currentPhone.matches('.services-app-phone.services-home') &&
      nextPhone.matches('.services-app-phone.services-home')
    );
    if(!compatible) return false;

    syncServicesHomeHeadState(currentHead, nextHead);

    /* r64i immutable shell: top-menu routes intentionally render with identical
       page/phone wrappers. Do not touch their runtime attributes/classes (notably
       .active), otherwise the connected menu can still blink despite preserving its node. */
    const shellKindStable = (el)=> mountedShellBranchFromPage(el);
    const immutableShellStable = !!(
      currentPage.getAttribute('data-client-services-shell') === 'stable' &&
      nextPage.getAttribute('data-client-services-shell') === 'stable' &&
      currentPhone.getAttribute('data-client-services-shell-body') === 'stable' &&
      nextPhone.getAttribute('data-client-services-shell-body') === 'stable' &&
      shellKindStable(currentPage) === shellKindStable(nextPage)
    );
    if(immutableShellStable){
      servicesHeadCommitStats.immutableShell += 1;
    } else {
      syncElementAttributes(currentPage, nextPage);
      syncElementAttributes(currentPhone, nextPhone);
    }

    setExclusiveShellBranch(currentPage, shellKindStable(nextPage), 'commit-body-patch');
    currentPhone.setAttribute('data-client-shell-kind', shellKindStable(nextPhone));
    currentPhone.setAttribute('data-k-shell-layer', shellKindStable(nextPhone));

    const nextBodyNodes = Array.from(nextPhone.childNodes).filter(node=>node !== nextHead);
    Array.from(currentPhone.childNodes).forEach(node=>{ if(node !== currentHead) node.remove(); });
    nextBodyNodes.forEach(node=> currentPhone.appendChild(node));
    return true;
  }

  function patchServicesRoutePayload(root, payload){
    if(!payload || payload.tagName !== 'TEMPLATE') return false;
    const payloadBranch = canonicalShellBranch(payload.getAttribute('data-services-shell-branch') || 'public');
    const shell = connectedServicesShell(root, payloadBranch);
    if(!shell) return false;
    setExclusiveShellBranch(shell.page, payloadBranch, 'route-payload');
    shell.phone.setAttribute('data-client-shell-kind', payloadBranch);
    shell.phone.setAttribute('data-k-shell-layer', payloadBranch);
    syncServicesHomeHeadActiveKey(shell.head, payload.getAttribute('data-services-active') || 'services', { mobileTitle: payload.getAttribute('data-services-mobile-title') || '' });

    let desktopChrome = shell.phone.querySelector(':scope > .services-desktop-chrome');
    if(!desktopChrome){
      const tmp = document.createElement('template');
      tmp.innerHTML = servicesDesktopChromeNav(payload.getAttribute('data-services-active') || 'services');
      desktopChrome = tmp.content.firstElementChild;
      shell.phone.insertBefore(desktopChrome, shell.head.nextSibling);
    }
    const oldBodyNodes = Array.from(shell.phone.childNodes).filter(node=>node !== shell.head && node !== desktopChrome);
    const bodyFragment = document.createDocumentFragment();
    Array.from(payload.content.childNodes).forEach(node=>bodyFragment.appendChild(node));
    const anchor = document.createComment('services-route-body');
    shell.phone.insertBefore(anchor, desktopChrome.nextSibling);
    oldBodyNodes.forEach(node=>node.remove());
    shell.phone.insertBefore(bodyFragment, anchor);
    anchor.remove();
    return true;
  }

  function commitAppRouteHtml(root, routeHtml, meta={}){
    if(!root) return false;
    const html = String(routeHtml ?? '');
    const source = String(meta?.source || 'route');
    const template = document.createElement('template');
    template.innerHTML = html;

    const currentHeads = root.querySelectorAll('.services-home-head');
    const nextHeads = template.content.querySelectorAll('.services-home-head');
    const payloads = template.content.querySelectorAll('template[data-services-route-payload="stable"]');
    const directPayload = payloads.length === 1 && template.content.childElementCount === 1 && payloads[0].parentNode === template.content ? payloads[0] : null;
    let preserved = false;
    let mode = 'replace';

    if(directPayload && patchServicesRoutePayload(root, directPayload)){
      preserved = true;
      mode = 'route-payload';
    } else if(currentHeads.length === 1 && nextHeads.length === 1){
      const currentHead = currentHeads[0];
      const nextHead = nextHeads[0];
      if(patchConnectedServicesShell(root, currentHead, nextHead, template)){
        preserved = true;
        mode = 'body-patch';
      } else {
        const currentBranch = mountedShellBranchFromPage(currentHead?.parentElement?.parentElement);
        const nextBranch = mountedShellBranchFromPage(nextHead?.parentElement?.parentElement);
        if(currentBranch === nextBranch){
          syncServicesHomeHeadState(currentHead, nextHead);
          nextHead.replaceWith(currentHead);
          preserved = true;
          mode = 'node-move';
        }
      }
    }

    if(mode !== 'body-patch' && mode !== 'route-payload'){
      if(typeof root.replaceChildren === 'function') root.replaceChildren(template.content);
      else { root.innerHTML = ''; root.appendChild(template.content); }
    }

    try{
      const mountedShell = root.querySelector(':scope > .services-app-page--shell[data-client-services-shell="stable"]');
      if(mountedShell){
        const mountedBranch = canonicalShellBranch(mountedShell.getAttribute('data-client-shell-kind') || mountedShell.getAttribute('data-k-shell-layer') || (mountedShell.id === 'account-shell-page' ? 'account' : 'public'));
        setExclusiveShellBranch(mountedShell, mountedBranch, 'commit-final');
        const mountedPhone = mountedShell.querySelector(':scope > .services-app-phone.services-home');
        if(mountedPhone){
          mountedPhone.setAttribute('data-client-shell-kind', mountedBranch);
          mountedPhone.setAttribute('data-k-shell-layer', mountedBranch);
        }
      }
    }catch(_e){}
    try{ enforceMountedShellInvariant(root, 'commit-app-route'); }catch(_e){}

    servicesHeadCommitStats.commits += 1;
    servicesHeadCommitStats.lastSource = source;
    servicesHeadCommitStats.lastMode = mode;
    servicesHeadCommitStats.lastPreserved = preserved;
    if(preserved) servicesHeadCommitStats.preserved += 1;
    if(mode === 'route-payload') servicesHeadCommitStats.routePayload += 1;
    else if(mode === 'body-patch') servicesHeadCommitStats.bodyPatched += 1;
    else if(mode === 'node-move') servicesHeadCommitStats.moved += 1;
    else servicesHeadCommitStats.replaced += 1;
    try { afterServicesRouteCommit(mode, source); } catch(_e) {}
    if(window.__DEV__) console.debug('[ServicesHead r64j]', mode, source, servicesHeadCommitStats);
    return preserved;
  }

  try {
    const routeRendererApi = {
      commit: commitAppRouteHtml,
      stats: servicesHeadCommitStats
    };
    window.KaretaRouteRenderer = Object.assign(window.KaretaRouteRenderer || {}, routeRendererApi);
    window.KaretaRouteRendererStable = Object.assign(window.KaretaRouteRendererStable || {}, routeRendererApi);
    window.KaretaRouteRendererLegacy = Object.assign(window.KaretaRouteRendererLegacy || {}, routeRendererApi);
    window.KaretaRouteRendererAlt = Object.assign(window.KaretaRouteRendererAlt || {}, routeRendererApi);
  } catch(_e) {}

