  function mastersServiceById(cat, itemId){
    const catalog = mastersServiceCatalog();
    const c = String(cat || '').trim();
    const id = String(itemId || '').trim();
    return catalog.services.find(x=>String(x.cat)===c && String(x.id)===id) || catalog.services.find(x=>String(x.cat)===c) || catalog.services[0] || null;
  }
  function mastersServiceCategory(cat){
    const catalog = mastersServiceCatalog();
    const c = String(cat || '').trim();
    return catalog.categories.find(x=>String(x.key)===c) || catalog.categories[0] || {key:'repair', label:'Ремонт', icon:'repair', desc:''};
  }
  function mastersServiceCounts(){
    const catalog = mastersServiceCatalog();
    return catalog.services.reduce((acc, x)=>{ const k=String(x.cat||''); acc[k]=(acc[k]||0)+1; return acc; }, { all:catalog.services.length });
  }
  function mastersDirectoryOpenService(cat, itemId){
    const service = mastersServiceById(cat, itemId);
    if(!service){ try{ window._showToast?.('Услуга не найдена','error'); }catch(_e){} return false; }
    const category = mastersServiceCategory(service.cat);
    try {
      if(typeof servicesRequestDefaultState === 'function' && typeof servicesRequestSave === 'function' && typeof servicesRequestOpen === 'function'){
        const base = servicesRequestDefaultState(service.cat, service.id);
        const st = Object.assign(base, {
          cat:String(service.cat || 'repair'),
          item:String(service.id || 'custom'),
          title:String(service.title || 'Услуга'),
          categoryTitle:String(category.label || 'Услуга'),
          price:String(service.price || 'по заявке'),
          iconKey:String(service.icon || category.icon || 'repair'),
          desc:String(service.desc || category.desc || ''),
          source:'masters_catalog'
        });
        servicesRequestSave(st);
        servicesRequestOpen(st.cat, st.item, 1);
        return false;
      }
    } catch(_e) {}
    window.servicesAppOpenRequest?.(service.cat || 'repair', service.id || 'custom');
    return false;
  }
  try {
    window.KaretaMastersCatalog = Object.assign(window.KaretaMastersCatalog || {}, {
      version:'stable',
      get: mastersServiceCatalog,
      byId: mastersServiceById,
      category: mastersServiceCategory,
      counts: mastersServiceCounts,
      open: mastersDirectoryOpenService
    });
    window.mastersDirectoryOpenService = window.mastersDirectoryOpenService || mastersDirectoryOpenService;
  } catch(_e) {}

  // one public service catalog facade for #services, #masters and request flows.
  // It does not replace the r65i catalog; it gives other modules a stable access point.
  function serviceCatalogGet(){
    const base = (window.KaretaMastersCatalog?.get?.() || mastersServiceCatalog?.() || {});
    const categories = Array.isArray(base.categories) ? base.categories.slice() : [];
    const services = Array.isArray(base.services) ? base.services.slice() : [];
    return { version:'stable', categories, services };
  }
  function serviceCatalogById(cat, itemId){
    const c = String(cat || '').trim();
    const id = String(itemId || '').trim();
    const catalog = serviceCatalogGet();
    return catalog.services.find(x=>String(x.cat)===c && String(x.id)===id)
      || catalog.services.find(x=>String(x.cat)===c)
      || catalog.services.find(x=>String(x.id)===id)
      || null;
  }
  function serviceCatalogCategory(cat){
    const c = String(cat || '').trim();
    const catalog = serviceCatalogGet();
    return catalog.categories.find(x=>String(x.key)===c) || null;
  }
  function serviceCatalogCounts(){
    const catalog = serviceCatalogGet();
    return catalog.services.reduce((acc, x)=>{ const k=String(x.cat||''); acc[k]=(acc[k]||0)+1; acc.all=(acc.all||0)+1; return acc; }, { all:0 });
  }
  try {
    window.KaretaServiceCatalog = Object.assign(window.KaretaServiceCatalog || {}, {
      version:'stable',
      get:serviceCatalogGet,
      byId:serviceCatalogById,
      category:serviceCatalogCategory,
      counts:serviceCatalogCounts,
      open:(cat, itemId)=> window.KaretaMastersCatalog?.open?.(cat, itemId) || window.servicesAppOpenRequest?.(cat, itemId) || false
    });
  } catch(_e) {}

  /* r64n/r65i — standalone top-menu page "Сервисы / Все услуги".
     Important: #services remains the old frozen home page. This page is mounted on #masters. */
  function renderServicesDirectory(opts){
    opts = opts || {};
    const esc = window.escHtml || (v=>String(v||''));
    const attr = window.escAttr || escAttr || esc;
    const quickModeStable = !!(opts && (opts.quick || opts.mode === 'quick')) || String(location.hash || '').replace(/^#/,'').split('?')[0] === 'services:quick';
    const catalog = mastersServiceCatalog();
    const categories = catalog.categories || [];
    const services = catalog.services || [];
    const counts = mastersServiceCounts();
    const initialCat = mastersCatalogCategoryKey((opts && (opts.mastersCat || opts.cat)) || '') || 'all';
    const categoryModeStable = !quickModeStable && initialCat !== 'all';
    const currentCatMeta = categoryModeStable ? (categories.find(c=>String(c.key)===initialCat) || mastersServiceCategory(initialCat)) : null;
    const filteredCount = initialCat === 'all' ? services.length : services.filter(x=>String(x.cat)===initialCat).length;
    const catHtml = [{key:'all', label:'Все', icon:'search', desc:'Полный каталог услуг'}].concat(categories).map((c,idx)=>`<button type="button" class="services-dir-cat ${(String(c.key)===initialCat)?'is-active':''}" data-services-dir-filter="${attr(c.key)}" data-services-dir-cat-index="${idx}" onclick="window.servicesDirectoryFilter('${attr(c.key)}')"><span>${serviceMiniIconSvg(c.icon || 'repair')}</span><b>${esc(c.label)}</b><small>${Number(counts[c.key] || services.length)} услуг</small></button>`).join('');
    const cardHtml = services.map((x,idx)=>`<article class="services-dir-card" data-services-dir-card="1" data-services-dir-cat="${attr(x.cat)}" data-services-dir-text="${attr((x.title+' '+x.desc+' '+x.tag+' '+mastersServiceCategory(x.cat).label).toLowerCase())}" ${initialCat !== 'all' && String(x.cat)!==initialCat ? 'hidden' : ''}>
        <button type="button" class="services-dir-card-main" onclick="window.mastersDirectoryOpenService('${attr(x.cat)}','${attr(x.id)}')">
          <span class="services-dir-card-icon">${serviceMiniIconSvg(x.icon || mastersServiceCategory(x.cat).icon || 'repair')}</span>
          <span class="services-dir-card-copy"><mark>${esc(x.tag || mastersServiceCategory(x.cat).label)}</mark><b>${esc(x.title)}</b><small>${esc(x.desc)}</small></span>
        </button>
        <div class="services-dir-card-meta">
          <span>${serviceMiniIconSvg('clock')}${esc(x.time || 'по осмотру')}</span>
          <strong>${esc(x.price || 'по заявке')}</strong>
        </div>
        <button type="button" class="services-dir-card-cta" onclick="window.mastersDirectoryOpenService('${attr(x.cat)}','${attr(x.id)}')">Записаться</button>
      </article>`).join('');
    const statsHtml = [
      ['Разделов', String(categories.length)],
      ['Услуг', String(services.length)],
      ['В каждом разделе', '20'],
      ['Заявка', '3 шага']
    ].map(([k,v])=>`<div><b>${esc(v)}</b><span>${esc(k)}</span></div>`).join('');
    const trustHtml = [
      ['diagnostics','Каталог по разделам','Каждый раздел заполнен 20 услугами'],
      ['calendar','Запись через 3 шага','Услуга, автомобиль, подтверждение'],
      ['car','Привязка к машине','Заявка попадёт в историю автомобиля'],
      ['chat','Уточнение в чате','Мастер сможет согласовать детали']
    ].map(([icon,title,sub])=>`<div><span>${serviceMiniIconSvg(icon)}</span><b>${esc(title)}</b><small>${esc(sub)}</small></div>`).join('');
    return `<section class="services-directory ${quickModeStable ? 'services-directory--quick' : ''} ${categoryModeStable ? 'services-directory--category' : ''}" data-services-directory="1" data-masters-catalog="1" data-services-directory-contract="stable" data-services-directory-mode="${quickModeStable ? 'quick' : (categoryModeStable ? 'category' : 'catalog')}" data-services-directory-mode="${quickModeStable ? 'quick' : (categoryModeStable ? 'category' : 'catalog')}" data-services-dir-active-cat="${attr(initialCat)}">
      <div class="services-dir-head"><div class="services-dir-back-wrap">${categoryModeStable ? `<button type="button" class="services-dir-back" onclick="App.go('services:quick')" aria-label="Назад к поиску услуг">←</button>` : ''}<div><span>${quickModeStable ? 'Поиск услуг' : (categoryModeStable ? 'Раздел услуг' : 'Каталог KARETA.KZ')}</span><h1>${quickModeStable ? 'Найдите услугу' : (categoryModeStable ? (currentCatMeta?.label || 'Услуги') : 'Все услуги по автомобилю')}</h1><p>${quickModeStable ? 'Введите услугу, выберите карточку и сразу оформляйте заявку без лишнего информационного шага.' : (categoryModeStable ? (currentCatMeta?.desc || 'Выберите услугу из раздела и сразу оформляйте заявку.') : 'Выберите раздел или найдите услугу. При записи заявка будет привязана к автомобилю из гаража и попадёт в историю ремонта.')}</p></div><div class="services-dir-stats">${statsHtml}</div></div>
      <form class="services-dir-search" onsubmit="event.preventDefault();window.servicesDirectorySearch(this.querySelector('input')?.value||'')">
        <span>${serviceMiniIconSvg('search')}</span>
        <input type="search" placeholder="Поиск: стартер, масло, тормоза, кондиционер" autocomplete="off" oninput="window.servicesDirectorySearch(this.value)">
        <button type="submit"><i>${serviceMiniIconSvg('search')}</i><em>Найти</em></button>
      </form>
      <div class="services-dir-cats" aria-label="Категории услуг" data-services-dir-cats="1" data-services-dir-collapsed="1" data-services-dir-count="${categories.length + 1}">${catHtml}<button type="button" class="services-dir-cat services-dir-cat-more" data-services-dir-more="1" onclick="window.servicesDirectoryToggleCats()" hidden><span>•••</span><b>Ещё</b></button></div>
      <div class="services-dir-tools">
        <button type="button" class="services-dir-select">Сортировка: <b>Популярные</b></button>
        <button type="button" class="services-dir-select services-dir-show">Показать: <b>Все разделы</b></button>
        <button type="button" class="services-dir-filter" onclick="window.servicesDirectoryReset()">${serviceMiniIconSvg('filter')}<b>Сбросить</b></button>
        <button type="button" class="services-dir-filter services-dir-filter--primary" onclick="window.servicesQuickOpen?.(1) || App.go('services:quick')">${serviceMiniIconSvg('calendar')}<b>Быстрая заявка</b></button>
      </div>
      <div class="services-dir-result" data-services-dir-result>Найдено ${filteredCount} услуг</div>
      <div class="services-dir-grid">${cardHtml}</div>
      <section class="services-dir-trust">${trustHtml}</section>
    </section>`;
  }

  function servicesDirectoryCatColumns(width){
    const w = Number(width || 0);
    if(w > 0 && w < 372) return 4;
    return 5;
  }

  function applyServicesDirectoryCatStandard(){
    const root = document.querySelector('.services-directory');
    const cats = root?.querySelector('[data-services-dir-cats="1"]');
    if(!root || !cats) return false;
    const catButtons = Array.from(cats.querySelectorAll('.services-dir-cat[data-services-dir-filter]'));
    const moreBtn = cats.querySelector('[data-services-dir-more="1"]');
    const rectWidth = cats.getBoundingClientRect ? cats.getBoundingClientRect().width : cats.clientWidth;
    const cols = servicesDirectoryCatColumns(rectWidth || window.innerWidth || 390);
    const maxVisible = cols === 4 ? 7 : 10;
    const hasOverflow = catButtons.length > maxVisible;
    const collapsed = cats.getAttribute('data-services-dir-collapsed') !== '0';
    cats.style.setProperty('--services-dir-cat-cols', String(cols));
    cats.dataset.servicesDirCols = String(cols);
    cats.dataset.servicesDirMax = String(maxVisible);
    cats.classList.toggle('services-dir-cats--cols-4', cols === 4);
    cats.classList.toggle('services-dir-cats--cols-5', cols === 5);
    cats.classList.toggle('services-dir-cats--has-overflow', hasOverflow);
    catButtons.forEach((btn, idx)=>{
      const hide = hasOverflow && collapsed && idx >= maxVisible && !btn.classList.contains('is-active');
      btn.classList.toggle('is-overflow', hide);
      btn.hidden = hide;
    });
    if(moreBtn){
      moreBtn.hidden = !hasOverflow;
      moreBtn.classList.toggle('is-expanded', hasOverflow && !collapsed);
      const label = moreBtn.querySelector('b');
      const icon = moreBtn.querySelector('span');
      if(label) label.textContent = collapsed ? 'Ещё' : 'Скрыть';
      if(icon) icon.textContent = collapsed ? '•••' : '↑';
    }
    return true;
  }

  window.servicesDirectoryToggleCats = function(){
    const cats = document.querySelector('.services-directory [data-services-dir-cats="1"]');
    if(!cats) return false;
    const collapsed = cats.getAttribute('data-services-dir-collapsed') !== '0';
    cats.setAttribute('data-services-dir-collapsed', collapsed ? '0' : '1');
    return applyServicesDirectoryCatStandard();
  };

  function afterServicesRouteCommit(){
    const run = ()=>{
      applyServicesDirectoryCatStandard();
      applyMobileButtonGridStandards();
      try {
        const cats = document.querySelector('.services-directory [data-services-dir-cats="1"]');
        if(cats && !cats.__servicesDirResize && typeof ResizeObserver !== 'undefined'){
          cats.__servicesDirResize = new ResizeObserver(()=>applyServicesDirectoryCatStandard());
          cats.__servicesDirResize.observe(cats);
        }
      } catch(_e) {}
      try { attachMobileButtonGridObservers(); } catch(_e) {}
    };
    if(typeof requestAnimationFrame === 'function') requestAnimationFrame(run);
    else setTimeout(run, 0);
  }

  function mobileButtonGridColumns(width){
    const w = Number(width || 0);
    if(w > 0 && w < 372) return 4;
    return 5;
  }

  function applyOneMobileButtonGrid(grid, opts){
    if(!grid) return false;
    const selector = opts && opts.buttonSelector ? opts.buttonSelector : 'button';
    const buttonClass = opts && opts.overflowClass ? opts.overflowClass : 'is-overflow';
    const colsVar = opts && opts.colsVar ? opts.colsVar : '--kareta-mobile-btn-cols';
    const width = (grid.getBoundingClientRect ? grid.getBoundingClientRect().width : 0) || grid.clientWidth || window.innerWidth || 390;
    let cols = mobileButtonGridColumns(width);
    const maxCols = Number((opts && opts.maxCols) || grid.dataset.mobileGridMaxCols || 0);
    if(maxCols > 0) cols = Math.min(cols, maxCols);
    const maxVisible = cols * 2;
    const buttons = Array.from(grid.querySelectorAll(selector)).filter(btn=>!btn.hasAttribute('data-mobile-grid-more'));
    const moreBtn = grid.querySelector('[data-mobile-grid-more="1"]');
    const hasOverflow = buttons.length > maxVisible;
    const collapsed = grid.getAttribute('data-mobile-grid-collapsed') !== '0';
    grid.style.setProperty(colsVar, String(cols));
    grid.dataset.mobileGridCols = String(cols);
    grid.dataset.mobileGridMax = String(maxVisible);
    grid.classList.toggle('kareta-mobile-grid--cols-4', cols === 4);
    grid.classList.toggle('kareta-mobile-grid--cols-5', cols === 5);
    grid.classList.toggle('kareta-mobile-grid--has-overflow', hasOverflow);
    buttons.forEach((btn, idx)=>{
      const active = btn.classList.contains('active') || btn.classList.contains('is-active') || btn.getAttribute('aria-pressed') === 'true';
      const hide = hasOverflow && collapsed && idx >= maxVisible && !active;
      btn.classList.toggle(buttonClass, hide);
      btn.hidden = hide;
    });
    if(moreBtn){
      moreBtn.hidden = !hasOverflow;
      moreBtn.classList.toggle('is-expanded', hasOverflow && !collapsed);
      const label = moreBtn.querySelector('b');
      const icon = moreBtn.querySelector('span');
      if(label) label.textContent = collapsed ? 'Ещё' : 'Скрыть';
      if(icon) icon.textContent = collapsed ? '•••' : '↑';
    }
    return true;
  }

  function applyMobileButtonGridStandards(){
    let changed = false;
    document.querySelectorAll('[data-parts-ref-cats="1"]').forEach(grid=>{
      changed = applyOneMobileButtonGrid(grid, {
        buttonSelector: '.parts-ref-cat[data-parts-ref-cat]',
        overflowClass: 'is-overflow',
        colsVar: '--parts-ref-cat-cols',
        maxCols: 4
      }) || changed;
    });
    document.querySelectorAll('[data-sales-cats="1"]').forEach(grid=>{
      changed = applyOneMobileButtonGrid(grid, {
        buttonSelector: '.sales-cat[data-sales-cat]',
        overflowClass: 'is-overflow',
        colsVar: '--sales-cat-cols'
      }) || changed;
    });
    return changed;
  }

  function attachMobileButtonGridObservers(){
    if(typeof ResizeObserver === 'undefined') return false;
    document.querySelectorAll('[data-parts-ref-cats="1"],[data-sales-cats="1"]').forEach(grid=>{
      if(grid.__karetaMobileGridResize) return;
      grid.__karetaMobileGridResize = new ResizeObserver(()=>applyMobileButtonGridStandards());
      grid.__karetaMobileGridResize.observe(grid);
    });
    return true;
  }

  window.karetaToggleMobileButtonGrid = function(selector){
    const grid = document.querySelector(String(selector || ''));
    if(!grid) return false;
    const collapsed = grid.getAttribute('data-mobile-grid-collapsed') !== '0';
    grid.setAttribute('data-mobile-grid-collapsed', collapsed ? '0' : '1');
    return applyMobileButtonGridStandards();
  };

  window.servicesDirectoryFilter = function(cat){
    const key = String(cat || 'all').trim() || 'all';
    const root = document.querySelector('.services-directory');
    if(!root) return false;
    const showAll = !key || key === 'all';
    root.querySelectorAll('.services-dir-cat[data-services-dir-filter]').forEach(btn=>btn.classList.toggle('is-active', String(btn.dataset.servicesDirFilter || '') === key));
    const input = root.querySelector('.services-dir-search input');
    if(input) input.value = '';
    let visible = 0;
    root.querySelectorAll('[data-services-dir-card="1"]').forEach(card=>{
      const show = showAll || String(card.dataset.servicesDirCat || '') === key;
      card.hidden = !show;
      if(show) visible += 1;
    });
    const result = root.querySelector('[data-services-dir-result]');
    if(result) result.textContent = visible ? `Найдено ${visible} услуг` : 'Ничего не найдено';
    return false;
  };

  window.servicesDirectorySearch = function(query){
    const root = document.querySelector('.services-directory');
    if(!root) return false;
    const q = String(query || '').trim().toLowerCase().replace(/ё/g,'е');
    root.querySelectorAll('.services-dir-cat[data-services-dir-filter]').forEach(btn=>btn.classList.toggle('is-active', String(btn.dataset.servicesDirFilter || '') === 'all' && !q));
    let visible = 0;
    root.querySelectorAll('[data-services-dir-card="1"]').forEach(card=>{
      const text = String(card.dataset.servicesDirText || card.textContent || '').toLowerCase().replace(/ё/g,'е');
      const show = !q || text.includes(q);
      card.hidden = !show;
      if(show) visible += 1;
    });
    const result = root.querySelector('[data-services-dir-result]');
    if(result) result.textContent = visible ? `Найдено ${visible} услуг` : 'Ничего не найдено';
    return false;
  };

  window.servicesDirectoryReset = function(){
    const root = document.querySelector('.services-directory');
    if(!root) return false;
    const input = root.querySelector('.services-dir-search input');
    if(input) input.value = '';
    root.querySelectorAll('.services-dir-cat[data-services-dir-filter]').forEach(btn=>btn.classList.toggle('is-active', String(btn.dataset.servicesDirFilter || '') === 'all'));
    let visible = 0;
    root.querySelectorAll('[data-services-dir-card="1"]').forEach(card=>{ card.hidden = false; visible += 1; });
    const result = root.querySelector('[data-services-dir-result]');
    if(result) result.textContent = `Найдено ${visible} услуг`;
    return false;
  };


