  window.salesFilter = function(type){
    const root = document.querySelector('.sales-reference');
    if(!root) return false;
    const key = String(type || 'all');
    root.querySelectorAll('.sales-cat').forEach(btn=>btn.classList.toggle('is-active', String(btn.dataset.salesCat || '') === key));
    const input = root.querySelector('.sales-search input');
    if(input) input.value = '';
    let visible = 0;
    root.querySelectorAll('[data-sales-card="1"]').forEach(card=>{
      const show = key === 'all' || String(card.dataset.salesType || '') === key;
      card.hidden = !show;
      if(show) visible += 1;
    });
    const result = root.querySelector('[data-sales-result]');
    if(result) result.textContent = visible ? `Найдено ${visible} предложений` : 'Ничего не найдено';
    return false;
  };

  window.salesSearch = function(value){
    const root = document.querySelector('.sales-reference');
    if(!root) return false;
    const q = String(value || '').trim().toLowerCase().replace(/ё/g,'е');
    root.querySelectorAll('.sales-cat').forEach(btn=>btn.classList.toggle('is-active', String(btn.dataset.salesCat || '') === 'all'));
    let visible = 0;
    root.querySelectorAll('[data-sales-card="1"]').forEach(card=>{
      const hay = String(card.dataset.salesText || card.textContent || '').toLowerCase().replace(/ё/g,'е');
      const show = !q || hay.includes(q);
      card.hidden = !show;
      if(show) visible += 1;
    });
    const result = root.querySelector('[data-sales-result]');
    if(result) result.textContent = visible ? `Найдено ${visible} предложений` : 'Ничего не найдено';
    return false;
  };

  window.salesReset = function(){
    const root = document.querySelector('.sales-reference');
    if(!root) return false;
    const input = root.querySelector('.sales-search input');
    if(input) input.value = '';
    return window.salesFilter('all');
  };

