  window.servicesRequestOpen = window.servicesRequestOpen || servicesRequestOpen;
  window.servicesRequestClose = window.servicesRequestClose || servicesRequestClose;
  window.servicesRequestSelectService = window.servicesRequestSelectService || servicesRequestSelectService;
