  function partsProductCategoryKeys(){
    return ['audio_speaker','audio_amp','audio_sub','audio_cable','audio_accessory','audio_box','audio_headunit','camera','soundproof','merch','oil','filter','brake','suspension','battery','spark','wire','cooling','gen','start','alarm','other'];
  }
  function partsIsProductCategory(cat){
    const token = String(cat || '').trim();
    return !!token && token !== 'all' && partsProductCategoryKeys().includes(token);
  }
  function getPartsCategoryUrl(cat){
    const token = String(cat || '').trim();
    if(!token || token === 'all') return 'parts';
    return partsIsProductCategory(token)
      ? ('parts:' + encodeURIComponent(token) + ':all-products')
      : ('parts:' + encodeURIComponent(token));
  }
  function getPartsDrilldownUrl(cat, subcat, brand){
    const cleanCat = String(cat || '').trim();
    let cleanSub = String(subcat || '').trim();
    const cleanBrand = String(brand || '').trim();
    const bits = [];
    if(cleanCat && cleanCat !== 'categories') bits.push(cleanCat);
    if(cleanBrand && cleanBrand !== 'all' && (!cleanSub || cleanSub === 'all')) cleanSub = 'all-products';
    if(cleanSub && cleanSub !== 'all') bits.push(cleanSub);
    if(cleanBrand && cleanBrand !== 'all') bits.push(cleanBrand);
    return bits.length ? ('parts:' + bits.map(encodeURIComponent).join(':')) : 'parts';
  }
  window.getPartsCategoryUrl = window.getPartsCategoryUrl || getPartsCategoryUrl;
  window.getPartsDrilldownUrl = window.getPartsDrilldownUrl || getPartsDrilldownUrl;
  function openPartsCategoryPage(cat){
    const target = String(cat || 'all').trim() || 'all';
    window._partsActiveCat = target;
    const canonical = getPartsCategoryUrl(target);
    const opts = { partsCat: target, canonicalHash: canonical };
    if(partsIsProductCategory(target)){
      opts.partsSubcat = 'all-products';
      opts.partsBrand = 'all';
      window._partsReferenceSubcat = 'all';
      window._partsReferenceBrand = 'all';
      window._partsRouteSubcat = 'all-products';
      window._partsRouteBrand = '';
      window._partsSearchQuery = '';
    }
    App.go('parts', opts);
  }
