  function getPartGalleryImages(part){
    const list = [];
    const push = (v)=>{ const s=String(v||'').trim(); if(s && !list.includes(s)) list.push(s); };
    push(part?.image || part?.img || part?.imageUrl || part?.photo || '');
    const arr = Array.isArray(part?.images) ? part.images : [];
    arr.forEach(push);
    if(!list.length) push(getPartImage(part||{}));
    return list;
  }
