    const stockButtons = `<button type="button" class="parts-ref-filter-chip active" data-parts-ref-stock="all" aria-pressed="true" onclick="partsRefSetStock('all')">Все</button><button type="button" class="parts-ref-filter-chip" data-parts-ref-stock="in" aria-pressed="false" onclick="partsRefSetStock('in')">В наличии</button><button type="button" class="parts-ref-filter-chip" data-parts-ref-stock="order" aria-pressed="false" onclick="partsRefSetStock('order')">Под заказ</button>`;
