  const __stoAssignOrderMasterBusy = new Set();
  window.stoAssignOrderMaster = async function(){
    const orderId = document.getElementById('sto-assign-order-id')?.value || '';
    const masterId = document.getElementById('sto-assign-master-select')?.value || '';
    const mode = document.getElementById('sto-assign-mode')?.value || 'assign';
    const expectedMasterId = document.getElementById('sto-assign-expected-master-id')?.value || '';
    const comment = document.getElementById('sto-assign-comment')?.value || '';
    if(!orderId || !masterId){ window._showToast?.('Выберите мастера','error'); return; }
    if(mode === 'reassign' && expectedMasterId && masterId === expectedMasterId){ window._showToast?.('Выберите другого мастера','warn'); return; }
    const busyKey = mode + ':' + orderId;
    if (__stoAssignOrderMasterBusy.has(busyKey)) { window._showToast?.('Операция уже выполняется','warn'); return; }
    const modal = document.getElementById('sto-assign-order-modal');
    const btn = modal?.querySelector?.('button.btn-primary');
    __stoAssignOrderMasterBusy.add(busyKey);
    if (btn) { btn.disabled = true; btn.dataset.prevText = btn.textContent || ''; btn.textContent = mode === 'reassign' ? 'Переназначаю...' : 'Назначаю...'; }
    try{
      const r = mode === 'reassign'
        ? await window.DB?.StoExchangeStore?.reassignMaster?.(orderId, masterId, expectedMasterId, comment)
        : await window.DB?.StoExchangeStore?.assignOrderMaster?.(orderId, masterId);
      document.getElementById('sto-assign-order-modal')?.remove();
      window._showToast?.(r?.skipped ? 'Заявка уже закреплена за этим мастером' : (mode === 'reassign' ? 'Мастер переназначен' : 'Мастер назначен на заявку'),'success');
      await _stoRefreshDispatchSafe();
    }catch(e){ window._showToast?.(e?.message || (mode === 'reassign' ? 'Не удалось переназначить мастера' : 'Не удалось назначить мастера'),'error'); }
    finally {
      __stoAssignOrderMasterBusy.delete(busyKey);
      if (btn && document.body.contains(btn)) { btn.disabled = false; btn.textContent = btn.dataset.prevText || (mode === 'reassign' ? 'Переназначить' : 'Назначить'); }
    }
  };

