  // one normalizer for all client cabinet hashes.
  // It keeps old public URLs (#cabinet:stats, #cabinet:editprofile, #cabinet:garage) working,
  // but renders them through the new kcab-* level cabinet.
  function normalizeCabinetHash(rawHash){
    const raw0 = String(rawHash || 'cabinet').replace(/^#/, '').trim() || 'cabinet';
    const parts = raw0.split(':').map(x => decodeURIComponent(String(x || '').trim()));
    const rawSection = parts[1] || 'home';
    const aliases = { stats:'home', documents:'appsettings', reminders:'notifs', garage:'car' };
    const sectionToLegacy = { home:'stats', profile:'editprofile', car:'car', history:'history', loyalty:'loyalty', notifs:'notifs', appsettings:'appsettings', diagnostics:'diagnostics' };
    const allowed = ['home','profile','car','history','loyalty','notifs','appsettings','diagnostics'];
    let section = raw0 === 'cabinet' ? 'home' : (aliases[rawSection] || rawSection || 'home');
    let action = parts[2] || '';
    let id = parts[3] || '';
    let orderId = '';

    // old #cabinet:editprofile means profile edit, but #cabinet:profile means profile view.
    if (rawSection === 'editprofile') { section = 'profile'; action = 'edit'; id = ''; }
    if (!allowed.includes(section)) { section = 'home'; action = ''; id = ''; }

    let canonical = 'cabinet';
    if (section === 'home') {
      canonical = (rawSection === 'stats') ? 'cabinet:stats' : 'cabinet';
      action = ''; id = '';
    } else if (section === 'profile') {
      if (action === 'edit') canonical = 'cabinet:profile:edit';
      else { action = 'view'; id = ''; canonical = 'cabinet:profile'; }
    } else if (section === 'car') {
      // linked repair card inside vehicle history.
      // Supports both #cabinet:car:order:<vehicleId>:<orderId> and
      // #cabinet:car:view:<vehicleId>:order:<orderId> as compatibility aliases.
      if (action === 'view' && id && parts[4] === 'order' && parts[5]) { action = 'order'; orderId = parts[5]; canonical = 'cabinet:car:order:' + encodeURIComponent(id) + ':' + encodeURIComponent(orderId); }
      else if (action === 'order' && id && parts[4]) { orderId = parts[4]; canonical = 'cabinet:car:order:' + encodeURIComponent(id) + ':' + encodeURIComponent(orderId); }
      else if (action === 'new') { id = ''; canonical = 'cabinet:car:new'; }
      else if (action === 'view' && id) canonical = 'cabinet:car:view:' + encodeURIComponent(id);
      else if (action === 'edit' && id) canonical = 'cabinet:car:edit:' + encodeURIComponent(id);
      else { action = ''; id = ''; orderId = ''; canonical = 'cabinet:car'; }
    } else if (section === 'history') {
      const filters = ['all','planned','process','done','cancel'];
      if (!filters.includes(action)) action = '';
      canonical = 'cabinet:history' + (action && action !== 'all' ? ':' + action : '');
    } else {
      action = ''; id = ''; canonical = 'cabinet:' + section;
    }
    let level = section === 'home' ? 1 : 2;
    if ((section === 'profile' && action === 'edit') || (section === 'car' && ['new','view','edit','order'].includes(action))) level = 3;
    return { raw: raw0, section, action, id, orderId, canonical, level, legacyTab: sectionToLegacy[section] || 'stats' };
  }

  // isolated client cabinet level navigation.
  // This layer keeps the global shell untouched and replaces only the client cabinet UI.
  function getCabinetRoute(rawHash){
    return normalizeCabinetHash(rawHash || location.hash || '#cabinet');
  }

  // profile page helpers for the new kcab-* cabinet.
  function cabinetProfileInitials(u){
    const name = String(u?.name || '').trim();
    const parts = name.split(/\s+/).filter(Boolean);
    const initials = String(u?.initials || '').trim();
    if (initials) return initials.slice(0,2).toUpperCase();
    if (parts.length > 1) return (parts[0][0] + parts[1][0]).toUpperCase();
    return (name[0] || 'K').toUpperCase();
  }

  function cabinetProfileRows(ctx){
    const u = ctx?.u || {};
    const primary = ctx?.primaryVehicle || null;
    const rows = [
      ['Имя', u.name || 'Не указано'],
      ['Телефон', u.phone ? formatPhone(u.phone) : 'Не указан'],
      ['Email', u.email || 'Не указан'],
      ['Город', u.city || 'Не указан'],
      ['Основной автомобиль', u.car || primary?.title || (primary ? cabinetVehicleTitle(primary) : 'Не указан')]
    ];
    return rows.map(([k,v]) => `<div><span>${escHtml(k)}</span><b>${escHtml(String(v || '—'))}</b></div>`).join('');
  }

  window.kcabSaveProfile = async function(){
    const btn = document.getElementById('kcab-save-profile-btn');
    const toast = document.getElementById('kcab-profile-toast');
    const nameInput = document.getElementById('kcab-pf-name');
    const phoneInput = document.getElementById('kcab-pf-phone');
    const emailInput = document.getElementById('kcab-pf-email');
    const cityInput = document.getElementById('kcab-pf-city');
    const carInput = document.getElementById('kcab-pf-car');
    const specInput = document.getElementById('kcab-pf-spec');
    const name = String(nameInput?.value || '').trim();
    const phoneRawValue = String(phoneInput?.value || '').trim();
    const phone = phoneRawValue ? phoneRaw(phoneRawValue) : '';
    const email = String(emailInput?.value || '').trim();
    const city = String(cityInput?.value || '').trim();
    const car = String(carInput?.value || '').trim();
    const spec = String(specInput?.value || '').trim();

    if (!name) { showToast('Укажите имя', 'error'); nameInput?.focus?.(); return false; }
    if (phoneRawValue && !isValidPhone(phoneRawValue)) { showToast('Проверьте номер телефона', 'error'); phoneInput?.focus?.(); return false; }

    const currentPhone = phoneRaw(window.App?.getState?.()?.user?.phone || '');
    const patch = { name, email, city, car, spec };
    if (!currentPhone && phone) patch.phone = phone;

    if (btn) { btn.disabled = true; btn.textContent = 'Сохраняем...'; }
    try {
      if (window.App?.persistServerProfile) await window.App.persistServerProfile(patch);
      window.App?.mergeUserPatch?.(patch);
      const state = window.App?.getState?.();
      if (state?.user) {
        const parts = String(state.user.name || name).split(/\s+/).filter(Boolean);
        state.user.initials = ((parts[0]?.[0] || '') + (parts[1]?.[0] || parts[0]?.[1] || '')).toUpperCase();
      }
      try { window.RBAC?.upsertUser?.(window.App?.getState?.()?.user); } catch(_e) {}
      if (toast) { toast.textContent = 'Профиль сохранён'; toast.classList.add('show'); setTimeout(()=>toast.classList.remove('show'), 2200); }
      showToast('Профиль сохранён');
      if (btn) { btn.textContent = 'Сохранено'; setTimeout(()=>{ btn.disabled = false; btn.textContent = 'Сохранить'; }, 1200); }
      setTimeout(()=>{ try { kcabGo('cabinet:profile'); } catch(_e) {} }, 350);
    } catch(e) {
      showToast(e?.message || 'Не удалось сохранить профиль', 'error');
      if (btn) { btn.disabled = false; btn.textContent = 'Сохранить'; }
    }
    return false;
  };

  function cabinetIcon(name){
    try {
      if (typeof serviceMiniIconSvg === 'function') return serviceMiniIconSvg(name) || '';
    } catch(_e) {}
    return ({car:'▱', calendar:'▤', bell:'○', user:'◌', settings:'□', wallet:'₸', diagnostic:'⌕'}[name] || '•');
  }

  function cabinetStatusText(status){
    const s = String(status || 'new');
    return ({done:'Выполнено',process:'В работе',wait:'Ожидает',new:'Новая',cancel:'Отменено',cancelled:'Отменено',done_pending_client:'Ожидает подтверждения'}[s] || s);
  }

  function cabinetStatusClass(status){
    const s = String(status || 'new');
    if (s === 'done') return 'is-done';
    if (s === 'process') return 'is-process';
    if (s === 'cancel' || s === 'cancelled') return 'is-cancel';
    return 'is-new';
  }

  function cabinetMoney(value){
    return Number(value || 0).toLocaleString('ru') + ' ₸';
  }

  function cabinetVehicleTitle(v){
    if (!v) return 'Автомобиль';
    return String(v.title || [v.brand, v.model, v.year].filter(Boolean).join(' ') || 'Автомобиль').trim();
  }

  function cabinetVehicleSub(v){
    if (!v) return 'Данные не заполнены';
    return String([v.plate, v.vin].filter(Boolean).join(' · ') || [v.brand, v.model, v.year].filter(Boolean).join(' ') || 'Карточка автомобиля').trim();
  }

  function cabinetFindVehicle(ctx, id){
    const cars = Array.isArray(ctx?.clientVehicles) ? ctx.clientVehicles : [];
    const sid = String(id || '').trim();
    if (!sid) return null;
    return cars.find(x => String(x?.id || '') === sid) || null;
  }

  function renderCabinetMissingVehicle(ctx, route){
    const body = `<div id="cp-car" class="kcab-route-anchor"></div><section class="kcab-empty kcab-empty--route">
      <span>▱</span><b>Автомобиль не найден</b><p>Карточка могла быть удалена, ID в ссылке устарел или данные ещё не загрузились.</p>
      <div class="kcab-empty-actions"><button type="button" onclick="return kcabGo('cabinet:car')">Открыть гараж</button><button type="button" onclick="return kcabGo('cabinet:car:new')">Добавить авто</button></div>
    </section>`;
    return renderCabinetShell(ctx, Object.assign({}, route, { section:'car', level:3 }), 'Автомобиль не найден', 'Проверьте список машин в гараже', body);
  }

  function getCabinetBackRoute(route){
    const r = route || {};
    if (r.section === 'car' && r.action === 'order' && r.id) return 'cabinet:car:view:' + r.id;
    if (r.section === 'car' && r.level >= 3) return 'cabinet:car';
    if (r.section === 'profile' && r.action === 'edit') return 'cabinet:profile';
    if (r.section && r.section !== 'home') return 'cabinet';
    return 'home';
  }

  function renderCabinetHeader(ctx, route, title, subtitle, opts){
    const backRoute = getCabinetBackRoute(route);
    const back = route.level > 1 ? `<button type="button" class="kcab-back" onclick="return kcabGo('${escJs(backRoute)}')" aria-label="Назад">‹</button>` : '';
    const action = opts && opts.action ? opts.action : '';
    return `<header class="kcab-head k-page-head k-page-head--cabinet" data-k-page-contract="stable">
      <div class="kcab-head-left">${back}<div><h1 class="k-page-title">${escHtml(title)}</h1><p class="k-page-desc">${escHtml(subtitle || '')}</p></div></div>
      <div class="kcab-head-actions">${action}<button type="button" class="kcab-bell" onclick="window.Notifs?.toggle?.()">${cabinetIcon('bell')}${ctx.unreadCount ? `<i>${ctx.unreadCount}</i>` : ''}</button></div>
    </header>`;
  }

  function renderCabinetShell(ctx, route, title, subtitle, body, opts){
    const mod = 'kcab-page--' + escHtml(route.section || 'home');
    const surf = route.section === 'home' ? 'dashboard' : 'detail';
    return `<div class="page kcab-page ${mod}" data-kcab-section="${escHtml(route.section || 'home')}" data-kcab-level="${route.level}" data-kcab-surface="${surf}">
      <section class="kcab-shell">
        <div class="kcab-phone">
          ${renderCabinetHeader(ctx, route, title, subtitle, opts)}
          ${body}
        </div>
      </section>
    </div>`;
  }

  function renderCabinetHome(ctx, route){
    const u = ctx.u || {};
    const primary = ctx.primaryVehicle || null;
    const next = ctx.nextOrder;
    const quick = [
      ['profile','Профиль','Контакты','user'],
      ['car','Гараж','Авто','car'],
      ['history','История','Заявки','calendar'],
      ['appsettings','Настройки','Документы','settings']
    ];
    const primaryRoute = primary ? (primary.id ? ('cabinet:car:view:' + primary.id) : 'cabinet:car') : 'cabinet:car:new';
    const primaryCarHtml = primary ? `<button type="button" class="kcab-primary-car kcab-primary-car-" onclick="return kcabGo('${escJs(primaryRoute)}')">
      <span>${escHtml(primary.icon || '▱')}</span><strong>${escHtml(cabinetVehicleTitle(primary))}</strong><em>${escHtml(cabinetVehicleSub(primary))}</em><b>›</b>
    </button>` : `<button type="button" class="kcab-empty-action kcab-empty-action-" onclick="return kcabGo('cabinet:car:new')"><span>+</span><strong>Добавить автомобиль</strong><em>История ремонта будет привязана к машине</em></button>`;
    const nextHtml = next ? `<button type="button" class="kcab-order-card kcab-order-card-" data-k-action="open-order" data-order-id="${escAttr(next.id)}">
      <span class="kcab-order-ico">▤</span><span><strong>${escHtml(next.serviceNames || next.notes || 'Заявка')}</strong><em>${escHtml([next.date, next.time].filter(Boolean).join(' · ') || String(next.createdAt || '').slice(0,16))}</em><small>${escHtml(next.masterName || 'Мастер не назначен')}</small></span><b>${cabinetStatusText(next.status)}</b>
    </button>` : `<button type="button" class="kcab-empty-action kcab-empty-action-" data-kroute="services"><span>+</span><strong>Записаться на услугу</strong><em>Диагностика, ремонт или установка</em></button>`;
    const body = `
      <main class="kcab-dashboard" data-kcab-dashboard="stable">
        <section class="kcab-user-card kcab-user-card-">
          <span class="kcab-avatar">${u.photoUrl ? `<img src="${escHtml(u.photoUrl)}" alt="${escHtml(u.name || 'Профиль')}">` : `<b>${escHtml(u.initials || (u.name || 'K')[0] || 'K')}</b>`}</span>
          <span class="kcab-user-main"><strong>${escHtml(u.name || 'Пользователь')}</strong><em>${escHtml(u.phone || 'Телефон не указан')}</em><small>${escHtml(u.city || 'Город не указан')}</small></span>
          <button type="button" class="kcab-edit" onclick="return kcabGo('cabinet:profile:edit')">Изменить</button>
        </section>

        <section class="kcab-dashboard-main" aria-label="Краткая сводка кабинета">
          <div class="kcab-dashboard-col">
            <h2>Основной автомобиль</h2>
            ${primaryCarHtml}
          </div>
          <div class="kcab-dashboard-col">
            <h2>Ближайшая запись</h2>
            ${nextHtml}
          </div>
        </section>

        <section class="kcab-quick" aria-label="Быстрые действия">
          ${quick.map(([hash,label,sub,ico]) => `<button type="button" class="kcab-tile kcab-tile-" onclick="return kcabGo('cabinet:${escJs(hash)}')"><span>${cabinetIcon(ico)}</span><b>${escHtml(label)}</b><small>${escHtml(sub)}</small></button>`).join('')}
          <button type="button" class="kcab-tile kcab-tile- kcab-tile--accent" data-kroute="services"><span>+</span><b>Записаться</b><small>Новая заявка</small></button>
        </section>

        <section class="kcab-stats kcab-stats-" aria-label="Статистика заявок">
          <div><b>${ctx.processCount}</b><span>В работе</span></div>
          <div><b>${ctx.plannedCount}</b><span>Запланировано</span></div>
          <div><b>${ctx.doneCount}</b><span>Выполнено</span></div>
          <div><b>${ctx.cancelCount}</b><span>Отменено</span></div>
        </section>
      </main>
    `;
    return renderCabinetShell(ctx, route, 'Кабинет', 'Краткая сводка клиента', body, { action: ctx.roleShortcut || `<button type="button" class="kcab-logout" id="logoutBtn">Выйти</button>` });
  }

  function renderCabinetProfileView(ctx, route){
    const u = ctx.u || {};
    const initials = cabinetProfileInitials(u);
    const body = `<section class="kcab-profile-hero">
      <span class="kcab-avatar kcab-avatar--profile">${u.photoUrl ? `<img src="${escAttr(u.photoUrl)}" alt="${escAttr(u.name || 'Профиль')}">` : `<b>${escHtml(initials)}</b>`}</span>
      <div class="kcab-profile-main"><strong>${escHtml(u.name || 'Пользователь')}</strong><em>${escHtml(u.phone ? formatPhone(u.phone) : 'Телефон не указан')}</em><small>${escHtml(u.city || 'Город не указан')}</small></div>
      <button type="button" class="kcab-profile-edit" onclick="return kcabGo('cabinet:profile:edit')">Редактировать</button>
    </section>
    <section class="kcab-fields kcab-fields--profile">${cabinetProfileRows(ctx)}</section>
    <section class="kcab-profile-note"><b>Данные профиля</b><p>Эти данные используются для записи на услуги, заявок, чатов и сервисной истории автомобиля.</p></section>`;
    return renderCabinetShell(ctx, route, 'Профиль', 'Контактные данные клиента', body, { action:`<button type="button" class="kcab-text-btn" onclick="return kcabGo('cabinet:profile:edit')">Изменить</button>` });
  }

  function renderCabinetProfileEdit(ctx, route){
    const u = ctx.u || {};
    const phoneValue = u.phone ? formatPhone(u.phone) : '';
    const phoneReadonly = u.phone ? ' readonly aria-readonly="true"' : '';
    const carValue = u.car || ctx.primaryVehicle?.title || '';
    const body = `<section class="kcab-form-card kcab-profile-form">
      <label><span>Имя</span><input id="kcab-pf-name" autocomplete="name" value="${escAttr(u.name || '')}" placeholder="Ваше имя"></label>
      <label><span>Телефон</span><input id="kcab-pf-phone" type="tel" inputmode="tel" autocomplete="tel" value="${escAttr(phoneValue)}" placeholder="+7 (___) ___ __ __" oninput="this.value=formatPhone(this.value)"${phoneReadonly}></label>
      <label><span>Email</span><input id="kcab-pf-email" type="email" autocomplete="email" value="${escAttr(u.email || '')}" placeholder="mail@example.com"></label>
      <label><span>Город</span><input id="kcab-pf-city" autocomplete="address-level2" value="${escAttr(u.city || '')}" placeholder="Усть-Каменогорск"></label>
      <label><span>Основной автомобиль</span><input id="kcab-pf-car" value="${escAttr(carValue)}" placeholder="Toyota Camry 70"></label>
      <label><span>Комментарий</span><textarea id="kcab-pf-spec" placeholder="Дополнительная информация">${escHtml(u.spec || '')}</textarea></label>
      <div class="kcab-form-actions"><button type="button" class="btn btn-outline" onclick="return kcabGo('cabinet:profile')">Отмена</button><button type="button" class="btn btn-primary" id="kcab-save-profile-btn" onclick="return kcabSaveProfile()">Сохранить</button></div>
      <div class="kcab-toast" id="kcab-profile-toast">Профиль сохранён</div>
    </section>`;
    return renderCabinetShell(ctx, route, 'Редактирование профиля', 'Имя, телефон, город и основной автомобиль', body);
  }

  function renderCabinetCars(ctx, route){
    const cars = Array.isArray(ctx.clientVehicles) ? ctx.clientVehicles : [];
    const list = cars.length ? cars.map(v => {
      const vid = String(v.id || '').trim();
      const openRoute = vid ? ('cabinet:car:view:' + vid) : 'cabinet:car';
      return `<button type="button" class="kcab-car-card" onclick="return kcabGo('${escJs(openRoute)}')">
        <span class="kcab-car-ico">${escHtml(v.icon || '▱')}</span><span><strong>${escHtml(cabinetVehicleTitle(v))}</strong><em>${escHtml(cabinetVehicleSub(v))}</em><small>${v.isDefault ? 'Основной автомобиль' : 'Дополнительный автомобиль'}</small></span><b>›</b>
      </button>`;
    }).join('') : `<div class="kcab-empty"><span>▱</span><b>Автомобилей пока нет</b><p>Добавьте машину, чтобы вести историю ремонта и сервисную книжку.</p></div>`;
    const body = `<div id="cp-car" class="kcab-route-anchor"></div><section class="kcab-list">${list}</section><button type="button" class="kcab-wide-action" onclick="return kcabGo('cabinet:car:new')"><span>+</span> Добавить автомобиль</button>`;
    return renderCabinetShell(ctx, route, 'Мой гараж', cars.length ? 'Автомобили, VIN, пробег и сервисная история' : 'Гараж пуст — добавьте первую машину', body, { action:`<button type="button" class="kcab-plus" onclick="return kcabGo('cabinet:car:new')">+</button>` });
  }

  function renderCabinetCarDetailLegacy(ctx, route){
    const cars = Array.isArray(ctx.clientVehicles) ? ctx.clientVehicles : [];
    if (route.action === 'new') {
      const body = `<div id="cp-car" class="kcab-route-anchor"></div><section class="kcab-editor-shell kcab-editor-shell--vehicle"><div class="kcab-editor-loading">Загрузка формы автомобиля...</div><div id="kcab-vehicle-editor-host" data-kcab-vehicle-action="new" data-kcab-vehicle-id=""><div id="vehicle-editor-wrap" class="kcab-vehicle-editor-wrap"></div></div></section>`;
      return renderCabinetShell(ctx, route, 'Добавить автомобиль', 'Карточка машины', body);
    }
    const v = cabinetFindVehicle(ctx, route.id);
    if (!v) return renderCabinetMissingVehicle(ctx, route);
    if (route.action === 'edit') {
      const id = escHtml(v.id || route.id || '');
      const body = `<div id="cp-car" class="kcab-route-anchor"></div><section class="kcab-editor-shell kcab-editor-shell--vehicle"><div class="kcab-editor-loading">Загрузка формы автомобиля...</div><div id="kcab-vehicle-editor-host" data-kcab-vehicle-action="edit" data-kcab-vehicle-id="${id}"><div id="vehicle-editor-wrap" class="kcab-vehicle-editor-wrap"></div></div></section>`;
      return renderCabinetShell(ctx, route, 'Редактировать автомобиль', cabinetVehicleTitle(v), body);
    }
    const body = `<div id="cp-car" class="kcab-route-anchor"></div><section class="kcab-detail-card">
      <div class="kcab-detail-hero"><span>${escHtml(v.icon || '▱')}</span><div><h2>${escHtml(cabinetVehicleTitle(v))}</h2><p>${escHtml(cabinetVehicleSub(v))}</p></div></div>
      <div class="kcab-fields">
        ${[['Марка',v.brand],['Модель',v.model],['Год',v.year],['Госномер',v.plate],['VIN',v.vin],['Пробег',v.mileageKm ? Number(v.mileageKm).toLocaleString('ru') + ' км' : ''],['Кузов',v.bodyType],['Двигатель',v.engineType],['КПП',v.transmission],['Цвет',v.color]].filter(x=>x[1]).map(([k,val])=>`<div><span>${escHtml(k)}</span><b>${escHtml(String(val))}</b></div>`).join('') || '<div><span>Данные</span><b>Карточка требует заполнения</b></div>'}
      </div>
      <div class="kcab-form-actions"><button type="button" class="btn btn-outline" onclick="window.openVehicleCard?.('${escJs(v.id || '')}')">Полная карточка</button><button type="button" class="btn btn-primary" onclick="return kcabGo('cabinet:car:edit:${escJs(v.id || '')}')">Редактировать</button></div>
    </section>`;
    return renderCabinetShell(ctx, route, 'Карточка автомобиля', 'Основные данные и быстрые действия', body);
  }


  // clean two-stage vehicle creation/editing for the new kcab cabinet.
  // Stage 1 is the client minimum: brand/model/plate/year/VIN. Stage 2 is the vehicle card:
  // optional technical data, client notes, master service description and repair history binding.
  function kcabVehicleOrders(v, ctx){
    return vehicleFlowOrders(v, Array.isArray(ctx?.liveOrders) ? ctx.liveOrders : []);
  }

  function kcabCanEditMasterVehicleNote(){
    try {
      const u = window.App?.getState?.()?.user || S?.user || null;
      return !!(u && (window.RBAC?.atLeast?.(u, 'master') || window.RBAC?.atLeast?.(u, 'admin') || window.RBAC?.atLeast?.(u, 'owner') || window.RBAC?.atLeast?.(u, 'sto')));
    } catch(_e) { return false; }
  }

  function kcabVehicleInput(id, label, value, placeholder, opts){
    const o = opts || {};
    const tag = o.textarea ? 'textarea' : 'input';
    const type = o.type || 'text';
    const req = o.required ? ' required' : '';
    const ro = o.readonly ? ' readonly aria-readonly="true"' : '';
    const dis = o.disabled ? ' disabled aria-disabled="true"' : '';
    const attrs = `id="${escAttr(id)}" ${tag === 'input' ? `type="${escAttr(type)}"` : ''} ${o.inputmode ? `inputmode="${escAttr(o.inputmode)}"` : ''} value="${tag === 'input' ? escAttr(value || '') : ''}" placeholder="${escAttr(placeholder || '')}"${req}${ro}${dis}`;
    return `<label class="kcab-vform-field ${o.wide ? 'is-wide' : ''}"><span>${escHtml(label)}${o.required ? ' <b>*</b>' : ''}</span>${tag === 'textarea' ? `<textarea ${attrs} rows="${Number(o.rows || 3)}">${escHtml(value || '')}</textarea>` : `<input ${attrs}>`}</label>`;
  }

  function kcabVehiclePayload(id){
    const old = id ? (window.DB?.Vehicles?.get?.(id) || {}) : {};
    const val = k => String(document.getElementById(k)?.value || '').trim();
    const mileage = Math.max(0, Number(val('kcab-v-mileage').replace(/\s+/g, '')) || 0);
    const brand = val('kcab-v-brand');
    const model = val('kcab-v-model');
    const year = val('kcab-v-year');
    const plate = val('kcab-v-plate').toUpperCase();
    const vin = val('kcab-v-vin').toUpperCase();
    const title = [brand, model, year].filter(Boolean).join(' ').trim() || [brand, plate].filter(Boolean).join(' · ').trim() || String(old.title || '').trim();
    const canMaster = kcabCanEditMasterVehicleNote();
    const existing = Array.isArray(window.DB?.Vehicles?.getMine?.()) ? window.DB.Vehicles.getMine() : [];
    return Object.assign({}, old, {
      id: old.id || id || '',
      icon: old.icon || '▱',
      title,
      brand,
      model,
      year,
      plate,
      vin,
      color: val('kcab-v-color'),
      mileageKm: mileage,
      bodyType: val('kcab-v-body'),
      engineType: val('kcab-v-engine'),
      engineVolume: val('kcab-v-engine-volume'),
      fuelType: val('kcab-v-fuel'),
      transmission: val('kcab-v-transmission'),
      driveType: val('kcab-v-drive'),
      tires: val('kcab-v-tires'),
      battery: val('kcab-v-battery'),
      oilType: val('kcab-v-oil'),
      knownIssues: val('kcab-v-known'),
      note: val('kcab-v-client-note'),
      serviceAt: val('kcab-v-service-at'),
      serviceNote: canMaster ? val('kcab-v-master-note') : String(old.serviceNote || ''),
      isDefault: old.isDefault || (!old.id && existing.length === 0)
    });
  }

  window.kcabSaveVehicle = async function(mode, id){
    const isNew = String(mode || '') === 'new';
    const payload = kcabVehiclePayload(id || '');
    const btn = document.getElementById('kcab-save-vehicle-btn');
    if (!payload.brand) { showToast('Укажите марку автомобиля', 'error'); document.getElementById('kcab-v-brand')?.focus?.(); return false; }
    if (!payload.model) { showToast('Укажите модель автомобиля', 'error'); document.getElementById('kcab-v-model')?.focus?.(); return false; }
    if (!payload.plate) { showToast('Укажите госномер автомобиля', 'error'); document.getElementById('kcab-v-plate')?.focus?.(); return false; }
    if (!payload.title) { showToast('Не удалось сформировать название автомобиля', 'error'); return false; }
    if (btn) { btn.disabled = true; btn.textContent = isNew ? 'Создаю...' : 'Сохраняю...'; }
    try {
      const saved = await window.DB?.Vehicles?.upsert?.(payload);
      if (!saved?.id) throw new Error('vehicle_not_saved');
      if (saved.isDefault && window.App?.mergeUserPatch) window.App.mergeUserPatch({ car: saved.title || payload.title || '' });
      showToast(isNew ? 'Автомобиль создан. Открыта карточка.' : 'Карточка автомобиля сохранена');
      try { window.__vehicleEditorState = null; window.__vehicleEditorStep = 1; } catch(_e) {}
      setTimeout(()=>{ try { kcabGo('cabinet:car:view:' + saved.id); } catch(_e) { location.hash = '#cabinet:car:view:' + encodeURIComponent(saved.id); } }, 180);
    } catch(e) {
      showToast((e && e.message) || 'Не удалось сохранить автомобиль', 'error');
      if (btn) { btn.disabled = false; btn.textContent = isNew ? 'Создать автомобиль' : 'Сохранить карточку'; }
    }
    return false;
  };

  function renderCabinetVehicleForm(ctx, route, vehicle){
    const isNew = !vehicle;
    const v = vehicle || {};
    const canMaster = kcabCanEditMasterVehicleNote();
    const disabledMasterText = canMaster ? '' : 'Заполняет мастер или СТО при обслуживании клиента';
    const title = isNew ? 'Добавить автомобиль' : 'Редактировать карточку';
    const subtitle = isNew ? '1 часть — клиент заполняет минимум и создаёт машину' : 'Основные данные и карточка автомобиля';
    const body = `<div id="cp-car" class="kcab-route-anchor"></div>
      <section class="kcab-vcreate-note">
        <b>Схема заполнения</b>
        <p><strong>1 часть:</strong> клиент указывает минимум и создаёт машину. <strong>2 часть:</strong> карточка автомобиля — остальные данные можно заполнить позже. Мастер может добавить сервисное описание после обслуживания.</p>
      </section>
      <form class="kcab-vform" onsubmit="return kcabSaveVehicle('${isNew ? 'new' : 'edit'}','${escJs(v.id || route.id || '')}')">
        <section class="kcab-vform-card is-required">
          <div class="kcab-vform-title"><span>1</span><div><b>Создание машины клиентом</b><small>Эти поля нужны, чтобы привязать заявки и историю ремонта к конкретному автомобилю.</small></div></div>
          <div class="kcab-vform-grid">
            ${kcabVehicleInput('kcab-v-brand', 'Марка', v.brand || '', 'Toyota', { required:true })}
            ${kcabVehicleInput('kcab-v-model', 'Модель', v.model || '', 'Camry', { required:true })}
            ${kcabVehicleInput('kcab-v-plate', 'Госномер', v.plate || '', '123 ABC 16', { required:true })}
            ${kcabVehicleInput('kcab-v-year', 'Год', v.year || '', '2018', { inputmode:'numeric' })}
            ${kcabVehicleInput('kcab-v-vin', 'VIN', v.vin || '', 'Можно заполнить позже')}
            ${kcabVehicleInput('kcab-v-color', 'Цвет', v.color || '', 'Белый')}
          </div>
        </section>
        <section class="kcab-vform-card ${isNew ? 'is-optional-new' : ''}">
          <div class="kcab-vform-title"><span>2</span><div><b>Карточка автомобиля</b><small>${isNew ? 'Эти поля необязательны. После создания машина откроется как отдельная карточка.' : 'Дополнительные параметры, заметки клиента и сервисное описание мастера.'}</small></div></div>
          <div class="kcab-vform-grid">
            ${kcabVehicleInput('kcab-v-mileage', 'Пробег, км', v.mileageKm ? String(v.mileageKm) : '', '150000', { inputmode:'numeric' })}
            ${kcabVehicleInput('kcab-v-body', 'Кузов', v.bodyType || '', 'седан / универсал')}
            ${kcabVehicleInput('kcab-v-engine', 'Двигатель', v.engineType || '', 'M111 / 2.0')}
            ${kcabVehicleInput('kcab-v-engine-volume', 'Объём', v.engineVolume || '', '2.0')}
            ${kcabVehicleInput('kcab-v-fuel', 'Топливо', v.fuelType || '', 'бензин / дизель')}
            ${kcabVehicleInput('kcab-v-transmission', 'КПП', v.transmission || '', 'АКПП / МКПП')}
            ${kcabVehicleInput('kcab-v-drive', 'Привод', v.driveType || '', 'передний / задний / 4WD')}
            ${kcabVehicleInput('kcab-v-service-at', 'Последнее ТО', v.serviceAt ? String(v.serviceAt).slice(0,10) : '', '', { type:'date' })}
            ${kcabVehicleInput('kcab-v-oil', 'Масло', v.oilType || '', '5W-30')}
            ${kcabVehicleInput('kcab-v-tires', 'Шины', v.tires || '', '215/55 R17')}
            ${kcabVehicleInput('kcab-v-battery', 'АКБ', v.battery || '', '75Ah')}
            ${kcabVehicleInput('kcab-v-known', 'Что беспокоит по машине', v.knownIssues || '', 'Например: плавают обороты, шумит подвеска', { textarea:true, wide:true })}
            ${kcabVehicleInput('kcab-v-client-note', 'Комментарий клиента', v.note || '', 'Любая информация для мастера', { textarea:true, wide:true })}
            ${kcabVehicleInput('kcab-v-master-note', 'Доп. описание мастера / СТО', v.serviceNote || '', disabledMasterText || 'Сервисные наблюдения, рекомендации, особенности ремонта', { textarea:true, wide:true, disabled:!canMaster })}
          </div>
        </section>
        <div class="kcab-form-actions kcab-vform-actions">
          <button type="button" class="btn btn-outline" onclick="return kcabGo('${isNew ? 'cabinet:car' : ('cabinet:car:view:' + escJs(v.id || route.id || ''))}')">Отмена</button>
          <button type="submit" class="btn btn-primary" id="kcab-save-vehicle-btn">${isNew ? 'Создать автомобиль' : 'Сохранить карточку'}</button>
        </div>
      </form>`;
    return renderCabinetShell(ctx, route, title, subtitle, body);
  }

  function renderCabinetVehicleHistory(v, ctx){
    const rows = kcabVehicleOrders(v, ctx);
    if (!rows.length) return `<section class="kcab-vhistory"><div class="kcab-vhistory-head"><b>История ремонта</b><small>Заявки будут привязываться к этой машине</small></div><div class="kcab-empty kcab-empty--small"><span>▤</span><b>Истории пока нет</b><p>После записи на ремонт или диагностику здесь появятся работы именно по этому автомобилю.</p><button type="button" onclick="App.go('services')">Записаться</button></div></section>`;
    return `<section class="kcab-vhistory"><div class="kcab-vhistory-head"><b>История ремонта</b><small>${rows.length} записей по автомобилю</small></div><div class="kcab-list">${rows.slice(0,12).map(o=> window.KaretaOrderFlow?.card ? KaretaOrderFlow.card(o, v) : `<button type="button" class="kcab-order-card" onclick="openClientOrderModal('${escJs(o.id || '')}')"><span class="kcab-order-ico">▤</span><span><strong>${escHtml(o.serviceNames || o.notes || 'Ремонт')}</strong><em>${escHtml([o.date, o.time].filter(Boolean).join(' · ') || String(o.createdAt || '').slice(0,16))}</em><small>${escHtml(o.masterName || o.stoName || 'KARETA.KZ')}</small></span><b class="${cabinetStatusClass(o.status)}">${cabinetStatusText(o.status)}</b></button>`).join('')}</div></section>`;
  }

  function renderCabinetVehicleOrderDetail(ctx, route, v){
    const order = window.KaretaOrderFlow?.findForVehicle?.(v, route.orderId, ctx) || null;
    if (!order) {
      const body = `<div id="cp-car" class="kcab-route-anchor"></div><section class="kcab-empty kcab-empty--route kcab-order-empty"><span>▤</span><b>Запись не найдена</b><p>Заявка не связана с этой машиной, была удалена или данные ещё не загрузились.</p><div class="kcab-empty-actions"><button type="button" onclick="return kcabGo('cabinet:car:view:${escJs(v.id || route.id || '')}')">К карточке автомобиля</button><button type="button" onclick="App.go('myorders')">Мои заявки</button></div></section>`;
      return renderCabinetShell(ctx, route, 'Запись ремонта', 'Карточка заявки по выбранному автомобилю', body);
    }
    const m = window.KaretaOrderFlow?.normalize?.(order) || orderFlowNormalize(order);
    const raw = m.raw || order;
    const details = [
      ['Тип', m.kind === 'parts' ? 'Запчасти' : 'Ремонт / услуга'],
      ['Статус', cabinetStatusText(m.status)],
      ['Дата', m.date],
      ['Автомобиль', m.vehicle],
      ['VIN', m.vin],
      ['Госномер', m.plate],
      ['Мастер / СТО', m.provider],
      ['Сумма', m.price]
    ].filter(x=>x[1] && x[1] !== '—');
    const notes = String(raw.notes || raw.comment || raw.clientComment || '').trim();
    const masterText = String(raw.masterComment || raw.masterNote || raw.serviceNote || raw.reportText || '').trim();
    const lifecycle = window.KaretaOrderActions?.lifecycleHtml ? KaretaOrderActions.lifecycleHtml(raw || order) : '';
    const support = window.KaretaOrderActions?.supportHtml ? KaretaOrderActions.supportHtml(raw || order, v) : '';
    const actions = window.KaretaOrderActions?.detailActionsHtml ? KaretaOrderActions.detailActionsHtml(raw || order, v) : `<div class="kcab-form-actions kcab-order-actions"><button type="button" class="btn btn-outline" onclick="return kcabGo('cabinet:car:view:${escJs(v.id || '')}')">К автомобилю</button><button type="button" class="btn btn-outline" onclick="App.go('myorders')">Все заявки</button><button type="button" class="btn btn-primary" onclick="${m.id ? "openClientOrderModal('" + escJs(m.id) + "')" : "App.go('myorders')"}">Открыть полную заявку</button></div>`;
    const body = `<div id="cp-car" class="kcab-route-anchor"></div>
      <section class="kcab-detail-card kcab-order-detail">
        <div class="kcab-order-detail-head">
          <span>${m.kind === 'parts' ? '▣' : '▤'}</span>
          <div><h2>${escHtml(m.title)}</h2><p>${escHtml(cabinetVehicleTitle(v))}</p></div>
          <b class="${cabinetStatusClass(m.status)}">${cabinetStatusText(m.status)}</b>
        </div>
        ${lifecycle}
        <div class="kcab-fields kcab-order-fields">${details.map(([k,val])=>`<div><span>${escHtml(k)}</span><b>${escHtml(String(val))}</b></div>`).join('')}</div>
        ${support}
        <div class="kcab-vnotes kcab-order-notes">
          <div><span>Описание клиента</span><p>${escHtml(notes || 'Описание не указано.')}</p></div>
          <div><span>Комментарий мастера / отчёт</span><p>${escHtml(masterText || 'Мастер добавит информацию после диагностики или выполнения работ.')}</p></div>
        </div>
        ${actions}
      </section>`;
    return renderCabinetShell(ctx, route, 'Запись ремонта', 'Детали заявки, связанной с автомобилем', body);
  }

  function renderCabinetCarDetail(ctx, route){
    if (route.action === 'new') {
      return renderCabinetVehicleForm(ctx, route, null);
    }
    const v = cabinetFindVehicle(ctx, route.id);
    if (!v) return renderCabinetMissingVehicle(ctx, route);
    if (route.action === 'edit') {
      return renderCabinetVehicleForm(ctx, route, v);
    }
    if (route.action === 'order') {
      return renderCabinetVehicleOrderDetail(ctx, route, v);
    }
    const optionalRows = [
      ['Марка',v.brand],['Модель',v.model],['Год',v.year],['Госномер',v.plate],['VIN',v.vin],['Цвет',v.color],
      ['Пробег',v.mileageKm ? Number(v.mileageKm).toLocaleString('ru') + ' км' : ''],['Кузов',v.bodyType],['Двигатель',v.engineType],['Объём',v.engineVolume],['Топливо',v.fuelType],['КПП',v.transmission],['Привод',v.driveType],['Масло',v.oilType],['Шины',v.tires],['АКБ',v.battery],['Последнее ТО',v.serviceAt ? String(v.serviceAt).slice(0,10) : '']
    ].filter(x=>x[1]);
    const body = `<div id="cp-car" class="kcab-route-anchor"></div>
      <section class="kcab-detail-card kcab-vehicle-card">
        <div class="kcab-detail-hero"><span>${escHtml(v.icon || '▱')}</span><div><h2>${escHtml(cabinetVehicleTitle(v))}</h2><p>${escHtml(cabinetVehicleSub(v))}</p></div></div>
        <div class="kcab-fields kcab-fields--vehicle">
          ${optionalRows.map(([k,val])=>`<div><span>${escHtml(k)}</span><b>${escHtml(String(val))}</b></div>`).join('') || '<div><span>Данные</span><b>Заполнены только основные сведения</b></div>'}
        </div>
        <div class="kcab-vnotes">
          <div><span>Комментарий клиента</span><p>${escHtml(v.note || 'Клиент пока не добавил комментарий.')}</p></div>
          <div><span>Описание мастера / СТО</span><p>${escHtml(v.serviceNote || 'Мастер добавит описание после диагностики или ремонта.')}</p></div>
          <div><span>Что беспокоит</span><p>${escHtml(v.knownIssues || 'Не указано.')}</p></div>
        </div>
        <div class="kcab-form-actions"><button type="button" class="btn btn-outline" data-kroute="cabinet:car">В гараж</button><button type="button" class="btn btn-primary" data-kroute="cabinet:car:edit:${escAttr(v.id || '')}">Редактировать карточку</button></div>
      </section>
      ${renderCabinetVehicleHistory(v, ctx)}`;
    return renderCabinetShell(ctx, route, 'Карточка автомобиля', 'Данные машины, описание мастера и история ремонта', body);
  }

  function getCabinetHistoryFilter(route){
    const f = String(route?.action || 'all').toLowerCase();
    return ['all','planned','process','done','cancel'].includes(f) ? f : 'all';
  }

  function cabinetHistoryFilterMatches(order, filter){
    const s = String(order?.status || 'new').toLowerCase();
    if (filter === 'planned') return ['new','wait','pending','booked'].includes(s);
    if (filter === 'process') return ['process','in_work','work'].includes(s);
    if (filter === 'done') return ['done','done_pending_client','closed','complete','completed'].includes(s);
    if (filter === 'cancel') return ['cancel','cancelled','canceled'].includes(s);
    return true;
  }

  function renderCabinetHistory(ctx, route){
    const filter = getCabinetHistoryFilter(route);
    const sourceRows = (ctx.liveOrders || []).slice().sort((a,b)=>String(b.date || b.createdAt || '').localeCompare(String(a.date || a.createdAt || '')));
    const rows = sourceRows.filter(o => cabinetHistoryFilterMatches(o, filter));
    const filters = [
      ['all','Все'], ['planned','Запланировано'], ['process','В работе'], ['done','Выполнено'], ['cancel','Отменено']
    ];
    const body = `<section class="kcab-filter-row">${filters.map(([key,label]) => `<button type="button" class="${filter === key ? 'active' : ''}" data-kroute="cabinet:history${key === 'all' ? '' : ':' + escAttr(key)}">${escHtml(label)}</button>`).join('')}</section><section class="kcab-list">
      ${rows.length ? rows.slice(0,30).map(o=>`<button type="button" class="kcab-order-card" data-k-action="open-order" data-order-id="${escAttr(o.id)}"><span class="kcab-order-ico">▤</span><span><strong>${escHtml(o.serviceNames || o.notes || o.clientCar || 'Заявка')}</strong><em>${escHtml([o.date, o.time].filter(Boolean).join(' · ') || String(o.createdAt || '').slice(0,16))}</em><small>${escHtml(o.masterName || o.clientCar || 'KARETA.KZ')}</small></span><b class="${cabinetStatusClass(o.status)}">${cabinetStatusText(o.status)}</b></button>`).join('') : `<div class="kcab-empty"><span>▤</span><b>${sourceRows.length ? 'По выбранному фильтру заявок нет' : 'История пока пуста'}</b><p>${sourceRows.length ? 'Смените фильтр или откройте полный список.' : 'После первой записи здесь появится сервисная книжка.'}</p><button type="button" data-kroute="${sourceRows.length ? 'cabinet:history' : 'services'}">${sourceRows.length ? 'Все заявки' : 'Записаться'}</button></div>`}
    </section>`;
    return renderCabinetShell(ctx, route, 'История обслуживания', 'Заявки, ремонты и сервисная книжка', body);
  }

  function renderCabinetLoyalty(ctx, route){
    const body = `<section class="kcab-wallet"><div><span>${escHtml(ctx.curLevel?.e || '₸')} ${escHtml(ctx.curLevel?.n || 'Клиент')}</span><b>${escHtml(ctx.curLevel?.disc || '5%')}</b></div><strong>${Number(ctx.loyaltyPts || 0).toLocaleString('ru')}</strong><p>доступно баллов · 1 балл = 1 ₸</p><i><em style="width:${Math.max(0, Math.min(100, Number(ctx.lvlPct || 0)))}%"></em></i><small>${ctx.nextLevel ? `До ${escHtml(ctx.nextLevel.n)}: ещё ${Number(ctx.nextLevel.min - ctx.loyaltyEarned).toLocaleString('ru')} баллов` : 'Максимальный уровень клиента'}</small></section>
      <section class="kcab-stats"><div><b>${Number(ctx.loyaltyEarned || 0).toLocaleString('ru')}</b><span>Заработано</span></div><div><b>${cabinetMoney(ctx.totalSpent)}</b><span>Потрачено</span></div><div><b>${Number(ctx.loyaltySpent || 0).toLocaleString('ru')}</b><span>Списано</span></div></section>
      <section class="kcab-list">${(ctx.loyaltyTxns || []).length ? ctx.loyaltyTxns.slice(0,20).map(t=>`<div class="kcab-txn"><span class="${t.type === 'spend' ? 'spend' : 'earn'}">${t.type === 'spend' ? '−' : '+'}${Number(t.pts || 0).toLocaleString('ru')}</span><div><strong>${escHtml(t.label || 'Операция')}</strong><em>${escHtml(t.date || '')}</em></div></div>`).join('') : `<div class="kcab-empty"><span>₸</span><b>Истории баллов пока нет</b><p>Баллы появятся после выполненного ремонта.</p></div>`}</section>`;
    return renderCabinetShell(ctx, route, 'Расходы и бонусы', 'Баллы, скидка и история оплат', body, { action:`<button type="button" class="kcab-plus" onclick="App.go('services')">+</button>` });
  }

  function renderCabinetNotifs(ctx, route){
    const body = `<section class="kcab-reminder-hero"><span>${cabinetIcon('bell')}</span><div><strong>${ctx.unreadCount ? ctx.unreadCount + ' новых уведомлений' : 'Все спокойно'}</strong><p>${ctx.unreadCount ? 'Проверьте новые сообщения и статусы заявок.' : 'Когда появятся запись, сообщение или напоминание по ТО — они будут здесь.'}</p></div></section><section class="kcab-list">
      ${(ctx.notifs || []).length ? ctx.notifs.slice(0,30).map((n,i)=>`<button type="button" class="kcab-notif ${n.unread ? 'unread' : ''}" data-k-action="notif-read" data-notif-id="${escAttr(String(n.id || i))}" data-notif-url="${escAttr(String(n.actionUrl || ''))}"><span>${escHtml(n.ico || '○')}</span><div><strong>${escHtml(n.title || 'Уведомление')}</strong><em>${escHtml(n.text || '')}</em><small>${escHtml(n.time || '')}</small></div></button>`).join('') : `<div class="kcab-empty"><span>○</span><b>Напоминаний нет</b><p>Создайте заявку или добавьте автомобиль — система покажет сроки обслуживания.</p><button type="button" data-kroute="cabinet:car">Открыть гараж</button></div>`}
    </section>`;
    return renderCabinetShell(ctx, route, 'Напоминания', 'Уведомления, записи и обслуживание', body, { action: ctx.unreadCount ? `<button type="button" class="kcab-text-btn" data-k-action="notifs-read-all">Прочитать</button>` : `<button type="button" class="kcab-text-btn" data-kroute="services">Записаться</button>` });
  }

  function renderCabinetSettings(ctx, route){
    const settingsHtml = (typeof _buildSettingsHTML === 'function') ? _buildSettingsHTML() : '<div class="kcab-empty"><span>□</span><b>Настройки временно недоступны</b><p>Откройте настройки позже или используйте меню сайта.</p></div>';
    const body = `<div id="cp-appsettings" class="kcab-settings-host"><div class="kcab-settings-card">${settingsHtml}</div></div>
      <section class="kcab-docs">
        <button type="button" onclick="App.go('privacy')"><span>□</span><b>Политика конфиденциальности</b><small>Открыть документ</small></button>
        <button type="button" onclick="App.go('terms')"><span>◇</span><b>Пользовательское соглашение</b><small>Открыть условия сервиса</small></button>
      </section>`;
    return renderCabinetShell(ctx, route, 'Документы и настройки', 'Тема, интерфейс, документы и параметры приложения', body);
  }

  function renderCabinetDiagnostics(ctx, route){
    const body = `<section class="kcab-grid kcab-grid--large">
      <button class="kcab-tile" type="button" onclick="window._openHomeCatalog&&window._openHomeCatalog('diagnostics')"><span>⌕</span><b>Компьютерная диагностика</b><small>Ошибки, датчики, ECU</small></button>
      <button class="kcab-tile" type="button" onclick="window._openHomeCatalog&&window._openHomeCatalog('battery')"><span>▱</span><b>Проверка АКБ</b><small>Напряжение и запуск</small></button>
      <button class="kcab-tile" type="button" onclick="window._openHomeCatalog&&window._openHomeCatalog('electric')"><span>⌁</span><b>Электрика</b><small>Проводка, свет, датчики</small></button>
    </section>`;
    return renderCabinetShell(ctx, route, 'Онлайн диагностика', 'Быстрый выбор диагностических услуг', body);
  }

  function renderCabinetLevel(ctx){
    const rawRoute = (ctx && ctx.routeHash) || (S && S._navOpts && S._navOpts.canonicalHash) || location.hash || '#cabinet';
    const route = getCabinetRoute(rawRoute);
    if (route.section === 'profile' && route.action === 'edit') return renderCabinetProfileEdit(ctx, route);
    if (route.section === 'profile') return renderCabinetProfileView(ctx, route);
    if (route.section === 'car' && route.level === 3) return renderCabinetCarDetail(ctx, route);
    if (route.section === 'car') return renderCabinetCars(ctx, route);
    if (route.section === 'history') return renderCabinetHistory(ctx, route);
    if (route.section === 'loyalty') return renderCabinetLoyalty(ctx, route);
    if (route.section === 'notifs') return renderCabinetNotifs(ctx, route);
    if (route.section === 'appsettings') return renderCabinetSettings(ctx, route);
    if (route.section === 'diagnostics') return renderCabinetDiagnostics(ctx, route);
    return renderCabinetHome(ctx, route);
  }

  function renderCabinet(){
    if(!loggedIn()) return`<div class="page"><section><div class="container"><div class="cab-locked">
      <div class="cab-locked-ico">◌</div>
      <div class="cab-locked-title">Личный кабинет</div>
      <div class="cab-locked-sub">Войдите в аккаунт, чтобы открыть кабинет, историю заявок и программу лояльности</div>
      <button class="btn btn-primary" style="margin-top:24px" onclick="App.showAuth('cabinet')">Войти по номеру телефона</button>
      <div style="margin-top:16px;font-size:12px;color:var(--text3)">Нет аккаунта? Он создаётся автоматически при первом входе</div>
    </div></div></section></div>`;

    const u=S.user; const r=RBAC.getRole(u);
    const isAdmin = RBAC.atLeast(u,'admin');
    const isMaster = RBAC.atLeast(u,'master');
    const isClient = r.id === 'client';
    try {
      document.body?.classList.toggle('kareta-role-cabinet-legacy', !isClient);
      document.body?.classList.toggle('kareta-role-cabinet-client', !!isClient);
      if(!isClient) clearCabinetLevelBodyFlags?.();
    } catch(_e) {}

    // Live orders from DB
    const cl = DB.Clients.getByPhone(u.phone);
    const dbOrders = cl
      ? DB.Orders.getAll({ clientId: cl.id })
      : DB.Orders.getAll().filter(o => (o.clientPhone||'').replace(/\D/g,'') === (u.phone||'').replace(/\D/g,''));

    // ── Реальная система баллов ──────────────────────────────
    const LOYALTY_KEY = 'kareta_loyalty_' + (u.phone||'').replace(/\D/g,'');
    const LOYALTY_LEVELS = [
      {e:'🥉',n:'Бронза',  min:0,    max:499,  disc:'5%',   discPct:5,  color:'#cd7f32'},
      {e:'🥈',n:'Серебро', min:500,  max:999,  disc:'7%',   discPct:7,  color:'#9ba3a9'},
      {e:'🥇',n:'Золото',  min:1000, max:2499, disc:'10%',  discPct:10, color:'#f5b800'},
      {e:'💎',n:'Платина', min:2500, max:9999, disc:'15% + приоритет', discPct:15, color:'#5dd8ff'},
    ];

    // Читаем историю транзакций из localStorage
    let _loyStore;
    try { _loyStore = JSON.parse(localStorage.getItem(LOYALTY_KEY) || 'null'); } catch(_e) {}
    if (!_loyStore || typeof _loyStore !== 'object') {
      _loyStore = { earned: 0, spent: 0, txns: [] };
    }

    // Синхронизируем с реальными заказами: начисляем за каждый выполненный заказ если ещё не начислено
    const doneOrders = dbOrders.filter(o=>o.status==='done');
    const processedIds = new Set((_loyStore.txns || []).filter(t=>t.type==='earn').map(t=>t.orderId).filter(Boolean));
    let _newEarned = 0;
    doneOrders.forEach(o => {
      if (processedIds.has(o.id)) return;
      const price = Number(o.price || 0);
      if (price <= 0) return;
      // 5% от суммы заказа = баллы
      const pts = Math.floor(price * 0.05);
      if (pts <= 0) return;
      _loyStore.txns.push({
        id: 'earn_' + o.id,
        type: 'earn',
        orderId: o.id,
        pts,
        label: o.serviceNames || 'Ремонт',
        date: (o.date || o.createdAt || '').slice(0, 10),
      });
      _newEarned += pts;
    });
    if (_newEarned > 0) {
      _loyStore.earned += _newEarned;
      try { localStorage.setItem(LOYALTY_KEY, JSON.stringify(_loyStore)); } catch(_e) {}
    }

    const loyaltyEarned = _loyStore.earned || 0;
    const loyaltySpent  = _loyStore.spent  || 0;
    const loyaltyPts    = Math.max(0, loyaltyEarned - loyaltySpent);
    const loyaltyTxns   = (_loyStore.txns || []).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));

    const curLevel = LOYALTY_LEVELS.slice().reverse().find(l=>loyaltyEarned>=l.min) || LOYALTY_LEVELS[0];
    const nextLevel = LOYALTY_LEVELS[LOYALTY_LEVELS.indexOf(curLevel)+1];
    const lvlPct = nextLevel
      ? Math.round((loyaltyEarned - curLevel.min) / (nextLevel.min - curLevel.min) * 100)
      : 100;
    const loyaltyLevels = LOYALTY_LEVELS;
    // ─────────────────────────────────────────────────────────

    const activeOrders = dbOrders.filter(o=>o.status==='process'||o.status==='new').length;
    const doneCount = doneOrders.length;
    const totalSpent = doneOrders.reduce((a,o)=>a+(o.price||0),0);

    // Role shortcut
    const roleShortcut = RBAC.can(u,'page.owner')
      ? `<button class="btn btn-ghost cab-role-btn" onclick="App.go('owner')">◇ Панель владельца</button>`
      : RBAC.can(u,'page.admin')
      ? `<button class="btn btn-ghost cab-role-btn" onclick="App.go('admin')">◇ Панель</button>`
      : RBAC.can(u,'page.master')
      ? `<button class="btn btn-ghost cab-role-btn" onclick="App.go('master')">⌁ Работа</button>`
      : '';

    const masterRec = isMaster ? ((window.DB?.Masters?.getMine?.() || window.DB?.Masters?.getByPhone?.(u.phone)) || null) : null;
    const masterId = masterRec?.id || '';
    const masterObj = masterRec;
    // stats и shop нужны только для мастера — безопасно объявляем здесь
    const stats = isMaster && masterId ? (window.DB?.Masters?.stats?.(masterId) || { revenue:0, ordersDone:0, rating:0 }) : { revenue:0, ordersDone:0, rating:0 };
    const shop  = isMaster && masterId ? (window.DB?.Shop?.getByMaster?.(masterId) || null) : null;
    const liveOrders = isAdmin
      ? DB.Orders.getAll({})
      : isMaster && masterRec
        ? (window.DB?.Orders?.forMaster?.(masterRec,{ excludeCancelled:false }) || DB.Orders.getAll({ masterId: masterRec.id }))
        : dbOrders;
    const hist = liveOrders.map(o=>({
      id: o.id,
      type: o.type || 'service_order',
      title: o.serviceNames || o.vehicleTitle || o.clientCar || 'Заявка',
      meta: [o.date, o.time].filter(Boolean).join(' · ') || String(o.createdAt||'').replace('T',' ').slice(0,16),
      price: `${Number(o.price||0).toLocaleString('ru')} ₸`,
      status: o.status || 'new',
      master: o.masterName || '—',
      order: o,
    }));
    const smap={done:'Выполнен',process:'В работе',wait:'Ожидает',new:'Новая',cancel:'Отменён'};
    const myOrders = liveOrders;

    const notifs = (window.DB?.Notifications?.getMine?.() || []).map((n,idx)=>({
      id: n.id || ('notif_'+idx),
      type: String(n.eventType||'').includes('error') ? 'danger' : String(n.eventType||'').includes('cancel') ? 'warning' : String(n.eventType||'').includes('message') ? 'info' : 'success',
      ico: String(n.eventType||'').includes('message') ? '◌' : String(n.eventType||'').includes('assign') ? '👨‍⌁' : String(n.eventType||'').includes('status') ? '📌' : String(n.entityType||'').includes('order') ? '▤' : '○',
      title: n.title || 'Уведомление',
      text: n.body || '',
      time: String(n.createdAt||'').replace('T',' ').slice(0,16),
      unread: !n.isRead,
      actionUrl: n.actionUrl || '',
    }));

    const cabinetHistoryHtml = `<div class="card" style="padding:18px 20px;margin-bottom:14px"><div class="row-sb"><div><div class="h-oswald-lg">□ История мастера</div><div style="font-size:12px;color:var(--text3);margin-top:4px">Автоистория по дням, заявкам, клиентам и отзывам сведена в личный кабинет.</div></div><button class="btn btn-outline" style="font-size:12px;padding:7px 12px" onclick="navMasterCabinet('history')">Открыть в кабинете</button></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:12px">${[
      [myOrders.length,'Всего заявок'],
      [myOrders.filter(o=>o.status==='done').length,'Выполнено'],
      [myOrders.filter(o=>o.status==='process').length,'Сейчас в работе'],
      [getPublicReviews('service').filter(r => String(r.masterId||'')===String(masterId||'') || String(r.masterName||'')===String(masterObj?.name||'')).length,'Отзывов клиентов']
    ].map(([n,l])=>`<div class="card" style="padding:12px 14px"><div class="h-oswald-lg">${escHtml(String(n))}</div><div style="font-size:11px;color:var(--text3);margin-top:4px">${escHtml(l)}</div></div>`).join('')}</div><div class="flex-col-8">${myOrders.slice().sort((a,b)=>String(b.date||b.createdAt||'').localeCompare(String(a.date||a.createdAt||''))).slice(0,6).map(o=>`<div class="garage-history-item" style="align-items:flex-start;gap:10px;padding:10px 12px"><div style="flex:1;min-width:0"><div class="name">${escHtml(o.clientName||'Клиент')} · ${escHtml(o.clientCar||'Авто')}</div><div class="meta">${escHtml(o.dateLabel||o.date||o.createdAt?.slice(0,10)||'—')} · ${escHtml(o.serviceNames||o.notes||'Заявка')}</div></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn btn-outline" style="font-size:11px;padding:6px 10px" onclick="OrderSystem.Detail.open('${o.id}')">▤</button></div></div>`).join('') || `<div class="card" style="padding:18px;text-align:center;color:var(--text3)">История пока пуста.</div>`}</div>`;
    const cabinetAnalyticsHtml = `<div class="card" style="padding:18px 20px;margin-bottom:14px"><div class="row-sb"><div><div class="h-oswald-lg">📈 Аналитика мастера</div><div style="font-size:12px;color:var(--text3);margin-top:4px">Ключевые KPI мастера вынесены в личный кабинет для быстрого обзора.</div></div><button class="btn btn-outline" style="font-size:12px;padding:7px 12px" onclick="navMasterCabinet('analytics')">Открыть в кабинете</button></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">${[
      [stats.revenue.toLocaleString('ru')+' ₸','Выручка'],
      [stats.ordersDone,'Выполнено'],
      [stats.rating?`${stats.rating} ★`:'—','Рейтинг'],
      [shop?.sales?.length||0,'Продаж магазина']
    ].map(([n,l])=>`<div class="card" style="padding:12px 14px"><div class="h-oswald-lg">${escHtml(String(n))}</div><div style="font-size:11px;color:var(--text3);margin-top:4px">${escHtml(l)}</div></div>`).join('')}</div>`;

    const cabinetIsSubroute = isClient && String(location.hash||'').startsWith('#cabinet:');
    const realClientVehicles = isClient ? getClientVehicles() : [];
    const clientVehiclesStable = isClient ? ((window.KARETA_CLIENT_CABINET_LEVEL !== false) ? realClientVehicles : (realClientVehicles.length ? realClientVehicles : cabinetRefVehicleFallbacks())) : [];
    const primaryVehicleStable = isClient ? (getPrimaryVehicle() || clientVehiclesStable[0] || null) : null;
    const providerStable = (typeof servicesAppGetFeaturedProvider === 'function') ? servicesAppGetFeaturedProvider() : servicesAppFallbackProvider();
    const nextOrderStable = isClient ? (dbOrders.find(o=>['new','wait','process'].includes(String(o.status||''))) || dbOrders[0] || null) : null;
    const plannedCountStable = dbOrders.filter(o=>['new','wait'].includes(String(o.status||''))).length;
    const processCountStable = dbOrders.filter(o=>String(o.status||'')==='process').length;
    const cancelCountStable = dbOrders.filter(o=>['cancel','cancelled'].includes(String(o.status||''))).length;

    // client uses the level cabinet by default. Legacy cabinet is preserved below as fallback
    // when window.KARETA_CLIENT_CABINET_LEVEL === false.
    if (isClient && window.KARETA_CLIENT_CABINET_LEVEL !== false) {
      return renderCabinetLevel({
        u, r, isClient, isAdmin, isMaster, roleShortcut, routeHash: (S._navOpts && S._navOpts.canonicalHash) || location.hash || 'cabinet',
        dbOrders, liveOrders, hist, notifs, unreadCount: Number(S.unread || notifs.filter(n=>n.unread).length || 0),
        clientVehicles: clientVehiclesStable, primaryVehicle: primaryVehicleStable, nextOrder: nextOrderStable, provider: providerStable,
        doneCount, plannedCount: plannedCountStable, processCount: processCountStable, cancelCount: cancelCountStable, totalSpent,
        loyaltyEarned, loyaltySpent, loyaltyPts, loyaltyTxns, curLevel, nextLevel, lvlPct, loyaltyLevels
      });
    }

    const cabinetRefProfileHtml = (isClient && !cabinetIsSubroute) ? `<section class="cabinet-ref">
      <div class="cabinet-ref-phone">
        <header class="cabinet-ref-head"><img src="/assets/onboarding/kareta_logo_full.png" alt="KARETA.KZ" loading="eager"><button class="cabinet-ref-bell" type="button" onclick="window.Notifs?.toggle?.()">${serviceMiniIconSvg('bell')}<i>2</i></button></header>
        <h1>Профиль</h1>
        <section class="cabinet-ref-user-card">
          <span class="cabinet-ref-avatar">${u.photoUrl ? `<img src="${escHtml(u.photoUrl)}" alt="${escHtml(u.name||'Профиль')}">` : `<b>${escHtml(u.initials || (u.name||'К')[0] || 'К')}</b>`}</span>
          <span class="cabinet-ref-user-body"><strong>${escHtml(u.name || 'Арман Нурланов')}</strong><em>${escHtml(u.phone || '+7 701 123 45 67')}</em><small>${escHtml(u.city || 'Алматы, Казахстан')}</small><mark>GOLD</mark><i>Постоянный клиент</i></span>
          <button type="button" onclick="openCabPaneModal('editprofile', true)"><span>✎</span><b>Изменить</b></button>
        </section>
        ${primaryVehicleStable ? cabinetRefVehicleCard(primaryVehicleStable, 0, true) : ''}
        <section class="cabinet-ref-section"><h2>Быстрые разделы</h2><div class="cabinet-ref-quick-grid">
          <button type="button" onclick="return kcabGo('cabinet:car')"><span>${serviceMiniIconSvg('car')}</span><b>Мои<br>автомобили</b></button>
          <button type="button" onclick="return kcabGo('cabinet:history')"><span>${serviceMiniIconSvg('calendar')}</span><b>История<br>обслуживания</b></button>
          <button type="button" onclick="return kcabGo('cabinet:history')"><span>▤</span><b>Сервисная<br>книжка</b></button>
          <button type="button" onclick="App.go('cabinet:loyalty')"><span>₸</span><b>Расходы</b></button>
          <button type="button" onclick="App.go('cabinet:appsettings')"><span>□</span><b>Документы</b></button>
          <button type="button" onclick="App.go('cabinet:notifs')"><span>${serviceMiniIconSvg('bell')}</span><b>Напоминания</b></button>
        </div></section>
        <section class="cabinet-ref-section"><h2>Ближайшая запись</h2><button type="button" class="cabinet-ref-booking" onclick="${nextOrderStable ? `openClientOrderModal('${escHtml(nextOrderStable.id)}')` : `window.servicesAppOpenRequest('diagnostics','engine_diag')`}">
          <span class="cabinet-ref-booking-img" style="background-image:url('/assets/services/kareta_service_thumb.svg')"></span>
          <span><strong>${escHtml(nextOrderStable?.masterName || providerStable.name || 'KARETA.KZ Service')} ${providerStable.verified ? '<i>✓</i>' : ''}</strong><em>□ ${escHtml(nextOrderStable?.date || '24 мая, суббота')} ${escHtml(nextOrderStable?.time ? 'в '+nextOrderStable.time : 'в 10:00')}</em><mark>${nextOrderStable ? 'Запланирован' : 'Записаться'}</mark><small>${escHtml(nextOrderStable?.serviceNames || 'Диагностика ходовой части и замена масла')}</small></span><b>›</b>
        </button></section>
        <section class="cabinet-ref-section cabinet-ref-section--stats"><h2>Моя статистика</h2><div class="cabinet-ref-stats">
          <div><span class="is-ok">✓</span><b>${doneCount}</b><small>Выполнено</small></div>
          <div><span class="is-plan">◷</span><b>${plannedCountStable}</b><small>Запланировано</small></div>
          <div><span class="is-work">⌁</span><b>${processCountStable}</b><small>В процессе</small></div>
          <div><span class="is-cancel">×</span><b>${cancelCountStable}</b><small>Отменено</small></div>
        </div></section>
      </div>
    </section>` : '';

    return`<div class="page ${isClient ? ('cabinet-profile-page ' + (!cabinetIsSubroute ? 'cabinet-profile-page--home' : 'cabinet-profile-page--sub')) : ''}">${cabinetRefProfileHtml}

    <!-- ── HERO ── -->
    <div class="cab-hero">
      <div class="container">
        <div class="cab-profile-row">
          <div class="cab-avatar-wrap" onclick="document.getElementById('cab-photo-input').click()" title="Изменить фото профиля" style="cursor:pointer">
            ${u.photoUrl
              ? `<img class="cab-avatar cab-avatar--photo" src="${escHtml(u.photoUrl)}" alt="${escHtml(u.initials||'?')}">`
              : `<div class="cab-avatar" style="background:linear-gradient(135deg,${r.color},${r.color}88)">${u.initials}</div>`}
            <div class="cab-av-camera">📷</div>
            ${activeOrders>0?`<div class="cab-av-badge">${activeOrders}</div>`:''}
            <input type="file" id="cab-photo-input" accept="image/*" style="display:none" onchange="window.cabUploadPhoto(this)">
          </div>
          <div class="cab-profile-info">
            <div class="cab-name">${u.name}</div>
            <div class="cab-profile-meta">
              <span class="rbadge ${r.id}">${r.emoji} ${r.label}</span>
              <span class="cab-phone-chip">📱 ${u.phone||'—'}</span>
              ${(() => { const pv = getPrimaryVehicle(); return pv ? `<span class="cab-car-chip">${escHtml(pv.icon||'▱')} ${escHtml(pv.title||u.car||'Автомобиль')}</span>` : (u.car?`<span class="cab-car-chip">▱ ${escHtml(u.car)}</span>`:''); })()}
            </div>
          </div>
          <div class="cab-profile-actions">
            ${roleShortcut}
            <button class="logout-btn" id="logoutBtn">🚪 Выйти</button>
          </div>
        </div>

        <!-- mini stats for client -->
        ${isClient ? `<div class="cab-mini-stats cab-mini-stats--max3">
          <div class="cab-ms-item">
            <div class="cab-ms-num">${Math.max(getClientVehicles().length, (getPrimaryVehicle() || u.car) ? 1 : 0)}</div>
            <div class="cab-ms-lbl">Авто</div>
          </div>
          <div class="cab-ms-item">
            <div class="cab-ms-num" style="color:var(--orange)">${hist.length}</div>
            <div class="cab-ms-lbl">Заявки</div>
          </div>
          <div class="cab-ms-item">
            <div class="cab-ms-num" style="color:var(--green)">${loyaltyPts}</div>
            <div class="cab-ms-lbl">Баллы</div>
          </div>
        </div>` : ''}

        <!-- cab-tab-card кнопки перенесены в #drawer. Скрытые tab-switcher кнопки сохраняем для совместимости -->
        <div class="cab-tabs cab-tabs--hidden" aria-hidden="true" style="display:none">
          <button class="cab-tab cab-tab-card" data-tab="editprofile"></button>
          ${isClient?`<button class="cab-tab cab-tab-card" data-tab="car"></button>`:''} 
          ${isClient?`<button class="cab-tab cab-tab-card" data-tab="stats"></button>`:''}
          ${isClient?`<button class="cab-tab cab-tab-card" data-tab="loyalty"></button>`:''}
          ${isClient?`<button class="cab-tab cab-tab-card" data-tab="diagnostics"></button>`:''}
          <button class="cab-tab cab-tab-card" data-tab="appsettings"></button>
        </div>
      </div>
    </div>

    <!-- ══ STATS ══ -->
    ${isClient?`<div class="cab-pane cabinet-reference-pane" id="cp-stats">
      <div class="container">
        <div class="cst-grid">
          <!-- Блок заявок -->
          <div class="cst-card card">
            <div class="cst-card-ico">⌁</div>
            <div class="cst-card-val">${doneOrders.length + dbOrders.filter(o=>o.status==='process'||o.status==='new').length}</div>
            <div class="cst-card-lbl">Всего заявок</div>
          </div>
          <div class="cst-card card">
            <div class="cst-card-ico">✅</div>
            <div class="cst-card-val">${doneOrders.length}</div>
            <div class="cst-card-lbl">Выполнено</div>
          </div>
          <div class="cst-card card">
            <div class="cst-card-ico">▥</div>
            <div class="cst-card-val">${Number(totalSpent).toLocaleString('ru')} ₸</div>
            <div class="cst-card-lbl">Потрачено</div>
          </div>
          <div class="cst-card card">
            <div class="cst-card-ico">▣</div>
            <div class="cst-card-val">${dbOrders.filter(o=>String(o.type||'service_order')==='parts_request').length}</div>
            <div class="cst-card-lbl">Запчастей</div>
          </div>
        </div>

        <!-- Последние заявки -->
        <div class="cst-section-title">Последние заявки</div>
        <div class="cst-orders">
          ${(()=>{
            const last = dbOrders.slice(0,5);
            if (!last.length) return '<div class="cst-empty">Заявок пока нет. <button class="btn btn-primary" style="font-size:12px;padding:6px 14px;margin-left:8px" onclick="App.go(\'services\')">Записаться</button></div>';
            return last.map(o=>{
              const isParts = String(o.type||'service_order')==='parts_request';
              const sIco = {done:'✅',process:'⌁',new:'🕐',cancelled:'✖'}[o.status]||'▤';
              const oid = escHtml(o.id);
              return `<button class="cst-order-row" onclick="openClientOrderModal('${oid}')">
                <span class="cst-order-ico">${sIco}</span>
                <span class="cst-order-body">
                  <span class="cst-order-name">${escHtml(o.serviceNames||o.notes||'Заявка')}</span>
                  <span class="cst-order-meta">${isParts?'▣ Запчасть':'⌁ Ремонт'} · ${escHtml(String(o.date||o.createdAt||'').slice(0,10))}</span>
                </span>
                <span class="cst-order-price">${Number(o.price||0).toLocaleString('ru')} ₸</span>
              </button>`;
            }).join('');
          })()}
        </div>
      </div>
    </div>`:''}

    <!-- ══ EDITPROFILE ══ -->
    <div class="cab-pane cabinet-reference-pane" id="cp-editprofile">
      <div class="container">
        <div class="cab-pane-layout">
          <div class="profile-form-card card">
            ${('Notification' in window && Notification.permission === 'default') ? `
          <div class="push-banner">
            <div style="font-size:22px">○</div>
            <div class="push-banner-text">
              <div class="push-banner-t">Включить уведомления</div>
              <div class="push-banner-s">Мы уведомим, когда ремонт будет готов</div>
            </div>
            <button class="btn btn-primary" style="font-size:12px;padding:8px 16px;flex-shrink:0"
              onclick="PushNotifs.requestPermission().then(ok=>{if(ok)this.closest('.push-banner').remove()})">
              Разрешить
            </button>
          </div>` : ''}
          <div class="pfc-title">Личные данные</div>
            <div class="profile-form">
              <div class="pf-group">
                <label class="pf-label">Имя</label>
                <input class="pf-input" id="pf-name" value="${u.name}" placeholder="Ваше имя"/>
              </div>
              <div class="pf-group">
                <label class="pf-label">Телефон <span style="color:var(--text3);font-weight:400">(изменить нельзя)</span></label>
                <input class="pf-input" value="${u.phone||'—'}" disabled/>
              </div>
              <div class="pf-group">
                <label class="pf-label">Email</label>
                <input class="pf-input" id="pf-email" type="email" placeholder="your@email.com" value="${u.email||''}" autocomplete="email"/>
              </div>
              <div class="pf-group">
                <label class="pf-label">Автомобиль</label>
                <input class="pf-input" id="pf-car" value="${u.car||''}" placeholder="Toyota Camry 2018"/>
              </div>
              ${r.id === 'master' || r.id === 'admin' || r.id === 'owner' ? `<div class="pf-group">
                <label class="pf-label">Специализация</label>
                <input class="pf-input" id="pf-spec" value="${u.spec||''}" placeholder="Генераторы, стартеры..."/>
              </div>` : ''}
              ${r.id !== 'client' ? `<div class="pf-group">
                <label class="pf-label">Роль</label>
                <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--surface2);border-radius:var(--ui-radius-sm,5px);border:1px solid var(--line)">
                  <span class="rbadge ${r.id}">${r.emoji} ${r.label}</span>
                  <span class="t-sub">Уровень доступа ${r.level}/4</span>
                </div>
              </div>` : ''}
              <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">
                <button class="btn btn-primary pf-save" id="saveProfileBtn">Сохранить</button>
                <div class="pf-toast" id="profileToast">✅ Данные сохранены</div>
              </div>
            </div>
          </div>
          </div>
        </div>
      </div>
    </div>

    <!-- ══ HISTORY ══ -->
    <div class="cab-pane cabinet-reference-pane cabinet-level-pane" id="cp-history">
      <section class="cabinet-level">
        <div class="cabinet-ref-phone cabinet-level-phone">
          <header class="cabinet-ref-head"><img src="/assets/onboarding/kareta_logo_full.png" alt="KARETA.KZ" loading="eager"><button class="cabinet-ref-bell" type="button" onclick="window.Notifs?.toggle?.()">${serviceMiniIconSvg('bell')}<i>${Math.max(1, S.unread||2)}</i></button></header>
          <div class="cabinet-level-title-row"><button type="button" onclick="return kcabGo('cabinet')" aria-label="Назад">‹</button><div><h1>История обслуживания</h1><p>${isAdmin?'Все заказы системы':isMaster?'Назначенные работы':'Ваши сервисные записи'}</p></div><button type="button" class="is-action" onclick="App.startServiceBooking()">+</button></div>
          <div class="cabinet-level-summary">
            <div><span class="is-orange">${hist.length}</span><b>Всего</b></div>
            <div><span class="is-green">${hist.filter(h=>h.status==='done').length}</span><b>Выполнено</b></div>
            <div><span class="is-blue">${hist.filter(h=>h.status==='process').length}</span><b>В работе</b></div>
          </div>
          <div class="cabinet-level-chips"><span class="active">Все</span><span>Запланировано</span><span>В работе</span><span>Выполнено</span></div>
          <div class="cabinet-level-list">
            ${hist.length ? hist.slice(0,12).map(h=>`
            <button type="button" class="cabinet-history-card" onclick="openClientOrderModal('${escHtml(String(h.id||''))}')">
              <span class="cabinet-history-icon ${escHtml(String(h.status||'new'))}">${h.status==='done'?'✓':h.status==='process'?'⌁':h.status==='cancelled'||h.status==='cancel'?'×':'□'}</span>
              <span class="cabinet-history-body"><strong>${escHtml(h.title||'Заявка')}</strong><em>${escHtml(h.meta||'Дата не указана')}${isAdmin?` · Мастер: ${escHtml(h.master||'—')}`:''}</em><small>${escHtml(smap[h.status]||'Новая')}</small></span>
              <span class="cabinet-history-side"><b>${escHtml(h.price||'0 ₸')}</b>${h.status==='done'?'<i>Повторить</i>':h.status==='process'?'<i>Чат</i>':'<i>Открыть</i>'}</span>
            </button>`).join('') : `<div class="cabinet-level-empty"><span>▤</span><b>История пока пуста</b><p>Создайте первую запись, и она появится в сервисной книжке.</p><button type="button" onclick="App.startServiceBooking()">Записаться</button></div>`}
          </div>
        </div>
      </section>
    </div>

    <!-- ══ NOTIFICATIONS ══ -->
    <div class="cab-pane cabinet-reference-pane cabinet-level-pane" id="cp-notifs">
      <section class="cabinet-level">
        <div class="cabinet-ref-phone cabinet-level-phone">
          <header class="cabinet-ref-head"><img src="/assets/onboarding/kareta_logo_full.png" alt="KARETA.KZ" loading="eager"><button class="cabinet-ref-bell" type="button" onclick="window.Notifs?.toggle?.()">${serviceMiniIconSvg('bell')}<i>${Math.max(1, S.unread||2)}</i></button></header>
          <div class="cabinet-level-title-row"><button type="button" onclick="return kcabGo('cabinet')" aria-label="Назад">‹</button><div><h1>Напоминания</h1><p>Уведомления, записи и обслуживание</p></div>${S.unread>0?`<button type="button" class="is-text" onclick="markAllNotifsRead(this)">Прочитать</button>`:`<button type="button" class="is-text" onclick="App.go('services')">Записаться</button>`}</div>
          <div class="cabinet-reminder-hero">
            <span>${serviceMiniIconSvg('bell')}</span>
            <div><strong>${S.unread>0 ? `${S.unread} новых уведомлений` : 'Все спокойно'}</strong><p>${S.unread>0 ? 'Проверьте новые сообщения и статусы заявок.' : 'Когда появится запись, сообщение или напоминание по ТО — оно будет здесь.'}</p></div>
          </div>
          <div class="cabinet-level-list" id="cab-notif-list">
            ${notifs.length ? notifs.slice(0,20).map((n,i)=>`
            <button type="button" class="cabinet-notif-card ${n.unread?'unread':''}" id="cab-notif-${escHtml(String(n.id||i))}" onclick="markNotifRead('${escHtml(String(n.id||i))}', '${escHtml(String(n.actionUrl||''))}')">
              <span class="cabinet-notif-dot"></span>
              <span class="cabinet-notif-icon ${escHtml(n.type||'info')}">${escHtml(n.ico||'○')}</span>
              <span class="cabinet-notif-body"><strong>${escHtml(n.title||'Уведомление')}</strong><em>${escHtml(n.text||'')}</em><small>${escHtml(n.time||'')}</small></span>
            </button>`).join('') : `<div class="cabinet-level-empty"><span>${serviceMiniIconSvg('bell')}</span><b>Напоминаний нет</b><p>Добавьте автомобиль или создайте заявку — система покажет сроки ТО и новые статусы.</p><button type="button" onclick="return kcabGo('cabinet:car')">Открыть гараж</button></div>`}
          </div>
        </div>
      </section>
    </div>

    <!-- ══ LOYALTY ══ -->
    ${isClient?`<div class="cab-pane cabinet-reference-pane cabinet-level-pane" id="cp-loyalty">
      <section class="cabinet-level">
        <div class="cabinet-ref-phone cabinet-level-phone">
          <header class="cabinet-ref-head"><img src="/assets/onboarding/kareta_logo_full.png" alt="KARETA.KZ" loading="eager"><button class="cabinet-ref-bell" type="button" onclick="window.Notifs?.toggle?.()">${serviceMiniIconSvg('bell')}<i>${Math.max(1, S.unread||2)}</i></button></header>
          <div class="cabinet-level-title-row"><button type="button" onclick="return kcabGo('cabinet')" aria-label="Назад">‹</button><div><h1>Расходы и бонусы</h1><p>Баллы, скидка и история оплат</p></div><button type="button" class="is-action" onclick="App.go('services')">+</button></div>
          <div class="cabinet-wallet-card">
            <div class="cabinet-wallet-top"><span style="color:${curLevel.color};border-color:${curLevel.color}55;background:${curLevel.color}14">${curLevel.e} ${curLevel.n}</span><b>${curLevel.disc}</b></div>
            <strong>${loyaltyPts.toLocaleString('ru')}</strong><p>доступно баллов · 1 балл = 1 ₸</p>
            <div class="cabinet-wallet-bar"><i style="width:${lvlPct}%;background:linear-gradient(90deg,${curLevel.color},${curLevel.color}cc)"></i></div>
            <small>${nextLevel ? `До ${nextLevel.n}: ещё ${(nextLevel.min - loyaltyEarned).toLocaleString('ru')} баллов` : 'Максимальный уровень клиента'}</small>
          </div>
          <div class="cabinet-expense-grid">
            <div><span>+${loyaltyEarned.toLocaleString('ru')}</span><b>Заработано</b></div>
            <div><span>${Number(totalSpent||0).toLocaleString('ru')} ₸</span><b>Потрачено</b></div>
            <div><span>−${loyaltySpent.toLocaleString('ru')}</span><b>Списано</b></div>
          </div>
          <div class="cabinet-level-section-head"><b>Уровни клиента</b><button type="button" onclick="App.go('services')">Заработать ещё</button></div>
          <div class="cabinet-level-list cabinet-levels">
            ${loyaltyLevels.map(l=>{ const isCur = curLevel.n === l.n; const isDone = loyaltyEarned >= l.min; const isNext = nextLevel && nextLevel.n === l.n; return `<div class="cabinet-loyalty-level ${isCur?'current':''} ${isDone&&!isCur?'done':''}"><span>${l.e}</span><div><strong>${l.n}${isCur?' · вы здесь':''}</strong><em>${l.min.toLocaleString('ru')}${l.max<9999?'–'+l.max.toLocaleString('ru'):'+'} баллов</em><small style="color:${isDone?l.color:'var(--text-muted)'}">${l.disc} скидка</small></div><b>${isDone?'✓':(isNext?'→':'')}</b></div>`; }).join('')}
          </div>
          <div class="cabinet-level-section-head"><b>История баллов</b>${loyaltyPts>=100?`<button type="button" onclick="showLoyaltyRedeem(${loyaltyPts})">Потратить</button>`:''}</div>
          <div class="cabinet-level-list">
            ${loyaltyTxns.length ? loyaltyTxns.slice(0,20).map(t=>`<div class="cabinet-txn"><span class="${t.type==='spend'?'spend':'earn'}">${t.type==='spend'?'−':'+'}${Number(t.pts||0).toLocaleString('ru')}</span><div><strong>${escHtml(t.label||'Операция')}</strong><em>${escHtml(t.date||'')}</em></div></div>`).join('') : `<div class="cabinet-level-empty"><span>₸</span><b>Истории баллов пока нет</b><p>После выполненного ремонта здесь появится начисление бонусов.</p><button type="button" onclick="App.go('services')">Записаться</button></div>`}
          </div>
        </div>
      </section>
    </div>`:''}

    <!-- ══ APP SETTINGS ══ -->
    <div class="cab-pane cabinet-reference-pane" id="cp-appsettings">
      <div class="container" style="max-width:640px">
        <!-- Заполняется через renderCabSettingsTab() при открытии вкладки -->
      </div>
    </div>

    <!-- ══ CAR ══ -->
    ${isClient?`<div class="cab-pane cabinet-reference-pane cabinet-garage-pane" id="cp-car">
      <div class="cabinet-garage">
        <div class="cabinet-garage-phone">
          <header class="cabinet-ref-head"><img src="/assets/onboarding/kareta_logo_full.png" alt="KARETA.KZ" loading="eager"><button class="cabinet-ref-bell" type="button" onclick="window.Notifs?.toggle?.()">${serviceMiniIconSvg('bell')}<i>2</i></button></header>
          <div class="cabinet-garage-title-row"><div><h1>Мой гараж</h1><p>Ваши автомобили</p></div><button type="button" onclick="event.stopPropagation();window.openVehicleAddModal&&window.openVehicleAddModal();return false;">+</button></div>
          <div class="cabinet-garage-list">
            ${clientVehiclesStable.length ? clientVehiclesStable.slice(0,5).map((v,i)=>cabinetRefVehicleCard(v,i,false)).join('') : `<div class="car-empty card"><div class="car-empty-ico">🚘</div><div class="car-empty-t">Пока нет автомобилей</div><div class="car-empty-d">Нажмите «+», чтобы создать первую карточку.</div></div>`}
          </div>
          <button type="button" class="cabinet-garage-add" onclick="window.openVehicleAddModal&&window.openVehicleAddModal();return false;"><span>+</span> Добавить автомобиль</button>
          <p class="cabinet-garage-limit">Вы можете добавить до 5 автомобилей</p>
        </div>
      </div>
    </div>`:''}

    <!-- ══ ONLINE DIAGNOSTICS ══ -->
    ${isClient?`<div class="cab-pane cabinet-reference-pane" id="cp-diagnostics">
      <div class="container">
        <div class="diag-account-hero card">
          <div class="diag-account-ico">⌕</div>
          <div class="diag-account-body">
            <h3>Онлайн диагностика автомобиля</h3>
            <p>Раздел для проверки автомобиля, чтения ошибок, будущего подключения OBD/ELM327 и отправки результата мастеру или администратору.</p>
          </div>
        </div>
        <div class="diag-account-grid">
          <button class="card diag-account-card" type="button" onclick="window._openHomeCatalog&&window._openHomeCatalog('diagnostics')">
            <span class="diag-account-card-ico">▣</span>
            <b>Компьютерная диагностика</b>
            <small>Ошибки, датчики, ECU</small>
          </button>
          <button class="card diag-account-card" type="button" onclick="window._openHomeCatalog&&window._openHomeCatalog('battery')">
            <span class="diag-account-card-ico">▱</span>
            <b>Проверка АКБ</b>
            <small>Напряжение и запуск</small>
          </button>
          <button class="card diag-account-card" type="button" onclick="window._openHomeCatalog&&window._openHomeCatalog('electric')">
            <span class="diag-account-card-ico">⌁</span>
            <b>Электрика</b>
            <small>Проводка и питание</small>
          </button>
          <button class="card diag-account-card" type="button" onclick="Messenger.openAdminChat&&Messenger.openAdminChat()">
            <span class="diag-account-card-ico">◌</span>
            <b>Передать администратору</b>
            <small>Чат и консультация</small>
          </button>
        </div>
      </div>
    </div>`:''}

    </div>`;
  }

  window.repeatExistingOrder = function(id){
    const o = window.DB?.Orders?.get?.(id);
    if(!o) return false;
    if(String(o.type||'service_order') === 'parts_request') return window.openPartOrderFromOrder ? window.openPartOrderFromOrder(id) : false;
    if(!window.App?.startServiceBooking) return false;
    App.startServiceBooking({
      clientVehicleId: o.clientVehicleId || '',
      clientCar: o.clientCar || '',
      vehicleTitle: o.vehicleTitle || '',
      serviceIds: Array.isArray(o.serviceIds) ? o.serviceIds.slice() : [],
      notes: o.notes || ''
    });
    return true;
  };

  /* notify helpers */
  window.markNotifRead = async function(id, actionUrl=''){
    if (!id) return;
    const safeId = String(id||'');
    const selector = safeId ? `[id="cab-notif-${safeId.replace(/"/g,'')}"]` : '';
    const el = selector ? document.querySelector(selector) : null;
    if(el){ el.classList.remove('unread'); el.querySelector('.notif-dot')?.remove(); }
    try{ await window.DB?.Notifications?.markRead?.(safeId); }catch(_e){}
    S.unread = window.DB?.Notifications?.unreadMineCount?.() || Math.max(0, S.unread-1);
    updateBadge();
    if(actionUrl && window.App?.go){ App.go(String(actionUrl).replace(/^#/,'')); }
  };
  window.markAllNotifsRead = async function(btn){
    document.querySelectorAll('#cab-notif-list .notif-item.unread').forEach(el=>{
      el.classList.remove('unread');
      el.querySelector('.notif-dot')?.remove();
    });
    try{ await window.DB?.Notifications?.markAllRead?.(); }catch(_e){}
    S.unread = window.DB?.Notifications?.unreadMineCount?.() || 0; updateBadge();
    if(btn){ btn.textContent='✓ Прочитано'; btn.disabled=true; }
  };
  const VEHICLE_EDITOR_STEPS = 2;
  function vehicleDraftFromEditor(id=''){ const st = window.__vehicleEditorState || {}; return { id:id || st.id || '', icon:st.icon || '▱', title:st.title || '', brand:st.brand || '', model:st.model || '', year:st.year || '', generation:st.generation || '', bodyType:st.bodyType || '', plate:st.plate || '', vin:st.vin || '', color:st.color || '', photoUrl:st.photoUrl || '', note:st.note || '', mileageKm:Number(st.mileageKm||0)||0, engineType:st.engineType || '', engineVolume:st.engineVolume || '', fuelType:st.fuelType || '', transmission:st.transmission || '', driveType:st.driveType || '', ownerName:st.ownerName || '', city:st.city || '', purchaseAt:st.purchaseAt || '', insuranceUntil:st.insuranceUntil || '', inspectionUntil:st.inspectionUntil || '', tires:st.tires || '', battery:st.battery || '', oilType:st.oilType || '', knownIssues:st.knownIssues || '', serviceAt:st.serviceAt || '', serviceNote:st.serviceNote || '', isDefault: !!st.isDefault }; }
  function syncVehicleEditorState(id=''){ const st = window.__vehicleEditorState || vehicleDraftFromEditor(id); const read=(el)=>document.getElementById(el)?.value?.trim() || ''; const readBool=(el)=>!!document.getElementById(el)?.checked; if(document.getElementById('veh-brand')) st.brand = read('veh-brand'); if(document.getElementById('veh-plate')) st.plate = read('veh-plate'); if(document.getElementById('veh-vin')) st.vin = read('veh-vin').toUpperCase(); if(document.getElementById('veh-icon')) st.icon = read('veh-icon') || '▱'; if(document.getElementById('veh-title')) st.title = read('veh-title'); if(document.getElementById('veh-model')) st.model = read('veh-model'); if(document.getElementById('veh-year')) st.year = read('veh-year'); if(document.getElementById('veh-generation')) st.generation = read('veh-generation'); if(document.getElementById('veh-body-type')) st.bodyType = read('veh-body-type'); if(document.getElementById('veh-color')) st.color = read('veh-color'); if(document.getElementById('veh-photo-url')) st.photoUrl = read('veh-photo-url'); if(document.getElementById('veh-note')) st.note = read('veh-note'); if(document.getElementById('veh-mileage')) st.mileageKm = Number(document.getElementById('veh-mileage')?.value||0)||0; if(document.getElementById('veh-engine-type')) st.engineType = read('veh-engine-type'); if(document.getElementById('veh-engine-volume')) st.engineVolume = read('veh-engine-volume'); if(document.getElementById('veh-fuel-type')) st.fuelType = read('veh-fuel-type'); if(document.getElementById('veh-transmission')) st.transmission = read('veh-transmission'); if(document.getElementById('veh-drive-type')) st.driveType = read('veh-drive-type'); if(document.getElementById('veh-owner-name')) st.ownerName = read('veh-owner-name'); if(document.getElementById('veh-city')) st.city = read('veh-city'); if(document.getElementById('veh-purchase-at')) st.purchaseAt = read('veh-purchase-at'); if(document.getElementById('veh-insurance-until')) st.insuranceUntil = read('veh-insurance-until'); if(document.getElementById('veh-inspection-until')) st.inspectionUntil = read('veh-inspection-until'); if(document.getElementById('veh-tires')) st.tires = read('veh-tires'); if(document.getElementById('veh-battery')) st.battery = read('veh-battery'); if(document.getElementById('veh-oil-type')) st.oilType = read('veh-oil-type'); if(document.getElementById('veh-known-issues')) st.knownIssues = read('veh-known-issues'); if(document.getElementById('veh-service-at')) st.serviceAt = read('veh-service-at'); if(document.getElementById('veh-service-note')) st.serviceNote = read('veh-service-note'); if(document.getElementById('veh-default')) st.isDefault = readBool('veh-default'); if(!st.title){ st.title = [st.brand, st.model].filter(Boolean).join(' ').trim() || [st.brand, st.plate].filter(Boolean).join(' · ').trim(); } window.__vehicleEditorState = st; return st; }
  function vehicleStepOneValid(st){ return !!(String(st.title||'').trim() && String(st.plate||'').trim() && String(st.vin||'').trim()); }
  function vehicleStepOneHtml(st){ return `<div class="profile-form" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Название авто *</label><input class="pf-input" id="veh-title" value="${escHtml(st.title||'')}" placeholder="Toyota Camry 70"></div><div class="pf-group"><label class="pf-label">Госномер *</label><input class="pf-input" id="veh-plate" value="${escHtml(st.plate||'')}" placeholder="777 AAA 16"></div><div class="pf-group"><label class="pf-label">VIN *</label><input class="pf-input" id="veh-vin" value="${escHtml(st.vin||'')}" placeholder="JTNBF3HK..." oninput="this.value=this.value.toUpperCase()"></div><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Фото/ссылка</label><input class="pf-input" id="veh-photo-url" value="${escHtml(st.photoUrl||'')}" placeholder="data:image/... или ссылка"></div><div class="pf-group" style="grid-column:1/-1"><div class="profile-hint">Сначала создаётся карточка автомобиля. Подробные данные можно заполнить на следующем шаге.</div></div><div style="display:flex;gap:10px;flex-wrap:wrap;grid-column:1/-1"><button class="btn btn-primary" onclick="goVehicleEditorStep(2,'${escHtml(st.id||'')}')">Далее</button><button class="btn btn-outline" onclick="document.getElementById('vehicle-editor-wrap').innerHTML=''">Закрыть</button></div></div>`; }
  function vehicleStepTwoHtml(st){ return `<div class="vehicle-editor-sections"><div class="vehicle-editor-section"><div class="vehicle-editor-section-title">Основное</div><div class="profile-form" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="pf-group"><label class="pf-label">Иконка</label><input class="pf-input" id="veh-icon" value="${escHtml(st.icon||'▱')}" placeholder="▱" maxlength="4"></div><div class="pf-group"><label class="pf-label">Название карточки</label><input class="pf-input" id="veh-title" value="${escHtml(st.title||'')}" placeholder="${escHtml(([st.brand, st.model].filter(Boolean).join(' ').trim() || [st.brand, st.plate].filter(Boolean).join(' · ')).trim())}"></div><div class="pf-group"><label class="pf-label">Марка</label><input class="pf-input" id="veh-brand" value="${escHtml(st.brand||'')}" placeholder="Toyota"></div><div class="pf-group"><label class="pf-label">Модель</label><input class="pf-input" id="veh-model" value="${escHtml(st.model||'')}" placeholder="Camry"></div><div class="pf-group"><label class="pf-label">Год</label><input class="pf-input" id="veh-year" value="${escHtml(st.year||'')}" placeholder="2018"></div><div class="pf-group"><label class="pf-label">Поколение / кузов</label><input class="pf-input" id="veh-generation" value="${escHtml(st.generation||'')}" placeholder="XV70"></div><div class="pf-group"><label class="pf-label">Тип кузова</label><input class="pf-input" id="veh-body-type" value="${escHtml(st.bodyType||'')}" placeholder="Седан"></div><div class="pf-group"><label class="pf-label">Цвет</label><input class="pf-input" id="veh-color" value="${escHtml(st.color||'')}" placeholder="Белый"></div><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Фото/ссылка</label><input class="pf-input" id="veh-photo-url" value="${escHtml(st.photoUrl||'')}" placeholder="https://... или data:image/... "></div></div></div><div class="vehicle-editor-section"><div class="vehicle-editor-section-title">Технические данные</div><div class="profile-form" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="pf-group"><label class="pf-label">Госномер *</label><input class="pf-input" id="veh-plate" value="${escHtml(st.plate||'')}" placeholder="777 AAA 16"></div><div class="pf-group"><label class="pf-label">VIN *</label><input class="pf-input" id="veh-vin" value="${escHtml(st.vin||'')}" placeholder="VIN" oninput="this.value=this.value.toUpperCase()"></div><div class="pf-group"><label class="pf-label">Пробег, км</label><input class="pf-input" id="veh-mileage" value="${escHtml(String(st.mileageKm||''))}" placeholder="125000"></div><div class="pf-group"><label class="pf-label">Объём двигателя</label><input class="pf-input" id="veh-engine-volume" value="${escHtml(st.engineVolume||'')}" placeholder="2.5"></div><div class="pf-group"><label class="pf-label">Тип двигателя</label><input class="pf-input" id="veh-engine-type" value="${escHtml(st.engineType||'')}" placeholder="Бензин"></div><div class="pf-group"><label class="pf-label">Топливо</label><input class="pf-input" id="veh-fuel-type" value="${escHtml(st.fuelType||'')}" placeholder="АИ-95"></div><div class="pf-group"><label class="pf-label">КПП</label><input class="pf-input" id="veh-transmission" value="${escHtml(st.transmission||'')}" placeholder="АКПП"></div><div class="pf-group"><label class="pf-label">Привод</label><input class="pf-input" id="veh-drive-type" value="${escHtml(st.driveType||'')}" placeholder="Передний"></div></div></div><div class="vehicle-editor-section"><div class="vehicle-editor-section-title">Владение и документы</div><div class="profile-form" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="pf-group"><label class="pf-label">Владелец</label><input class="pf-input" id="veh-owner-name" value="${escHtml(st.ownerName||'')}" placeholder="ФИО владельца"></div><div class="pf-group"><label class="pf-label">Город эксплуатации</label><input class="pf-input" id="veh-city" value="${escHtml(st.city||'')}" placeholder="Усть-Каменогорск"></div><div class="pf-group"><label class="pf-label">Дата покупки</label><input class="pf-input" id="veh-purchase-at" type="date" value="${escHtml(String(st.purchaseAt||'').slice(0,10))}"></div><div class="pf-group"><label class="pf-label">Страховка до</label><input class="pf-input" id="veh-insurance-until" type="date" value="${escHtml(String(st.insuranceUntil||'').slice(0,10))}"></div><div class="pf-group"><label class="pf-label">Техосмотр до</label><input class="pf-input" id="veh-inspection-until" type="date" value="${escHtml(String(st.inspectionUntil||'').slice(0,10))}"></div></div></div><div class="vehicle-editor-section"><div class="vehicle-editor-section-title">Обслуживание и заметки</div><div class="profile-form" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="pf-group"><label class="pf-label">Последнее ТО</label><input class="pf-input" id="veh-service-at" type="date" value="${escHtml(String(st.serviceAt||'').slice(0,10))}"></div><div class="pf-group"><label class="pf-label">Масло / расходники</label><input class="pf-input" id="veh-oil-type" value="${escHtml(st.oilType||'')}" placeholder="5W-30"></div><div class="pf-group"><label class="pf-label">Шины</label><input class="pf-input" id="veh-tires" value="${escHtml(st.tires||'')}" placeholder="215/55 R17"></div><div class="pf-group"><label class="pf-label">Аккумулятор</label><input class="pf-input" id="veh-battery" value="${escHtml(st.battery||'')}" placeholder="75Ah"></div><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Известные проблемы</label><textarea class="pf-input" id="veh-known-issues" rows="3" placeholder="Что беспокоит по машине">${escHtml(st.knownIssues||'')}</textarea></div><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Заметка по обслуживанию</label><textarea class="pf-input" id="veh-service-note" rows="3" placeholder="Замена масла и фильтров">${escHtml(st.serviceNote||'')}</textarea></div><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Комментарий</label><textarea class="pf-input" id="veh-note" rows="3" placeholder="Например: обслуживается по выходным">${escHtml(st.note||'')}</textarea></div></div></div><label style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text2)"><input type="checkbox" id="veh-default" ${st.isDefault?'checked':''}/> Сделать основным автомобилем</label><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px"><button class="btn btn-outline" onclick="goVehicleEditorStep(1,'${escHtml(st.id||'')}')">Назад</button><button class="btn btn-primary" onclick="saveVehicleData('${escHtml(st.id||'')}', this)">Сохранить автомобиль</button><div class="pf-toast" id="vehToast">✅ Автомобиль сохранён</div></div></div>`; }
  window.renderVehicleEditor = function(id=''){ const host=document.getElementById('vehicle-editor-wrap'); if(!host) return; const v=id ? (window.DB?.Vehicles?.get?.(id) || null) : null; const step = Math.max(1, Math.min(VEHICLE_EDITOR_STEPS, Number(window.__vehicleEditorStep||1)||1)); if(!window.__vehicleEditorState || String(window.__vehicleEditorState.id||'') !== String(v?.id||id||'')){ window.__vehicleEditorState = { id:v?.id||id||'', icon:v?.icon||'▱', title:v?.title||'', brand:v?.brand||'', model:v?.model||'', year:v?.year||'', generation:v?.generation||'', bodyType:v?.bodyType||'', plate:v?.plate||'', vin:v?.vin||'', color:v?.color||'', photoUrl:v?.photoUrl||'', note:v?.note||'', mileageKm:Number(v?.mileageKm||0)||0, engineType:v?.engineType||'', engineVolume:v?.engineVolume||'', fuelType:v?.fuelType||'', transmission:v?.transmission||'', driveType:v?.driveType||'', ownerName:v?.ownerName||'', city:v?.city||'', purchaseAt:v?.purchaseAt||'', insuranceUntil:v?.insuranceUntil||'', inspectionUntil:v?.inspectionUntil||'', tires:v?.tires||'', battery:v?.battery||'', oilType:v?.oilType||'', knownIssues:v?.knownIssues||'', serviceAt:v?.serviceAt||'', serviceNote:v?.serviceNote||'', isDefault: !!(v?.isDefault || !v) }; }
    const st = window.__vehicleEditorState; const progress = `<div class="vehicle-editor-steps"><div class="step ${step===1?'active':''}"><span>1</span><b>Обязательные поля</b><small>Название · Госномер · VIN</small></div><div class="step ${step===2?'active':''}"><span>2</span><b>Карточка автомобиля</b><small>Остальные данные и настройки</small></div></div>`; host.innerHTML = `<div class="vehicle-editor card"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px"><div style="font-weight:700;font-size:15px">${v?'Редактирование автомобиля':'Новый автомобиль'}</div><button class="btn btn-outline" style="font-size:12px;padding:6px 12px" onclick="document.getElementById('vehicle-editor-wrap').innerHTML='';window.__vehicleEditorState=null;window.__vehicleEditorStep=1;">Закрыть</button></div>${progress}${step===1 ? vehicleStepOneHtml(st) : vehicleStepTwoHtml(st)}</div>`; };
  window.goVehicleEditorStep = function(step,id=''){ const st = syncVehicleEditorState(id); if(Number(step)===2 && !vehicleStepOneValid(st)){ showToast('Сначала заполните название, госномер и VIN','error'); return; } window.__vehicleEditorStep = Number(step)||1; renderVehicleEditor(id||st.id||''); };
  window.editVehicle = function(id){
    if (!id) return;
    if (id && location.hash.startsWith('#cabinet')) { try{ history.pushState(null,'','#cabinet:car:edit:'+id); }catch(_e){} }
    window.__vehicleEditorStep = 1; window.__vehicleEditorState = null;

    // Открываем редактор в модалке если нет vehicle-editor-wrap
    let host = document.getElementById('vehicle-editor-wrap');
    if (!host) {
      let edEl = document.getElementById('vehicle-edit-modal');
      if (!edEl) {
        edEl = document.createElement('div');
        edEl.id = 'vehicle-edit-modal';
        edEl.className = 'cmodal-overlay';
        edEl.addEventListener('click', e => {
          if (e.target === edEl) {
            if (window.__closeLayeredModal) window.__closeLayeredModal('vehicle-edit-modal','vehicle-edit-modal');
            else edEl.classList.remove('open');
            if (location.hash.startsWith('#cabinet:car:edit:')) { try{ history.pushState(null,'','#cabinet:car'); }catch(_e){} }
          }
        });
        document.body.appendChild(edEl);
      }
      const wrap = document.createElement('div');
      wrap.id = 'vehicle-editor-wrap';
      wrap.style.cssText = 'width:min(96vw,560px);max-height:90vh;overflow-y:auto;background:var(--bg);border-radius:var(--ui-radius-md,10px);';
      edEl.innerHTML = '';
      edEl.appendChild(wrap);
      edEl.classList.add('open');
      try{ window.App?.LayerManager?.open('vehicle-edit-modal'); }catch(_e){}
      host = wrap;
    }

    renderVehicleEditor(id||'');
  };
  window.saveVehicleData = async function(id, btn) {
    const payload = syncVehicleEditorState(id);
    payload.icon = payload.icon || '▱';
    payload.vin  = String(payload.vin||'').toUpperCase().trim();
    if (!payload.title || !payload.plate || !payload.vin) {
      showToast('Нужны название, госномер и VIN','error');
      window.__vehicleEditorStep = 1;
      renderVehicleEditor(payload.id||'');
      return;
    }
    if (!payload.brand) payload.brand = String(payload.title||'').split(/\s+/)[0] || '';
    if (!payload.title) {
      payload.title = [payload.brand, payload.model, payload.year].filter(Boolean).join(' ').trim()
        || [payload.brand, payload.plate].filter(Boolean).join(' · ').trim()
        || payload.brand;
    }
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Сохраняем...'; }
    const _isKcabVehicleRoute = String(location.hash || '').startsWith('#cabinet:car:new') || String(location.hash || '').startsWith('#cabinet:car:edit:');
    try {
      const saved = await window.DB.Vehicles.upsert(payload);
      if (saved?.isDefault && window.App?.mergeUserPatch) window.App.mergeUserPatch({ car: saved.title||'' });
      showToast('✅ Автомобиль сохранён');
      const t = document.getElementById('vehToast');
      if (t) { t.classList.add('show'); setTimeout(()=>t.classList.remove('show'), 2200); }
      window.__vehicleEditorState = null;
      window.__vehicleEditorStep  = 1;
      // Закрываем edit-modal если открыт
      const editModal = document.getElementById('vehicle-edit-modal');
      if (editModal) {
        window.__closeLayeredModal?.('vehicle-edit-modal','vehicle-edit-modal');
        if (location.hash.startsWith('#cabinet:car:edit:')) { try{ history.pushState(null,'','#cabinet:car'); }catch(_e){} }
      }
      // Обновляем грид карточек если на странице кабинета
      const grid = document.getElementById('client-vehicles-grid');
      if (grid && typeof getClientVehicles === 'function') {
        const cars = getClientVehicles();
        grid.innerHTML = cars.length
          ? cars.map(v => vehicleCardHtml(v)).join('')
          : '<div class="car-empty card"><div class="car-empty-ico">🚘</div><div class="car-empty-t">Пока нет автомобилей</div></div>';
      }
      // Close vehicle modal if open, else nav to cabinet/garage tab
      const vehModal = document.getElementById('vehicle-add-modal');
      if (vehModal) {
        window.__closeLayeredModal?.('vehicle-add-modal','vehicle-add-modal');
        // Refresh booking vehicle selector if it exists
        if (typeof window._refreshBookingVehicleSelect === 'function') window._refreshBookingVehicleSelect();
      } else {
        setTimeout(() => {
          if (window.App?.go) App.go(_isKcabVehicleRoute ? 'cabinet:car' : 'cabinet');
        }, 300);
      }
    } catch(e) {
      showToast((e&&e.message)||'Не удалось сохранить автомобиль', 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Сохранить автомобиль'; }
    }
  };
  window.setDefaultVehicle = async function(id){ if(!id) return; try{ await window.DB.Vehicles.setDefault(id); if(window.App?.persistServerProfile){ const v=window.DB.Vehicles.get(id); if(v) window.App.persistServerProfile({car:v.title||''}); } showToast('Основной автомобиль обновлён'); if(window.App?.go) App.go(String(location.hash||'').startsWith('#cabinet:car') ? 'cabinet:car' : 'cabinet'); }catch(e){ showToast((e&&e.message)||'Не удалось обновить основной автомобиль','error'); } };
  window.deleteVehicle = async function(id){ if(!id) return; try{ await window.DB.Vehicles.remove(id); showToast('Автомобиль удалён'); if(window.App?.go) App.go(String(location.hash||'').startsWith('#cabinet:car') ? 'cabinet:car' : 'cabinet'); }catch(e){ showToast((e&&e.message)||'Не удалось удалить автомобиль','error'); } };
  window.saveCarData = function(btn){ window.editVehicle(''); };

  /* ─── Compact detail modal for vehicle cards ─── */
  window.openVehicleDetailModal = function(id) {
    window.openVehicleCard(id);
  };

  window.openVehicleCard = function(id){
    const v = id ? (window.DB?.Vehicles?.get?.(id) || null) : getPrimaryVehicle();
    if (!v) { window.showToast('Автомобиль не найден', 'error'); return; }

    // URL
    if (location.hash.startsWith('#cabinet')) {
      try { history.pushState(null,'','#cabinet:car:view:'+v.id); } catch(_e){}
    }

    const eh = escHtml;
    const fill = vehicleCompletionPercent(v);
    const fillCls = fill>=75?'good':(fill>=45?'mid':'low');
    const stats = vehicleStats(v);
    const photo = String(v.photoUrl||'').trim();
    const vf = (label, val) => val ? `<div class="vdm-field"><span class="vdm-field-lbl">${eh(label)}</span><b class="vdm-field-val">${eh(String(val))}</b></div>` : '';

    let el = document.getElementById('vehicle-detail-modal');
    if (!el) {
      el = document.createElement('div');
      el.id = 'vehicle-detail-modal';
      el.className = 'cmodal-overlay';
      el.addEventListener('click', e => {
        if (e.target === el) window.closeVehicleDetailModal();
      });
      document.body.appendChild(el);
    }

    el.innerHTML = `
    <div class="cmodal-box vdm-box">
      <div class="cmodal-head">
        <h3>${eh(v.title||[v.brand,v.model].filter(Boolean).join(' ')||'Автомобиль')}</h3>
        <button type="button" class="cmodal-close" onclick="window.closeVehicleDetailModal()">✕</button>
      </div>
      <div class="cmodal-body vdm-body">
        ${photo ? `<div class="vdm-photo-wrap"><img class="vdm-photo" src="${eh(photo)}" alt="${eh(v.title||'')}"></div>` : ''}

        <div class="vdm-hero">
          <div class="vdm-hero-ico">${eh(v.icon||'▱')}</div>
          <div class="vdm-hero-info">
            <div class="vdm-hero-title">${eh(v.title||[v.brand,v.model].filter(Boolean).join(' ')||'Автомобиль')}</div>
            <div class="vdm-hero-sub">${eh([v.brand,v.model,v.year,v.generation].filter(Boolean).join(' ')||'—')}</div>
            ${v.isDefault ? '<span class="vcard-def-badge">Основной</span>' : ''}
          </div>
        </div>

        <div class="vdm-fill-wrap">
          <div class="vdm-fill-bar ${fillCls}"><div style="width:${fill}%"></div></div>
          <span class="vdm-fill-lbl">Заполненность ${fill}%</span>
        </div>

        <div class="vdm-stats">
          <div class="vdm-stat"><b>${stats.total}</b><span>заявок</span></div>
          <div class="vdm-stat"><b>${stats.serviceCount}</b><span>ремонтов</span></div>
          <div class="vdm-stat"><b>${Number(stats.spent||0).toLocaleString('ru')}</b><span>₸</span></div>
        </div>

        <div class="vdm-section-title">Основное</div>
        <div class="vdm-fields">
          ${vf('Госномер', v.plate)}${vf('VIN', v.vin)}${vf('Марка', v.brand)}
          ${vf('Модель', v.model)}${vf('Год', v.year)}${vf('Цвет', v.color)}
          ${vf('Кузов', v.bodyType)}${vf('Поколение', v.generation)}
        </div>

        <div class="vdm-section-title">Технические данные</div>
        <div class="vdm-fields">
          ${vf('Пробег', Number(v.mileageKm||0)>0 ? Number(v.mileageKm||0).toLocaleString('ru')+' км' : '')}
          ${vf('Двигатель', v.engineType)}${vf('Объём', v.engineVolume)}
          ${vf('Топливо', v.fuelType)}${vf('КПП', v.transmission)}${vf('Привод', v.driveType)}
        </div>

        ${v.knownIssues||v.serviceNote||v.note ? `
        <div class="vdm-section-title">Заметки</div>
        <div class="vdm-fields">
          ${vf('Известные проблемы', v.knownIssues)}
          ${vf('Заметка ТО', v.serviceNote)}
          ${vf('Комментарий', v.note)}
        </div>` : ''}

        <div class="vdm-section-title">История по автомобилю</div>
        ${vehicleHistoryHtml(v, 5)}

        <div class="vdm-actions">
          <button class="btn btn-outline vdm-del" onclick="deleteVehicle('${eh(v.id)}')">🗑 Удалить</button>
          <button class="btn btn-outline" onclick="App.go('services')">□ Записать</button>
          <button class="btn btn-primary" onclick="window.closeVehicleDetailModal();editVehicle('${eh(v.id)}')">✎ Редактировать</button>
        </div>
      </div>
    </div>`;

    el.classList.add('open');
    try { window.App?.LayerManager?.open('vehicle-detail-modal'); } catch(_e) {}
  };

  window.closeVehicleDetailModal = function(){
    if (window.__closeLayeredModal) window.__closeLayeredModal('vehicle-detail-modal','vehicle-detail-modal');
    else document.getElementById('vehicle-detail-modal')?.classList.remove('open');
    if (location.hash.startsWith('#cabinet:car:view:') || location.hash.startsWith('#cabinet:car:edit:')) {
      try { history.pushState(null,'','#cabinet:car'); } catch(_e){}
    }
  };

  function _dateIsoShift(days=0){ const d=new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()+Number(days||0)); return d.toISOString().slice(0,10); }
  function _weekdayDefaultSchedule(workDate){
    try{
      const d=new Date(String(workDate||'')+'T00:00:00');
      const wd=d.getDay();
      if(wd>=1 && wd<=5) return { isDayOff:false, startTime:'09:00', endTime:'18:00', source:'default' };
    }catch(_e){}
    return { isDayOff:true, startTime:'09:00', endTime:'18:00', source:'default' };
  }
  function getMasterScheduleRowsWithDefaults(masterId, days=21){
    const saved=(window.DB?.MasterSchedules?.byMaster?.(masterId)||[]);
    const byDate=new Map(saved.map(r=>[String(r.workDate||''), r]));
    const rows=[];
    for(let i=0;i<days;i++){
      const workDate=_dateIsoShift(i);
      const savedRow=byDate.get(workDate);
      rows.push(savedRow ? Object.assign({source:'saved'}, savedRow) : Object.assign({masterId, workDate}, _weekdayDefaultSchedule(workDate)));
    }
    return rows;
  }
  async function applyMasterDefaultSchedule(masterId, days=21, btn=null){
    if(btn) btn.disabled=true;
    try{
      const rows=getMasterScheduleRowsWithDefaults(masterId, days).filter(r=>r.source!=='saved');
      for(const r of rows){
        await window.DB?.MasterSchedules?.save?.({
          masterId,
          workDate:r.workDate,
          startTime:r.startTime||'09:00',
          endTime:r.endTime||'18:00',
          isDayOff:!!r.isDayOff,
          note:r.isDayOff ? 'Автошаблон: выходной' : 'Автошаблон: Пн–Пт 09:00–18:00'
        });
      }
      showToast('Стандартный график применён','success');
      if(page==='master') navMaster('schedule');
    }catch(e){
      showToast('Не удалось применить график','error');
    }finally{ if(btn) btn.disabled=false; }
  }
  window.applyMasterDefaultSchedule = applyMasterDefaultSchedule;
  function renderMasterSchedulePage(masterId){
    const master=window.DB?.Masters?.get?.(masterId)||window.DB?.Masters?.getMine?.()||null;
    const rows=getMasterScheduleRowsWithDefaults(masterId, 21);
    const upcomingSaved=(window.DB?.MasterSchedules?.upcoming?.(masterId, 21)||[]);
    const workDays=rows.filter(r=>!r.isDayOff).length;
    const dayOffs=rows.filter(r=>r.isDayOff).length;
    const firstSaved=upcomingSaved[0]||null;
    const today = new Date().toISOString().slice(0,10);

    // Все заказы мастера — активные (new/process) + ближайшие выполненные
    const allMasterOrders = (window.DB?.Orders?.getAll?.({})||[]).filter(o=>
      window.DB?.Orders?.isAttachedToMaster?.(o,{id:masterId}) &&
      !['cancelled'].includes(String(o.status||''))
    );
    const ordersByDate = {};
    allMasterOrders.forEach(o=>{
      // Приоритет дат: o.date (дата записи) → claimedAt → createdAt → сегодня для process
      let d = String(o.date||o.dateLabel||'').slice(0,10);
      if (!d && o.status === 'process') d = today; // активный ремонт — ставим на сегодня
      if (!d) d = String(o.createdAt||'').slice(0,10);
      if (d) { if(!ordersByDate[d]) ordersByDate[d]=[]; ordersByDate[d].push(o); }
    });

    // Заказы без даты и не попавшие в график — только new без даты
    const scheduleDates = new Set(rows.map(r=>r.workDate));
    const unscheduledOrders = allMasterOrders.filter(o=>{
      if (o.status === 'process') return false; // process всегда на сегодня
      const d = String(o.date||o.dateLabel||'').slice(0,10);
      return (!d || !scheduleDates.has(d)) && ['new'].includes(String(o.status||''));
    });

    return `<div class="container">
      <div class="msched-hero">
        <div class="msched-hero-title">□ График мастера</div>
        <div class="msched-hero-sub">
          Настройте рабочие дни — клиенты видят когда вы свободны. Выходные дни закрыты для записи.
          ${!upcomingSaved.length ? '<div style="margin-top:8px;padding:8px 12px;background:rgba(255,107,0,.1);border-radius:var(--ui-radius-sm,5px);font-size:12px;color:var(--orange)">💡 У вас ещё нет настроенных рабочих дней. Нажмите «Заполнить по умолчанию» — мы настроим пн–пт с 9:00 до 18:00.</div>' : ''}
        </div>
        <div class="msched-stats">
          <div class="msched-stat">□ Рабочих: <b>${workDays}</b></div>
          <div class="msched-stat">😴 Выходных: <b>${dayOffs}</b></div>
          ${firstSaved?`<div class="msched-stat">⌁ Ближайшая: <b>${escHtml(firstSaved.workDate||'')}</b></div>`:''}
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
          <button class="btn btn-primary" style="font-size:12px;padding:8px 12px" onclick="applyMasterDefaultSchedule('${masterId}',21,this)">◇ Стандарт на 21 день</button>
          <button class="btn btn-outline" style="font-size:12px;padding:8px 12px" onclick="openMasterScheduleModal('${masterId}')">✎ Редактировать дни</button>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px">
        ${rows.map(r=>{
          const dayOrders = ordersByDate[r.workDate] || [];
          const ordCnt = dayOrders.length;
          const ordBadge = ordCnt ? `<span style="font-size:10px;background:rgba(255,107,0,.15);color:var(--orange);border:1px solid rgba(255,107,0,.3);border-radius:99px;padding:2px 7px;font-weight:700">${ordCnt} заказ${ordCnt===1?'':'а'}</span>` : '';
          const isToday = r.workDate === today;
          const hasProcOrNew = dayOrders.some(o=>['new','process'].includes(String(o.status||'')));
          const borderColor = r.isDayOff ? '#94a3b8' : ordCnt && hasProcOrNew ? 'var(--orange)' : ordCnt ? '#22c55e' : '#34d399';
          // Mini order chips inside day card
          const miniOrders = dayOrders.slice(0,3).map(o=>{
            const sc = {new:'#60a5fa',process:'var(--orange)',done:'#22c55e',cancelled:'#94a3b8'}[o.status]||'var(--text3)';
            const ico = {new:'🕐',process:'⌁',done:'✅',cancelled:'✖'}[o.status]||'▤';
            return `<div style="display:flex;align-items:center;gap:6px;padding:5px 8px;background:var(--surface);border-radius:var(--ui-radius-sm,5px);border:1px solid var(--line)">
              <span style="font-size:12px">${ico}</span>
              <div style="flex:1;min-width:0">
                <div style="font-size:11px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(o.clientName||'Клиент')}</div>
                <div style="font-size:10px;color:var(--text3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml((o.serviceNames||o.notes||'Заявка').slice(0,30))}</div>
              </div>
              <span style="font-size:9px;padding:1px 5px;border-radius:99px;background:${sc}22;color:${sc};border:1px solid ${sc}44;font-weight:700;flex-shrink:0">${o.time||''}</span>
            </div>`;
          }).join('');
          const moreCount = dayOrders.length > 3 ? dayOrders.length - 3 : 0;

          return `<div class="card" style="padding:14px 14px 12px;border:1px solid ${isToday?'rgba(255,107,0,.4)':'var(--line)'};border-left:3px solid ${borderColor};${isToday?'box-shadow:0 0 0 1px rgba(255,107,0,.15)':''}">
            <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px">
              <div>
                <div style="font-weight:700;display:flex;align-items:center;gap:6px">
                  ${isToday?'<span style="font-size:10px;background:var(--orange);color:#fff;padding:1px 7px;border-radius:99px;font-weight:700">Сегодня</span>':''}
                  ${escHtml(new Date(String(r.workDate||'')+'T00:00:00').toLocaleDateString('ru-RU',{weekday:'short',day:'2-digit',month:'short'}))}
                </div>
                <div style="font-size:11px;color:var(--text3);margin-top:2px">${r.isDayOff?'Выходной':escHtml(_scheduleLabel(r))}</div>
              </div>
              <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">
                ${ordCnt ? `<span style="font-size:10px;background:rgba(255,107,0,.12);color:var(--orange);border:1px solid rgba(255,107,0,.25);border-radius:99px;padding:2px 8px;font-weight:700">${ordCnt} заказ${ordCnt===1?'':'а'}</span>` : ''}
              </div>
            </div>
            ${!r.isDayOff && dayOrders.length ? `
            <div style="display:flex;flex-direction:column;gap:4px;margin-top:10px">
              ${miniOrders}
              ${moreCount ? `<div style="font-size:11px;color:var(--text3);text-align:center;padding:4px">+${moreCount} ещё</div>` : ''}
            </div>` : (!r.isDayOff ? `<div style="font-size:12px;color:var(--text3);margin-top:8px">${r.note||'Свободный день'}</div>` : '')}
            <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
              ${!r.isDayOff ? `<button class="btn ${ordCnt?'btn-primary':'btn-outline'}" style="font-size:12px;padding:7px 14px;flex:1" onclick="masterOpenDayOrders('${masterId}','${r.workDate}')">▤${ordCnt?' Заказы ('+ordCnt+')':' Нет заказов'}</button>` : `<div style="font-size:12px;color:var(--text3);padding:7px 0">Выходной день</div>`}
              <button class="btn btn-outline" style="font-size:12px;padding:7px 10px" title="Изменить день" onclick="openMasterScheduleModal('${masterId}');setTimeout(()=>{const d=document.getElementById('msched-date');if(d)d.value='${r.workDate}';},30)">✎</button>
            </div>
          </div>`;
        }).join('')}
      </div>

      ${unscheduledOrders.length ? `
      <div style="margin-top:20px;padding:16px 20px;background:rgba(96,165,250,.07);border:1px solid rgba(96,165,250,.2);border-radius:var(--ui-radius-md,10px)">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px">
          <div>
            <div style="font-family:'Oswald',sans-serif;font-size:16px;font-weight:700;color:#60a5fa">📌 Без конкретного дня в графике</div>
            <div style="font-size:12px;color:var(--text3);margin-top:3px">Эти заказы назначены вам, но их дата не совпадает ни с одним днём в графике</div>
          </div>
          <span style="font-size:11px;padding:3px 10px;border-radius:99px;background:rgba(96,165,250,.15);color:#60a5fa;font-weight:700">${unscheduledOrders.length}</span>
        </div>
        <div class="flex-col-8">
          ${unscheduledOrders.slice(0,5).map(o=>{
            const sc = {new:'#60a5fa',process:'var(--orange)',done:'#22c55e'}[o.status]||'var(--text3)';
            const ico = {new:'🕐',process:'⌁',done:'✅'}[o.status]||'▤';
            return `<div style="display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--bg);border-radius:var(--ui-radius-md,10px);border:1px solid var(--line)">
              <span style="font-size:18px">${ico}</span>
              <div style="flex:1;min-width:0">
                <div style="font-weight:700;font-size:13px">${escHtml(o.clientName||'Клиент')} · <span style="color:var(--text3);font-weight:400">${escHtml(o.clientCar||'—')}</span></div>
                <div style="font-size:12px;color:var(--text2);margin-top:2px">${escHtml(o.serviceNames||o.notes||'Заявка')}</div>
                <div style="font-size:11px;color:var(--text3);margin-top:2px">□ ${escHtml(o.date||o.dateLabel||'Дата не указана')}${o.time?' · 🕐 '+escHtml(o.time):''}</div>
              </div>
              <div style="display:flex;gap:6px;flex-shrink:0">
                <button class="btn btn-outline" style="font-size:11px;padding:5px 10px" onclick="masterOpenStageModal('${o.id}')">📌 Этап</button>
                <button class="btn btn-outline" style="font-size:11px;padding:5px 10px" onclick="Messenger.openByOrder('${o.id}')">◌</button>
              </div>
            </div>`;
          }).join('')}
          ${unscheduledOrders.length > 5 ? `<div style="text-align:center;font-size:12px;color:var(--text3);padding:6px">ещё ${unscheduledOrders.length-5} заказов</div>` : ''}
        </div>
      </div>` : ''}

    </div>`;
  }
  function _scheduleLabel(row){ return row?.isDayOff ? 'Выходной' : ((row?.startTime||'09:00') + '–' + (row?.endTime||'18:00')); }
  function _masterScheduleRows(masterId, days=7){ const rows=(window.DB?.MasterSchedules?.upcoming?.(masterId, days) || []); if(!rows.length) return '<div style="color:var(--text3);font-size:13px">График пока не заполнен. Нажмите «Редактировать», чтобы добавить смены.</div>'; return rows.map(r=>`<div class="garage-history-item" style="cursor:default"><span class="name">${escHtml(r.workDate||'')}</span><span class="meta">${escHtml(_scheduleLabel(r))}${r.note?(' · '+escHtml(r.note)):''}</span></div>`).join(''); }
  function renderMasterScheduleBlock(masterId){ return `<div class="owner-block"><div class="owner-block-title">🗓 История и смены</div>${_masterScheduleRows(masterId, 10)}</div>`; }


  function renderMasterClientsPane(masterId, orders, chats){
    const esc = (typeof escHtml === 'function') ? escHtml : (v => String(v ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])));
    const norm = v => String(v || '').replace(/\D/g, '');
    const map = new Map();
    const put = (raw) => {
      const phone = norm(raw.phone || raw.clientPhone || '');
      const key = phone || String(raw.clientId || raw.id || raw.orderId || Math.random());
      const cur = map.get(key) || { key, phone, name:'Клиент', cars:new Set(), orders:[], chats:[], total:0, lastAt:'' };
      cur.name = raw.name || raw.clientName || cur.name || 'Клиент';
      const car = raw.car || raw.clientCar || '';
      if (car) cur.cars.add(String(car));
      if (raw.orderId || raw.id) cur.orders.push(raw);
      if (raw.chatId || raw.chat_id) cur.chats.push(raw);
      cur.total += Number(raw.price || raw.total || 0) || 0;
      const d = String(raw.date || raw.dateLabel || raw.createdAt || raw.created_at || raw.updatedAt || raw.updated_at || '');
      if (d && d > cur.lastAt) cur.lastAt = d;
      map.set(key, cur);
    };
    (orders || []).forEach(o => put(Object.assign({}, o, { orderId:o.id })));
    (chats || []).forEach(c => put({ chatId:c.id, orderId:c.orderId, clientName:c.clientName, clientPhone:c.clientPhone, car:c.car, updatedAt:c.updatedAt || c.updated_at }));
    const clients = Array.from(map.values()).sort((a,b)=>String(b.lastAt||'').localeCompare(String(a.lastAt||''),'ru'));
    const activeClients = clients.filter(c => c.orders.some(o => ['new','process','done_pending_client'].includes(String(o.status || '')))).length;
    const withChats = clients.filter(c => c.chats.length).length;
    const cards = clients.map(c => {
      const lastOrder = c.orders.slice().sort((a,b)=>String(b.date||b.createdAt||'').localeCompare(String(a.date||a.createdAt||''),'ru'))[0];
      const chat = c.chats[0] || (lastOrder ? (window.DB?.Chats?.getByOrder?.(lastOrder.id || lastOrder.orderId) || null) : null);
      const cars = Array.from(c.cars).filter(Boolean).slice(0,3).join(' · ');
      const hay = [c.name,c.phone,cars,lastOrder?.serviceNames,lastOrder?.notes,lastOrder?.id].join(' ').toLowerCase();
      return `<article class="master-client-card card" data-master-client="1" data-client-text="${esc(hay)}">
        <div class="master-client-top">
          <div class="master-client-avatar">${esc(String(c.name||'К').slice(0,2).toUpperCase())}</div>
          <div class="master-client-main"><b>${esc(c.name || 'Клиент')}</b><span>${esc(c.phone ? '+' + c.phone : 'Телефон не указан')}${cars ? ' · ' + esc(cars) : ''}</span></div>
        </div>
        <div class="master-client-meta">
          <span>${c.orders.length} заявок</span><span>${chat ? 'есть чат' : 'нет чата'}</span><span>${esc((c.total || 0).toLocaleString('ru'))} ₸</span>
        </div>
        <p>${esc(lastOrder?.serviceNames || lastOrder?.notes || 'История клиента будет пополняться по заявкам и чатам.')}</p>
        <div class="master-client-actions">
          ${lastOrder ? `<button class="btn btn-outline" onclick="OrderSystem.Detail.open('${esc(lastOrder.id || lastOrder.orderId || '')}')">Карточка</button>` : ''}
          ${chat ? `<button class="btn btn-primary" onclick="Messenger.openChat('${esc(chat.id || chat.chatId || '')}')">Открыть чат</button>` : (lastOrder ? `<button class="btn btn-primary" onclick="Messenger.openByOrder('${esc(lastOrder.id || lastOrder.orderId || '')}')">Создать чат</button>` : '')}
        </div>
      </article>`;
    }).join('');
    return `<div class="container master-clients-pane">
      <section class="master-clients-head card">
        <div><span>Клиентская база</span><h2>Клиенты мастера</h2><p>Собраны клиенты из ваших заявок и рабочих чатов. Быстрый переход в карточку заявки и диалог.</p></div>
        <div class="master-clients-stats"><b>${clients.length}</b><small>клиентов</small><b>${activeClients}</b><small>активных</small><b>${withChats}</b><small>с чатами</small></div>
      </section>
      <div class="master-clients-tools card"><input type="search" placeholder="Поиск клиента, авто, телефона или заявки" oninput="window.masterClientsSearch(this.value)"><button class="btn btn-outline" onclick="window.masterClientsSearch('');this.previousElementSibling.value=''">Сброс</button></div>
      <div class="master-clients-grid">${cards || `<div class="card master-clients-empty"><b>Клиентов пока нет</b><p>После первой принятой заявки здесь появится клиент и связанный чат.</p><button class="btn btn-primary" onclick="navMasterMarket()">К бирже заявок</button></div>`}</div>
    </div>`;
  }

  window.masterClientsSearch = function(q){
    const needle = String(q || '').toLowerCase().trim();
    document.querySelectorAll('[data-master-client="1"]').forEach(card => {
      const hay = String(card.dataset.clientText || '').toLowerCase();
      card.style.display = (!needle || hay.includes(needle)) ? '' : 'none';
    });
  };
  window.openMasterScheduleModal = function(masterId){
  try { history.pushState({modal:'openMasterScheduleModal'}, '', '#master:schedule:'+masterId); } catch(_e) {}
  const master=window.DB?.Masters?.get?.(masterId); if(!master) return showToast('Мастер не найден','error'); const rows=(window.DB?.MasterSchedules?.byMaster?.(masterId)||[]); const list = rows.length ? rows.map(r=>`<div class="garage-history-item"><span class="name">${escHtml(r.workDate||'')}</span><span class="meta">${escHtml(_scheduleLabel(r))}${r.note?(' · '+escHtml(r.note)):''}</span><span style="display:flex;gap:6px"><button class="act-btn edit" onclick="editMasterSchedule('${masterId}','${r.id}')">✎</button><button class="act-btn" style="color:#ef4444" onclick="deleteMasterSchedule('${r.id}')">🗑</button></span></div>`).join('') : '<div style="color:var(--text3);font-size:13px">График ещё не задан.</div>'; const html=`<div class="cmodal-card master-schedule-shell" style="max-width:860px"><div class="cmodal-head"><h3>🗓 График мастера · ${escHtml(master.name||'Мастер')}</h3><button type="button" class="cmodal-close" onclick="closeMasterScheduleModal()">✕</button></div><div class="cmodal-body"><div style="display:grid;grid-template-columns:1.15fr .85fr;gap:16px"><div class="schedule-surface" style="padding:16px"><div style="font-weight:700;margin-bottom:10px">Текущий график</div><div id="master-schedule-list">${list}</div></div><div class="schedule-surface" style="padding:16px"><div style="font-weight:700;margin-bottom:10px">Добавить / изменить смену</div><div class="profile-form" style="grid-template-columns:1fr 1fr"><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Дата *</label><input class="pf-input" id="msched-date" type="date"></div><div class="pf-group"><label class="pf-label">Начало</label><input class="pf-input" id="msched-start" type="time" value="09:00"></div><div class="pf-group"><label class="pf-label">Конец</label><input class="pf-input" id="msched-end" type="time" value="18:00"></div><label style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text2);grid-column:1/-1"><input type="checkbox" id="msched-off" onchange="toggleMasterDayOff(this.checked)"> Выходной день</label><div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Примечание</label><input class="pf-input" id="msched-note" placeholder="Например: дежурство до 20:00"></div><input type="hidden" id="msched-id" value=""><input type="hidden" id="msched-master-id" value="${masterId}"><div style="display:flex;gap:8px;grid-column:1/-1"><button class="btn btn-primary" onclick="saveMasterSchedule('${masterId}',this)">Сохранить</button><button class="btn btn-outline" onclick="prefillMasterSchedule('${masterId}')">На сегодня</button></div></div></div></div></div></div>`; const ov=document.createElement('div'); ov.id='master-schedule-modal'; ov.className='cmodal-overlay open'; ov.innerHTML=html; document.body.appendChild(ov); try{ window.bindOnboardingOverlayDismiss && window.bindOnboardingOverlayDismiss(); }catch(_e){} try{ window.armOnboardingOverlayAutoHide && window.armOnboardingOverlayAutoHide(); }catch(_e){} try{ window.App?.LayerManager?.open('master-schedule'); }catch(_e){} setTimeout(()=>{try{window.applyPhoneMasks(ov);}catch(_e){}},30); };
  window.closeMasterScheduleModal = function(){ document.getElementById('master-schedule-modal')?.remove(); try{ window.App?.LayerManager?.close('master-schedule'); }catch(_e){} };
  window.toggleMasterDayOff = function(off){ const s=document.getElementById('msched-start'); const e=document.getElementById('msched-end'); if(s) s.disabled=!!off; if(e) e.disabled=!!off; };
  window.prefillMasterSchedule = function(masterId){ const d=new Date().toISOString().slice(0,10); const existing=window.DB?.MasterSchedules?.forDate?.(masterId,d); document.getElementById('msched-id').value=existing?.id||''; document.getElementById('msched-date').value=d; document.getElementById('msched-start').value=existing?.startTime||'09:00'; document.getElementById('msched-end').value=existing?.endTime||'18:00'; document.getElementById('msched-note').value=existing?.note||''; document.getElementById('msched-off').checked=!!existing?.isDayOff; toggleMasterDayOff(!!existing?.isDayOff); };
  window.editMasterSchedule = function(masterId,id){ const row=window.DB?.MasterSchedules?.get?.(id); if(!row) return; document.getElementById('msched-id').value=row.id||''; document.getElementById('msched-date').value=row.workDate||''; document.getElementById('msched-start').value=row.startTime||'09:00'; document.getElementById('msched-end').value=row.endTime||'18:00'; document.getElementById('msched-note').value=row.note||''; document.getElementById('msched-off').checked=!!row.isDayOff; toggleMasterDayOff(!!row.isDayOff); };
  window.saveMasterSchedule = async function(masterId,btn){
    const _workDate = document.getElementById('msched-date')?.value || '';
    if (!_workDate) { showToast('Укажите дату', 'error'); document.getElementById('msched-date')?.focus(); return; }
    if (!masterId) { showToast('Ошибка: нет ID мастера', 'error'); return; }
    const payload={
      id:document.getElementById('msched-id')?.value||'',
      masterId,
      workDate:_workDate,
      startTime:document.getElementById('msched-start')?.value||'09:00',
      endTime:document.getElementById('msched-end')?.value||'18:00',
      isDayOff:!!document.getElementById('msched-off')?.checked,
      note:document.getElementById('msched-note')?.value?.trim()||''
    };
    if(!payload.workDate){ showToast('Укажите дату','error'); return; }
    if(btn){ btn.disabled=true; btn.textContent='Сохраняем...'; }
    try{
      // Ensure server session is alive before writing
      if(window.App?.syncServerSession){
        const ok = await App.syncServerSession().catch(()=>false);
        if(!ok && !window._appState?.user){ 
          showToast('Требуется авторизация','error');
          try{ closeMasterScheduleModal(); }catch(_){}
          App.showAuth();
          return;
        }
      }
      await window.DB.MasterSchedules.save(payload);
      showToast('График сохранён ✅');
      closeMasterScheduleModal();
      openMasterScheduleModal(masterId);
      const curPage=(window.location.hash||'').slice(1)||'master';
      if(window.App?.go) App.go(curPage);
    }catch(e){
      const msg=String(e?.message||'');
      const is403=msg.includes('403')||msg.includes('forbidden')||msg.includes('master_schedule_save_failed');
      if(is403){
        showToast('Нет доступа — попробуйте перезайти','error');
        try{ closeMasterScheduleModal(); }catch(_){}
        if(window.App?.showAuth) App.showAuth();
      } else {
        showToast(msg||'Не удалось сохранить график','error');
      }
    } finally{
      if(btn){ btn.disabled=false; btn.textContent='Сохранить'; }
    }
  };
  /* Быстрое редактирование дня из недельной сетки мастера */
  window.masterEditDay = function(masterId, dateIso) {
    openMasterScheduleModal(masterId);
    // После открытия модала — предзаполняем форму выбранной датой
    requestAnimationFrame(()=>{
      const existing = window.DB?.MasterSchedules?.forDate?.(masterId, dateIso);
      const idEl   = document.getElementById('msched-id');
      const dateEl = document.getElementById('msched-date');
      const startEl= document.getElementById('msched-start');
      const endEl  = document.getElementById('msched-end');
      const noteEl = document.getElementById('msched-note');
      const offEl  = document.getElementById('msched-off');
      if (!dateEl) return;
      if (idEl)    idEl.value   = existing?.id || '';
      dateEl.value               = dateIso;
      if (startEl) startEl.value = existing?.startTime || '09:00';
      if (endEl)   endEl.value   = existing?.endTime   || '18:00';
      if (noteEl)  noteEl.value  = existing?.note      || '';
      if (offEl)   offEl.checked = !!existing?.isDayOff;
      if (window.toggleMasterDayOff) toggleMasterDayOff(!!existing?.isDayOff);
      // Подсветим форму
      dateEl.scrollIntoView({ behavior:'smooth', block:'center' });
    });
  };
  window.deleteMasterSchedule = async function(id){ try{ const masterId=document.getElementById('msched-master-id')?.value||''; await window.DB.MasterSchedules.delete(id); showToast('Смена удалена'); closeMasterScheduleModal(); if(masterId) openMasterScheduleModal(masterId); }catch(e){ showToast((e&&e.message)||'Не удалось удалить смену','error'); } };

  /* r82_schedule_pattern_override: расширенная админская модалка графика без удаления старой логики */
  window.openMasterScheduleModal = function(masterId){
  try { history.pushState({modal:'openMasterScheduleModal'}, '', '#master:schedule:'+masterId); } catch(_e) {}
    const master=window.DB?.Masters?.get?.(masterId);
    if(!master) return showToast('Мастер не найден','error');
    const rows=(window.DB?.MasterSchedules?.byMaster?.(masterId)||[]);
    const list = rows.length ? rows.map(r=>`<div class="garage-history-item">
      <span class="name">${escHtml(r.workDate||'')}</span>
      <span class="meta">${escHtml(_scheduleLabel(r))}${r.note?(' · '+escHtml(r.note)):''}</span>
      <span style="display:flex;gap:6px"><button class="act-btn edit" onclick="editMasterSchedule('${masterId}','${r.id}')">✎</button><button class="act-btn" style="color:#ef4444" onclick="deleteMasterSchedule('${r.id}')">🗑</button></span>
    </div>`).join('') : '<div style="color:var(--text3);font-size:13px">График ещё не задан.</div>';
    const today = new Date().toISOString().slice(0,10);
    const html=`<div class="cmodal-card master-schedule-shell" style="max-width:980px">
      <div class="cmodal-head"><h3>🗓 График мастера · ${escHtml(master.name||'Мастер')}</h3><button type="button" class="cmodal-close" onclick="closeMasterScheduleModal()">✕</button></div>
      <div class="cmodal-body"><div style="display:grid;grid-template-columns:1.1fr .9fr;gap:16px">
        <div class="schedule-surface" style="padding:16px"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:10px"><div style="font-weight:700">Текущий график</div><button class="btn btn-outline" style="font-size:12px;padding:7px 12px" onclick="prefillMasterSchedule('${masterId}')">Сегодня</button></div><div id="master-schedule-list">${list}</div></div>
        <div style="display:flex;flex-direction:column;gap:12px">
          <div class="schedule-surface" style="padding:16px"><div style="font-weight:700;margin-bottom:10px">Добавить / изменить смену</div><div class="profile-form" style="grid-template-columns:1fr 1fr">
            <div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Дата *</label><input class="pf-input" id="msched-date" type="date"></div>
            <div class="pf-group"><label class="pf-label">Начало</label><input class="pf-input" id="msched-start" type="time" value="09:00"></div>
            <div class="pf-group"><label class="pf-label">Конец</label><input class="pf-input" id="msched-end" type="time" value="18:00"></div>
            <label style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text2);grid-column:1/-1"><input type="checkbox" id="msched-off" onchange="toggleMasterDayOff(this.checked)"> Выходной день</label>
            <div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Примечание</label><input class="pf-input" id="msched-note" placeholder="Например: дежурство до 20:00"></div>
            <input type="hidden" id="msched-id" value=""><input type="hidden" id="msched-master-id" value="${masterId}">
            <div style="display:flex;gap:8px;grid-column:1/-1;flex-wrap:wrap"><button class="btn btn-primary" onclick="saveMasterSchedule('${masterId}',this)">Сохранить день</button><button class="btn btn-outline" onclick="prefillMasterSchedule('${masterId}')">На сегодня</button></div>
          </div></div>
          <div class="schedule-surface" style="padding:16px"><div style="font-weight:700;margin-bottom:6px">Применить график</div><div style="font-size:12px;color:var(--text3);line-height:1.45;margin-bottom:10px">Шаблон перезапишет дни в выбранном периоде. Потом любой день можно поправить вручную.</div><div class="profile-form" style="grid-template-columns:1fr 1fr">
            <div class="pf-group"><label class="pf-label">Шаблон</label><select class="pf-input" id="msched-pattern"><option value="5/2">5/2</option><option value="3/2">3/2</option><option value="4/1">4/1</option><option value="3/3">3/3</option></select></div>
            <div class="pf-group"><label class="pf-label">Дней</label><input class="pf-input" id="msched-pattern-days" type="number" min="1" max="120" value="30"></div>
            <div class="pf-group" style="grid-column:1/-1"><label class="pf-label">Начать с даты</label><input class="pf-input" id="msched-pattern-start" type="date" value="${today}"></div>
            <div style="display:flex;gap:8px;grid-column:1/-1;flex-wrap:wrap"><button class="btn btn-primary" onclick="applyMasterSchedulePattern('${masterId}',this)">Применить шаблон</button></div>
          </div></div>
        </div>
      </div></div>
    </div>`;
    document.getElementById('master-schedule-modal')?.remove();
    const ov=document.createElement('div'); ov.id='master-schedule-modal'; ov.className='cmodal-overlay open'; ov.innerHTML=html; ov.addEventListener('click',e=>{ if(e.target===ov) closeMasterScheduleModal(); }); document.body.appendChild(ov);
    try{ window.App?.LayerManager?.open('master-schedule'); }catch(_e){}
  };
  window.applyMasterSchedulePattern = async function(masterId,btn){
    const rawPattern = document.getElementById('msched-pattern')?.value || '5/2';
    const match = String(rawPattern).match(/^(\d+)\/(\d+)$/);
    if(!match){ showToast('Неверный шаблон графика','error'); return; }
    const workDays = Math.max(1, Number(match[1]||0));
    const offDays  = Math.max(1, Number(match[2]||0));
    const totalDays = Math.min(120, Math.max(1, Number(document.getElementById('msched-pattern-days')?.value||30)));
    const startIso = document.getElementById('msched-pattern-start')?.value || new Date().toISOString().slice(0,10);
    const startTime = document.getElementById('msched-start')?.value || '09:00';
    const endTime   = document.getElementById('msched-end')?.value || '18:00';
    const cycle = workDays + offDays;
    const previewText = 'Применить график ' + rawPattern + ' на ' + totalDays + ' дней с ' + startIso + '?\n\nСуществующие дни в этом периоде будут перезаписаны, но отдельные дни можно поправить вручную.';
    if (typeof window.confirm === 'function' && !window.confirm(previewText)) return;
    if(btn){ btn.disabled=true; btn.textContent='Применяем...'; }
    try{
      for(let i=0;i<totalDays;i++){
        const d = new Date(startIso + 'T00:00:00'); d.setDate(d.getDate()+i);
        const workDate = d.toISOString().slice(0,10);
        const isDayOff = (i % cycle) >= workDays;
        const existing = window.DB?.MasterSchedules?.forDate?.(masterId, workDate);
        await window.DB.MasterSchedules.save({id: existing?.id || '', masterId, workDate, startTime, endTime, isDayOff, note: 'Шаблон ' + rawPattern});
      }
      showToast('График '+rawPattern+' применён на '+totalDays+' дней ✅');
      closeMasterScheduleModal(); openMasterScheduleModal(masterId);
      const curPage=(window.location.hash||'').slice(1)||'master'; if(window.App?.go) App.go(curPage);
    }catch(e){ showToast((e&&e.message)||'Не удалось применить график','error'); }
    finally{ if(btn){ btn.disabled=false; btn.textContent='Применить шаблон'; } }
  };
  function renderMasterCardsForAdmin(){ const masters=(window.DB?.Masters?.getAll?.(true)||[]); /* admin: all masters */ if(!masters.length) return ''; return `<div class="owner-block owner-block-elevated" style="margin-bottom:18px"><div class="owner-block-title">👨‍⌁ Мастера и графики</div><div class="car-grid admin-master-grid">${masters.map(m=>{ const upcoming=(window.DB?.MasterSchedules?.upcoming?.(m.id,3)||[]); const next=upcoming[0]; return `<div class="master-card admin-master-card" onclick="openMasterScheduleModal('${m.id}')" style="cursor:pointer"><div class="car-card-head"><div class="car-ico" style="background:${escHtml(m.color||'#f59e0b')}22;color:${escHtml(m.color||'#f59e0b')}">${escHtml(m.initials||'М')}</div><div><div class="car-title">${escHtml(m.name||'Мастер')}</div><div class="car-sub">${escHtml(m.spec||'')}</div></div></div><div class="car-card-meta">○ ${escHtml(m.phone||'—')}</div><div class="car-badges"><span class="car-badge">${upcoming.length} смен</span>${next?`<span class="car-badge">Ближайшая: ${escHtml(next.workDate||'')} · ${escHtml(_scheduleLabel(next))}</span>`:'<span class="car-badge">График не задан</span>'}</div><div class="admin-master-card-actions"><button class="btn btn-outline" style="font-size:12px;padding:7px 12px" onclick="event.stopPropagation();openMasterScheduleModal('${m.id}')">🗓 График</button><button class="btn btn-primary" style="font-size:12px;padding:7px 12px" onclick="event.stopPropagation();OrderSystem.Detail && showToast('Откройте заявки мастера через таблицу ниже')">▤ Детали</button></div></div>`; }).join('')}</div></div>`; }
  /* MASTER DASHBOARD */
  function resolveCurrentMaster(){
    try{
      const found = window.DB?.Masters?.getMine?.() || null;
      if (found) return found;
      // Fallback: создаём синтетический объект из профиля пользователя
      // пока pull не вернул запись мастера (первый заход, или задержка)
      const u = window._appState?.user;
      if (!u || !['master','admin','owner'].includes(String(u.role||''))) return null;
      const initials = (u.name||'М').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase() || 'М';
      return {
        id: 'local_' + String(u.id||u.phone||'me'),
        userId: u.id || 0,
        userPhone: u.phone || '',
        name: u.name || 'Мастер',
        phone: u.phone || '',
        initials,
        color: '#34d399',
        spec: u.spec || '',
        active: true,
        resume: {},
        _synthetic: true,
      };
    }catch(_e){ return null; }
  }

  function getCurrentMasterOrders(opts={}){
    try{
      if(window.DB?.Orders?.forCurrentMaster) return window.DB.Orders.forCurrentMaster(opts||{});
      const master = resolveCurrentMaster();
      if(!master) return [];
      if(window.DB?.Orders?.forMaster) return window.DB.Orders.forMaster(master, opts||{});
      const rows = window.DB?.Orders?.getAll?.({ masterId: master.id }) || [];
      const list = rows.filter(o=>window.DB?.Orders?.isAttachedToMaster?.(o, master) || String(o.masterId||'')===String(master.id||''));
      return list.filter(o=>opts?.excludeCancelled===false ? true : o.status!=='cancelled');
    }catch(_e){ return []; }
  }

  function getCurrentMasterChats(){
    try{
      if(window.DB?.Chats?.forCurrentMaster) return window.DB.Chats.forCurrentMaster();
      const master = resolveCurrentMaster();
      if(!master) return [];
      const chats = window.DB?.Chats?.getAll?.() || [];
      return chats.filter(c=>String(c.masterId||'')===String(master.id||'') || Number(c.masterUserId||c.master_user_id||0)===Number(master.userId||master.user_id||0));
    }catch(_e){ return []; }
  }

  function getMasterWorkBuckets(orders, allOrders){
    const list = Array.isArray(orders) ? orders : [];
    const pool = Array.isArray(allOrders) ? allOrders : list;
    // Свои заявки (мастер назначен)
    const mine = list.filter(o => String(o.masterId||'0') !== '0');
    // Мои отклики — из exchange store
    const storeState = (() => {
      try { return window.DB?.MasterExchangeStore?.getState?.() || {responses:[]}; }
      catch(_e) { return {responses:[]}; }
    })();
    const myResponses = Array.isArray(storeState.responses) ? storeState.responses : [];
    // ID заявок, по которым мастер уже отправлял отклик.
    // В биржу не возвращаем такие заявки как "новые": управление ими идёт во вкладке "Отклики".
    const activeResponseIds = new Set(
      myResponses
        .filter(r => !['cancelled','declined','rejected','expired'].includes(String(r.responseStatus||r.response_status||'pending')))
        .map(r => String(r.request_id||''))
        .filter(Boolean)
    );
    const anyResponseIds = new Set(
      myResponses.map(r => String(r.request_id||'')).filter(Boolean)
    );
    return {
      new:       mine.filter(o => String(o.status||'') === 'new'),
      process:   mine.filter(o => String(o.status||'') === 'process'),
      done:      mine.filter(o => String(o.status||'') === 'done'),
      returned:  mine.filter(o => ['cancelled','deferred','hold'].includes(String(o.status||''))),
      // Биржа = незакреплённые новые заявки БЕЗ моего отклика (ещё не откликался)
      queue:     pool.filter(o =>
        (o.masterId === '0' || o.masterId === 0 || o.masterId == null || o.masterId === '') &&
        ['new','waiting_responses'].includes(String(o.status||'')) && !activeResponseIds.has(String(o.id||''))
      ),
      // Мои отклики — заявки где я откликнулся но жду решения клиента
      responses: pool.filter(o =>
        anyResponseIds.has(String(o.id||''))
      ),
    };
  }

  function getMasterShopSummary(masterId){
    const shop = DB.Shop.getByMaster(masterId);
    const products = DB.Shop.getAllParts().filter(p=>String(p.masterId||'')===String(masterId||''));
    const sales = Array.isArray(shop?.sales) ? shop.sales : [];
    return {
      shop,
      products,
      sales,
      revenue: sales.reduce((s,x)=>s+(Number(x.total)||((Number(x.qty)||0)*(Number(x.price)||0))),0),
      linkedSales: sales.filter(x=>x.orderId).length,
      requestCount: getCurrentMasterOrders({ excludeCancelled:false }).filter(o=>(o.type||'service_order')==='parts_request').length,
    };
  }

  /* MASTER DASHBOARD */
