  /* ══════════════════════════════════════════
     OWNER ANALYTICS — ГЛУБОКАЯ АНАЛИТИКА
  ══════════════════════════════════════════ */
  function _renderOwnerAnalytics() {
    const allO = DB.Orders.getAll();
    const clients = DB.Clients.getAll();
    const masters = (DB.Masters?.getAll?.(true)||[]); // owner: all
    const done = allO.filter(o=>o.status==='done' && (o.type||'service_order')==='service_order');
    const cancelled = allO.filter(o=>o.status==='cancelled');
    const convRate = allO.length ? Math.round((done.length/allO.length)*100) : 0;
    const avgCheck = done.length ? Math.round(done.reduce((s,o)=>s+(Number(o.price)||0),0)/done.length) : 0;
    const repeatClients = clients.filter(c=>(c.ordersCount||0)>1).length;
    const repeatRate = clients.length ? Math.round(repeatClients/clients.length*100) : 0;

    // Orders by day of week
    const dowMap = [0,0,0,0,0,0,0];
    allO.forEach(o=>{ const d = new Date(o.date||o.createdAt||''); if(!isNaN(d)) dowMap[d.getDay()]++; });
    const maxDow = Math.max(...dowMap, 1);
    const dowNames = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];

    // Orders by hour
    const hourMap = {};
    allO.forEach(o=>{ if(o.time){ const h=parseInt(o.time); if(!isNaN(h)&&h>=8&&h<=19) hourMap[h]=(hourMap[h]||0)+1; } });
    const peakHour = Object.entries(hourMap).sort((a,b)=>b[1]-a[1])[0];

    // Client spend tiers
    const tiers = [{label:'< 5 000 ₸',cnt:0},{label:'5–20 тыс.',cnt:0},{label:'20–50 тыс.',cnt:0},{label:'50 тыс.+',cnt:0}];
    clients.forEach(c=>{
      const s = Number(c.totalSpent||0);
      if(s<5000) tiers[0].cnt++;
      else if(s<20000) tiers[1].cnt++;
      else if(s<50000) tiers[2].cnt++;
      else tiers[3].cnt++;
    });
    const maxTier = Math.max(...tiers.map(t=>t.cnt),1);

    // Master workload
    const masterLoad = masters.map(m=>{
      const total = allO.filter(o=>o.masterId===m.id).length;
      const active = allO.filter(o=>o.masterId===m.id&&o.status==='process').length;
      return {m, total, active};
    }).sort((a,b)=>b.total-a.total);

    return `<div>
      <div style="font-family:'Oswald',sans-serif;font-size:22px;font-weight:700;margin-bottom:20px">📈 Аналитика бизнеса</div>

      <!-- KPI row -->
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:24px">
        ${[
          ['🎯','Конверсия',convRate+'%','заявки → выполнено',convRate>50?'#22c55e':'var(--orange)'],
          ['💳','Средний чек',avgCheck.toLocaleString('ru')+' ₸','за выполненный заказ','var(--orange)'],
          ['🔄','Возврат клиентов',repeatRate+'%','сделали 2+ заказа','#a78bfa'],
          ['⏱','Пиковое время',peakHour?peakHour[0]+':00':'—','самый загруженный час','#60a5fa'],
          ['❌','Отменено',cancelled.length,'заявок отменено','#ef4444'],
          ['▥','Всего заявок',allO.length,'в базе данных','var(--text2)'],
        ].map(([e,l,n,s,c])=>`<div class="card" style="padding:14px 16px">
          <div style="font-size:20px;margin-bottom:6px">${e}</div>
          <div style="font-family:'Oswald',sans-serif;font-size:22px;font-weight:700;color:${c}">${n}</div>
          <div style="font-size:10px;color:var(--text3);font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin:3px 0 2px">${l}</div>
          <div class="t-meta">${s}</div>
        </div>`).join('')}
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px">
        <!-- Heatmap by day of week -->
        <div class="card" style="padding:18px 20px">
          <div style="font-weight:700;font-size:13px;margin-bottom:14px;font-family:'Oswald',sans-serif;text-transform:uppercase;letter-spacing:1px;color:var(--text2)">□ Заявки по дням недели</div>
          <div style="display:flex;align-items:flex-end;gap:8px;height:80px">
            ${dowNames.map((d,i)=>{
              const pct=Math.round(dowMap[i]/maxDow*100);
              const isWeekend=i===0||i===6;
              return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;height:100%;justify-content:flex-end">
                <div style="font-size:9px;color:var(--orange);font-weight:700;opacity:${dowMap[i]?1:.3}">${dowMap[i]||0}</div>
                <div style="width:100%;border-radius:var(--ui-radius-sm,5px) var(--ui-radius-sm,5px) 0 0;background:${isWeekend?'rgba(239,68,68,.5)':'var(--orange)'};opacity:.8;height:${Math.max(3,pct*0.75)}px;min-height:3px;transition:height .4s"></div>
                <div style="font-size:10px;color:${isWeekend?'#ef4444':'var(--text3)'};font-weight:${isWeekend?700:400}">${d}</div>
              </div>`;
            }).join('')}
          </div>
        </div>

        <!-- Client spend tiers -->
        <div class="card" style="padding:18px 20px">
          <div style="font-weight:700;font-size:13px;margin-bottom:14px;font-family:'Oswald',sans-serif;text-transform:uppercase;letter-spacing:1px;color:var(--text2)">▥ Сегменты клиентов</div>
          ${tiers.map((t,i)=>{
            const colors=['#6b7280','#60a5fa','var(--orange)','#f59e0b'];
            return `<div style="margin-bottom:9px">
              <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px">
                <span style="color:var(--text2)">${t.label}</span>
                <span style="color:${colors[i]};font-weight:700">${t.cnt} клиентов</span>
              </div>
              <div style="height:6px;background:var(--line);border-radius:var(--ui-radius-sm,5px)">
                <div style="height:6px;border-radius:var(--ui-radius-sm,5px);background:${colors[i]};width:${Math.round(t.cnt/maxTier*100)}%;transition:width .4s"></div>
              </div>
            </div>`;
          }).join('')}
        </div>
      </div>

      <!-- Master workload table -->
      <div class="card" style="padding:18px 20px;margin-bottom:20px">
        <div style="font-weight:700;font-size:13px;margin-bottom:14px;font-family:'Oswald',sans-serif;text-transform:uppercase;letter-spacing:1px;color:var(--text2)">⌁ Загрузка мастеров</div>
        <div style="overflow-x:auto">
        <table class="admin-table">
          <thead><tr><th>Мастер</th><th>Специализация</th><th>Всего заявок</th><th>В работе</th><th>Нагрузка</th></tr></thead>
          <tbody>
            ${masterLoad.map(({m,total,active})=>{
              const maxTotal=masterLoad[0]?.total||1;
              const pct=Math.round(total/maxTotal*100);
              return `<tr>
                <td><div class="flex-ac-8">
                  <div style="width:28px;height:28px;border-radius:50%;background:${escHtml(m.color||'#34d399')}22;color:${escHtml(m.color||'#34d399')};display:flex;align-items:center;justify-content:center;font-family:'Oswald',sans-serif;font-size:11px;font-weight:700">${escHtml(m.initials||'М')}</div>
                  <span style="font-weight:600">${escHtml(m.name||'Мастер')}</span>
                </div></td>
                <td class="t-sub">${escHtml(m.spec||'—')}</td>
                <td style="font-family:'Oswald',sans-serif;font-size:15px;font-weight:700">${total}</td>
                <td><span class="order-status ${active>0?'process':'done'}" style="font-size:10px">${active}</span></td>
                <td style="min-width:120px">
                  <div style="height:6px;background:var(--line);border-radius:var(--ui-radius-sm,5px)">
                    <div style="height:6px;border-radius:var(--ui-radius-sm,5px);background:${escHtml(m.color||'#34d399')};width:${pct}%;transition:width .4s"></div>
                  </div>
                </td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
        </div>
      </div>

      <!-- Export panel -->
      <div class="owner-block">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px">
          <div class="owner-block-title" style="margin:0">↓ Экспорт данных</div>
          <div class="flex-wrap-8">
            <button class="btn btn-outline" style="font-size:12px;padding:7px 14px" onclick="exportOrdersCSV()">▤ Заявки CSV</button>
            <button class="btn btn-outline" style="font-size:12px;padding:7px 14px" onclick="exportClientsCSV()">◎ Клиенты CSV</button>
            <button class="btn btn-outline" style="font-size:12px;padding:7px 14px" onclick="exportMastersCSV()">⌁ Мастера CSV</button>
          </div>
        </div>
        <div style="font-size:12px;color:var(--text3);margin-top:8px">Данные выгружаются в формате CSV, совместимом с Excel</div>
      </div>
    </div>`;
  }

  /* ══════════════════════════════════════════
     CSV ЭКСПОРТ
  ══════════════════════════════════════════ */
  window.exportOrdersCSV = function(){
    const orders = DB.Orders.getAll();
    const rows = [['ID','Тип','Клиент','Телефон','Авто','Услуги','Мастер','Дата','Время','Сумма','Статус','Создана']];
    orders.forEach(o=>{
      rows.push([
        o.id||'', (o.type||'service_order')==='parts_request'?'Запчасти':'Ремонт',
        o.clientName||'', o.clientPhone||'', o.clientCar||'',
        (o.serviceNames||o.notes||'').replace(/,/g,';'),
        o.masterName||'', o.date||'', o.time||'',
        Number(o.price||0), o.status||'',
        String(o.createdAt||'').slice(0,16),
      ]);
    });
    _downloadCSV(rows, 'kareta_orders_'+new Date().toISOString().slice(0,10)+'.csv');
    showToast('✅ Экспорт заявок готов');
  };

  window.exportClientsCSV = function(){
    const clients = DB.Clients.getAll();
    const rows = [['ID','Имя','Телефон','Авто','Заявок','Потрачено','Создан']];
    clients.forEach(c=>{
      rows.push([c.id||'',c.name||'',c.phone||'',c.car||'',c.ordersCount||0,c.totalSpent||0,String(c.createdAt||'').slice(0,10)]);
    });
    _downloadCSV(rows, 'kareta_clients_'+new Date().toISOString().slice(0,10)+'.csv');
    showToast('✅ Экспорт клиентов готов');
  };

  window.exportMastersCSV = function(){
    const masters = (DB.Masters?.getAll?.()||[]);
    const rows = [['ID','Имя','Телефон','Специализация','Всего заявок','Выручка']];
    masters.forEach(m=>{
      const st = DB.Masters.stats(m.id);
      rows.push([m.id||'',m.name||'',m.phone||'',m.spec||'',st.total,st.revenue]);
    });
    _downloadCSV(rows, 'kareta_masters_'+new Date().toISOString().slice(0,10)+'.csv');
    showToast('✅ Экспорт мастеров готов');
  };

  function _downloadCSV(rows, filename){
    const bom = '\uFEFF';
    const csv = bom + rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    a.click();
    URL.revokeObjectURL(a.href);
  }

  /* ── Owner settings save ── */
  window.saveOwnerSettings = async function(btn) {
    const get = id => document.getElementById(id)?.value.trim() || '';
    const name  = get('settings_name');
    const phone = get('settings_phone');
    if (!name) { showToast('Укажите название сервиса', 'error'); document.getElementById('settings_name')?.focus(); return; }
    const patch = {
      name,
      phone,
      address: get('settings_address'),
      instagram: get('settings_instagram'),
    };
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Сохраняем...'; }
    try {
      // Merge with existing contacts_page content
      const existing = window.DB?.Content?.get?.('contacts_page') || {};
      const body = Object.assign({}, existing.body || {}, patch);
      if (window.DB?.Content?.save) {
        await window.DB.Content.save('contacts_page', { title: existing.title || 'Контакты', body });
      }
      const toast = document.getElementById('settings-toast');
      if (toast) { toast.textContent = '✅ Настройки сохранены'; toast.style.opacity = '1'; setTimeout(()=>toast.style.opacity='0', 3000); }
      showToast('✅ Настройки обновлены');
    } catch(e) {
      showToast(e?.message || 'Ошибка сохранения', 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Сохранить настройки'; }
    }
  };

  /* ── Live KPIs из реальных данных DB ── */
  function _renderLiveKPIs() {
    const dbStatus = DB.isOnline()
      ? `<span style="display:inline-flex;align-items:center;gap:5px;font-size:11px;background:#22c55e18;border:1px solid #22c55e33;color:#22c55e;padding:3px 10px;border-radius:var(--ui-radius-lg,18px);margin-bottom:14px">
           <span style="width:6px;height:6px;border-radius:50%;background:#22c55e;display:inline-block"></span>MySQL подключена</span>`
      : `<span style="display:inline-flex;align-items:center;gap:5px;font-size:11px;background:#ef444418;border:1px solid #ef444433;color:#ef4444;padding:3px 10px;border-radius:var(--ui-radius-lg,18px);margin-bottom:14px">
           <span style="width:6px;height:6px;border-radius:50%;background:#ef4444;display:inline-block"></span>Offline · localStorage</span>`;
    const stats  = DB.Orders.stats();
    const serviceStats = stats.byType?.service_order || { total:0, new:0, process:0, done:0, revenue:0 };
    const partsStats = stats.byType?.parts_request || { total:0, new:0, process:0, done:0, revenue:0 };
    const month  = new Date().toISOString().slice(0,7);
    const allO   = DB.Orders.getAll();
    const monthO = allO.filter(o=>(o.createdAt||'').startsWith(month));
    const serviceMonth = monthO.filter(o=>(o.type||'service_order')==='service_order');
    const partsMonth = monthO.filter(o=>(o.type||'service_order')==='parts_request');
    const revMonth = serviceMonth.filter(o=>o.status==='done').reduce((s,o)=>s+(o.price||0),0);
    const clients  = DB.Clients.getAll();
    const newCl    = clients.filter(c=>(c.createdAt||'').startsWith(month)).length;
    const kpis = [
      ['▥','Выручка ремонта за месяц',revMonth.toLocaleString('ru')+' ₸',serviceStats.done>0?'↑ из выполненных':'—','up'],
      ['⌁','Обычные заявки',String(serviceStats.total),`Новых: ${serviceStats.new}`,serviceStats.new>0?'up':'flat'],
      ['▣','Запросы запчастей',String(partsStats.total),`В подборе: ${partsStats.process}`,partsStats.process>0?'up':'flat'],
      ['◎','Всего клиентов',String(clients.length),`Новых в месяце: ${newCl}`,newCl>0?'up':'flat'],
    ];
    const svcStats = {};
    allO.forEach(o=>{(o.serviceIds||[]).forEach(sid=>{svcStats[sid]=svcStats[sid]||{cnt:0,rev:0};svcStats[sid].cnt++;if(o.status==='done')svcStats[sid].rev+=(o.price||0)/(o.serviceIds.length||1);});});
    const maxCnt = Object.values(svcStats).reduce((m,x)=>Math.max(m,x.cnt),1);
    const svcRows = Object.entries(svcStats).sort((a,b)=>b[1].cnt-a[1].cnt).slice(0,5)
      .map(([sid,d])=>{const svc=DB.Services.get(sid);const pct=Math.round(d.cnt/maxCnt*100);
        return `<div class="bar-row"><div class="bar-label">${svc?.name||sid}<div class="t-meta">${d.cnt} заявок</div></div><div class="bar-track"><div class="bar-fill" style="width:${pct}%"></div></div><div class="bar-val">${Math.round(d.rev).toLocaleString('ru')} ₸</div></div>`;}).join('');
    return `${dbStatus}<div class="kpi-grid">${kpis.map(([e,l,n,c,cl])=>`<div class="kpi-card card"><div class="kpi-emo">${e}</div><div class="kpi-lbl">${l}</div><div class="kpi-num">${n}</div><div class="kpi-ch ${cl}">${c}</div></div>`).join('')}</div>
    <div class="owner-block" style="margin-top:24px"><div class="owner-block-title">▥ Топ услуг</div>${svcRows||'<div style="color:var(--text3);font-size:13px">Нет данных</div>'}</div>`;
  }

  /* ── Журнал аудита ── */
  function _renderAuditLog() {
    const entries = window.Security ? Security.Audit.getLast(100) : [];
    const lbl = {'auth.login':'🔑 Вход','order.cancel':'✕ Отмена','order.finish':'✅ Завершение','booking.create':'□ Запись','user.roleChange':'🔄 Роль','users.setRole':'🔄 Роль','users.setActive':'⛔ Доступ','orders.create':'▣ Заявка','orders.update':'⌁ Обновление заявки','orders.delete':'🗑 Удаление заявки','booking.saved':'□ Запись','receipt.view':'▤ Чек','receipt.print':'🖨️ Печать','receipt.send':'📧 Чек клиенту'};
    const rows = entries.length ? entries.map(e=>{
      const ts=new Date(e.ts);
      const time=String(ts.getHours()).padStart(2,'0')+':'+String(ts.getMinutes()).padStart(2,'0');
      const date=ts.getDate()+'.'+(ts.getMonth()+1);
      return `<div class="audit-row"><span class="audit-ts">${date} ${time}</span><span class="audit-action">${lbl[e.action]||e.action}</span><span class="audit-meta">${e.actor?.name||'—'} (${e.actor?.role||'?'})${e.meta?.orderId?' · '+e.meta.orderId:''}${e.meta?.id?' · '+e.meta.id:''}${e.meta?.newRole?' → '+e.meta.newRole:''}${e.meta?.role?' → '+e.meta.role:''}</span></div>`;
    }).join('')
    : '<div style="color:var(--text3);font-size:13px;padding:16px 0">Журнал пуст</div>';
    const controls = `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px"><div class="owner-block-title">▤ Журнал действий (${entries.length})</div><div style="display:flex;gap:8px"><button class="btn btn-ghost" style="font-size:11px" onclick="refreshOwnerAuditPanel()">↻ Обновить</button><button class="btn btn-ghost" style="font-size:11px;color:var(--red)" onclick="clearOwnerAuditPanel()">🗑️ Очистить в БД</button></div></div>`;
    return `<div class="owner-block">${controls}${rows}</div>`;
  }

  function _renderDbHealthPanel(health){
    if(!health?.ok){
      return `<div class="owner-block" style="margin-top:18px"><div class="owner-block-title">🗄️ Диагностика БД</div><div style="color:var(--text3);font-size:13px;padding-top:8px">Нет данных диагностики</div></div>`;
    }
    const counts = health.counts||{};
    const items = [
      ['Схема', String(health.schemaVersion||0)],
      ['Пользователи', String(counts.users||0)],
      ['Заявки', String(counts.orders||0)],
      ['Чаты', String(counts.chats||0)],
      ['Сообщения', String(counts.messages||0)],
      ['Аудит', String(counts.audit||0)],
      ['System logs', String(counts.systemLogs||0)],
    ];
    return `<div class="owner-block" style="margin-top:18px"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px"><div class="owner-block-title">🗄️ Диагностика БД</div><button class="btn btn-ghost" style="font-size:11px" onclick="refreshDbHealthPanel()">↻ Обновить</button></div><div class="stats-grid" style="margin-top:12px">${items.map(([l,v])=>`<div class="stat-card"><div class="stat-value">${v}</div><div class="stat-label">${l}</div></div>`).join('')}</div></div>`;
  }

  /* ── loyalty redeem modal ── */
  function showLoyaltyRedeem(availPts){
    const pts = Number(availPts) || 0;
    if (pts < 100) { showToast('Минимум 100 баллов для списания', 'error'); return; }
    let el = document.getElementById('loyalty-modal');
    if (!el) {
      el = document.createElement('div');
      el.id = 'loyalty-modal';
      el.className = 'cmodal-overlay';
      document.body.appendChild(el);
      el.addEventListener('click', e => { if (e.target === el) window.__closeLayeredModal?.('loyalty-modal','loyalty'); });
    }
    const presets = [100, 200, 500, Math.min(pts, 1000)].filter((v, i, a) => v <= pts && a.indexOf(v) === i);
    el.innerHTML = `
      <div class="cmodal-box" style="max-width:380px">
        <div class="cmodal-head">
          <h3>💳 Потратить баллы</h3>
          <button type="button" class="cmodal-close" onclick="window.__closeLayeredModal('loyalty-modal','loyalty')">✕</button>
        </div>
        <div class="cmodal-body">
          <p style="font-size:13px;color:var(--text2);margin-bottom:16px;line-height:1.5">
            Баллы будут применены как скидка на следующий заказ.<br>
            <b style="color:var(--orange)">Доступно: ${pts.toLocaleString('ru')} баллов</b>
          </p>
          <div class="loy-redeem-field">
            <label style="font-size:12px;color:var(--text3);font-weight:700;text-transform:uppercase;letter-spacing:.8px;margin-bottom:6px;display:block">Количество баллов</label>
            <input id="redeem-input" type="number" min="100" max="${pts}" step="50" value="${Math.min(200, pts)}"
              style="width:100%;background:var(--surface);border:2px solid var(--orange);border-radius:var(--ui-radius-md,10px);padding:13px 14px;font-size:22px;font-family:'Oswald',sans-serif;color:var(--orange);text-align:center;outline:none;box-sizing:border-box">
            <div id="redeem-save" style="text-align:center;font-size:13px;color:var(--text2);margin-top:8px">
              Скидка: <b id="redeem-save-val" style="color:var(--orange)">${Math.min(200, pts).toLocaleString('ru')} ₸</b>
            </div>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;justify-content:center">
            ${presets.map(v=>`<button onclick="document.getElementById('redeem-input').value=${v};document.getElementById('redeem-save-val').textContent='${v.toLocaleString('ru')} ₸'" class="btn btn-outline" style="padding:6px 14px;font-size:13px">${v.toLocaleString('ru')}</button>`).join('')}
            <button onclick="document.getElementById('redeem-input').value=${pts};document.getElementById('redeem-save-val').textContent='${pts.toLocaleString('ru')} ₸'" class="btn btn-outline" style="padding:6px 14px;font-size:13px">Все ${pts.toLocaleString('ru')}</button>
          </div>
          <div style="display:flex;gap:10px;margin-top:20px">
            <button class="btn btn-outline" style="flex:1;justify-content:center" onclick="window.__closeLayeredModal('loyalty-modal','loyalty')">Отмена</button>
            <button class="btn btn-primary" id="redeem-ok" style="flex:1;justify-content:center">Применить</button>
          </div>
        </div>
      </div>`;
    document.getElementById('redeem-input').addEventListener('input', function(){
      const v = Math.min(pts, Math.max(0, parseInt(this.value)||0));
      const el2 = document.getElementById('redeem-save-val');
      if (el2) el2.textContent = v.toLocaleString('ru') + ' ₸';
    });
    document.getElementById('redeem-ok').onclick = () => {
      const inp = document.getElementById('redeem-input');
      const v = Math.min(pts, Math.max(0, parseInt(inp?.value)||0));
      if (v < 100) { showToast('Минимум 100 баллов', 'error'); return; }
      // Сохраняем транзакцию списания
      const u2 = S.user;
      if (!u2?.phone) { showToast('Ошибка: нет пользователя', 'error'); return; }
      const KEY = 'kareta_loyalty_' + (u2.phone||'').replace(/\D/g,'');
      let store;
      try { store = JSON.parse(localStorage.getItem(KEY)||'null') || { earned:0, spent:0, txns:[] }; } catch(_e) { store = { earned:0, spent:0, txns:[] }; }
      store.spent = (store.spent||0) + v;
      store.txns = store.txns || [];
      store.txns.push({ id: 'spend_'+Date.now(), type:'spend', pts:v, label:'Списание на скидку', date: new Date().toISOString().slice(0,10) });
      try { localStorage.setItem(KEY, JSON.stringify(store)); } catch(_e){}
      window.__closeLayeredModal?.('loyalty-modal','loyalty');
      showToast('✅ ' + v.toLocaleString('ru') + ' баллов зарезервированы — скидка применится при следующем заказе', 'success');
      // Обновляем пейн лояльности
      setTimeout(() => {
        const pane = document.getElementById('cp-loyalty');
        if (pane && pane.classList.contains('active')) { App.go('cabinet'); setTimeout(()=>{ document.querySelector('[data-tab="loyalty"]')?.click(); },80); }
      }, 800);
    };
    el.classList.add('open');
    try{ window.App?.LayerManager?.open?.('loyalty'); }catch(_e){}
  }
  window.showLoyaltyRedeem = showLoyaltyRedeem;

  /* ── Загрузка фото профиля из галереи + квадратное кадрирование ── */
  window.cabUploadPhoto = function(input) {
    const file = input?.files?.[0];
    if (!file) return;
    if (!String(file.type || '').startsWith('image/')) {
      showToast('Выберите изображение', 'error');
      input.value = '';
      return;
    }
    if (file.size > 6 * 1024 * 1024) {
      showToast('Фото не должно превышать 6 МБ', 'error');
      input.value = '';
      return;
    }
    const reader = new FileReader();
    reader.onload = function(e) {
      window.openCabAvatarCropper?.(String(e.target?.result || ''), input);
    };
    reader.onerror = function(){ showToast('Не удалось прочитать фото', 'error'); input.value = ''; };
    reader.readAsDataURL(file);
  };

  window.openCabAvatarCropper = function(src, inputRef) {
    if (!src) return;
    let modal = document.getElementById('cab-avatar-crop-modal');
    if (!modal) {
      modal = document.createElement('div');
      modal.id = 'cab-avatar-crop-modal';
      modal.className = 'cab-avatar-crop-modal';
      modal.innerHTML = `
        <div class="cab-avatar-crop-backdrop" data-cab-crop-cancel="1"></div>
        <div class="cab-avatar-crop-card" role="dialog" aria-modal="true" aria-label="Кадрирование фото профиля">
          <div class="cab-avatar-crop-head">
            <div>
              <div class="cab-avatar-crop-title">Выделите портрет</div>
              <div class="cab-avatar-crop-sub">Перетащите квадратную область. Будет сохранён только выбранный фрагмент.</div>
            </div>
            <button type="button" class="cab-avatar-crop-x" data-cab-crop-cancel="1" aria-label="Закрыть">×</button>
          </div>
          <div class="cab-avatar-crop-stage-wrap">
            <div class="cab-avatar-crop-stage" id="cab-avatar-crop-stage">
              <img id="cab-avatar-crop-img" alt="Фото для кадрирования">
              <div class="cab-avatar-crop-shade"></div>
              <div class="cab-avatar-crop-box" id="cab-avatar-crop-box">
                <span class="cab-avatar-crop-grid"></span>
              </div>
            </div>
          </div>
          <div class="cab-avatar-crop-actions">
            <button type="button" class="btn btn-outline" data-cab-crop-cancel="1">Отмена</button>
            <button type="button" class="btn btn-primary" id="cab-avatar-crop-save">Сохранить</button>
          </div>
        </div>`;
      document.body.appendChild(modal);
    }

    const img = modal.querySelector('#cab-avatar-crop-img');
    const stage = modal.querySelector('#cab-avatar-crop-stage');
    const box = modal.querySelector('#cab-avatar-crop-box');
    const saveBtn = modal.querySelector('#cab-avatar-crop-save');
    if (!img || !stage || !box || !saveBtn) return;

    let state = { x:0, y:0, size:180, dragging:false, sx:0, sy:0, ox:0, oy:0, imgRect:null, scaleX:1, scaleY:1 };
    const clamp = (v,min,max)=>Math.max(min, Math.min(max, v));

    function closeCropper(){
      modal.classList.remove('open');
      document.body.classList.remove('cab-avatar-crop-open');
      if (inputRef) inputRef.value = '';
    }
    function applyBox(){
      box.style.width = state.size + 'px';
      box.style.height = state.size + 'px';
      box.style.left = state.x + 'px';
      box.style.top = state.y + 'px';
    }
    function initBox(){
      const sr = stage.getBoundingClientRect();
      const ir = img.getBoundingClientRect();
      const left = Math.max(0, ir.left - sr.left);
      const top = Math.max(0, ir.top - sr.top);
      const w = Math.max(80, ir.width);
      const h = Math.max(80, ir.height);
      const size = Math.floor(Math.min(w, h) * 0.78);
      state.imgRect = { left, top, width:w, height:h };
      state.size = clamp(size, 96, Math.min(w,h));
      state.x = left + Math.floor((w - state.size) / 2);
      state.y = top + Math.floor((h - state.size) / 2);
      state.scaleX = img.naturalWidth / w;
      state.scaleY = img.naturalHeight / h;
      applyBox();
    }
    function moveTo(nx, ny){
      const r = state.imgRect;
      if (!r) return;
      state.x = clamp(nx, r.left, r.left + r.width - state.size);
      state.y = clamp(ny, r.top, r.top + r.height - state.size);
      applyBox();
    }

    const onPointerDown = (ev)=>{
      ev.preventDefault();
      state.dragging = true;
      state.sx = ev.clientX || ev.touches?.[0]?.clientX || 0;
      state.sy = ev.clientY || ev.touches?.[0]?.clientY || 0;
      state.ox = state.x;
      state.oy = state.y;
      box.setPointerCapture?.(ev.pointerId);
      box.classList.add('dragging');
    };
    const onPointerMove = (ev)=>{
      if (!state.dragging) return;
      ev.preventDefault();
      const cx = ev.clientX || ev.touches?.[0]?.clientX || 0;
      const cy = ev.clientY || ev.touches?.[0]?.clientY || 0;
      moveTo(state.ox + (cx - state.sx), state.oy + (cy - state.sy));
    };
    const onPointerUp = (ev)=>{
      state.dragging = false;
      box.releasePointerCapture?.(ev.pointerId);
      box.classList.remove('dragging');
    };

    box.onpointerdown = onPointerDown;
    window.removeEventListener('pointermove', window.__cabCropMove || (()=>{}));
    window.removeEventListener('pointerup', window.__cabCropUp || (()=>{}));
    window.__cabCropMove = onPointerMove;
    window.__cabCropUp = onPointerUp;
    window.addEventListener('pointermove', onPointerMove, { passive:false });
    window.addEventListener('pointerup', onPointerUp);

    modal.querySelectorAll('[data-cab-crop-cancel]').forEach(btn => { btn.onclick = closeCropper; });
    saveBtn.onclick = async function(){
      try {
        const r = state.imgRect;
        if (!r || !img.naturalWidth || !img.naturalHeight) throw new Error('crop_not_ready');
        const sx = Math.round((state.x - r.left) * state.scaleX);
        const sy = Math.round((state.y - r.top) * state.scaleY);
        const sw = Math.round(state.size * state.scaleX);
        const sh = Math.round(state.size * state.scaleY);
        const canvas = document.createElement('canvas');
        const out = 512;
        canvas.width = out;
        canvas.height = out;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, out, out);
        ctx.drawImage(img, sx, sy, sw, sh, 0, 0, out, out);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.88);

        const avWrap = document.querySelector('.cab-avatar-wrap');
        if (avWrap) {
          const existing = avWrap.querySelector('.cab-avatar--photo');
          const initials = avWrap.querySelector('.cab-avatar:not(.cab-avatar--photo)');
          if (existing) { existing.src = dataUrl; }
          else if (initials) {
            const photo = document.createElement('img');
            photo.className = 'cab-avatar cab-avatar--photo';
            photo.src = dataUrl;
            photo.alt = '';
            avWrap.replaceChild(photo, initials);
          }
        }

        if (window.App?.mergeUserPatch) window.App.mergeUserPatch({ photoUrl: dataUrl });
        if (S?.user) S.user.photoUrl = dataUrl;
        await window.App?.persistServerProfile?.({ photoUrl: dataUrl });
        closeCropper();
        showToast('Фото профиля обновлено');
      } catch(_e) {
        closeCropper();
        showToast('Фото сохранено локально', 'success');
      }
    };

    img.onload = function(){ requestAnimationFrame(initBox); };
    img.src = src;
    modal.classList.add('open');
    document.body.classList.add('cab-avatar-crop-open');
    setTimeout(initBox, 80);
  };

  /* public API */

  /* ── Master earnings CSV export ── */
  /* ── Client orders CSV ── */
  window.exportClientOrders = function(){
    const u = window._appState?.user;
    if(!u) return;
    const cl = window.DB?.Clients?.getByPhone?.(u.phone);
    const orders = cl
      ? window.DB?.Orders?.getAll?.({clientId:cl.id})||[]
      : (window.DB?.Orders?.getAll?.()||[]).filter(o=>(o.clientPhone||'').replace(/\D/g,'') === (u.phone||'').replace(/\D/g,''));
    const rows=[['ID','Услуга','Дата','Мастер','Сумма','Статус']];
    orders.forEach(o=>rows.push([o.id||'',o.serviceNames||o.notes||'',o.date||'',o.masterName||'',Number(o.price||0),o.status||'']));
    const bom='\uFEFF';
    const csv=bom+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');
    const a=document.createElement('a');
    a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));
    a.download='my_orders_'+new Date().toISOString().slice(0,10)+'.csv';
    a.click(); URL.revokeObjectURL(a.href);
    showToast('✅ Экспорт готов');
  };

  window.exportMasterEarnings = function(masterId){
    const done = (window.DB?.Orders?.getAll?.({masterId})||[]).filter(o=>o.status==='done');
    const rows=[['Дата','Клиент','Авто','Услуга','Сумма']];
    done.forEach(o=>rows.push([o.date||'',o.clientName||'',o.clientCar||'',(o.serviceNames||'').replace(/,/g,';'),Number(o.price||0)]));
    const bom='\uFEFF';
    const csv=bom+rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');
    const a=document.createElement('a');
    a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));
    a.download='earnings_'+masterId+'_'+new Date().toISOString().slice(0,10)+'.csv';
    a.click(); URL.revokeObjectURL(a.href);
    showToast('✅ Экспорт готов');
  };

  /* ── Global quick search (Ctrl+K / Cmd+K) ── */
  (function(){
    let qs=null;
    function open(){
      if(qs){qs.querySelector('#qs-input')?.focus();return;}
      qs=document.createElement('div');
      qs.id='quick-search-overlay';
      qs.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.6);display:flex;align-items:flex-start;justify-content:center;padding-top:10vh;backdrop-filter:blur(4px)';
      qs.innerHTML=`<div style="width:100%;max-width:560px;background:var(--bg2,#1a1a1a);border:1px solid var(--line,#333);border-radius:var(--ui-radius-md,10px);overflow:hidden;box-shadow:0 24px 64px rgba(0,0,0,.5)">
        <div style="display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--line,#333)">
          <span style="font-size:18px;opacity:.5">⌕</span>
          <input id="qs-input" placeholder="Поиск клиента, заявки, мастера..." style="flex:1;background:none;border:none;outline:none;font-size:16px;color:var(--text,#fff);font-family:'Mulish',sans-serif">
          <kbd style="font-size:11px;color:var(--text3);background:var(--surface,#111);border:1px solid var(--line);border-radius:var(--ui-radius-sm,5px);padding:2px 6px">Esc</kbd>
        </div>
        <div id="qs-results" style="max-height:380px;overflow-y:auto;padding:8px 0"></div>
        <div style="padding:8px 16px;border-top:1px solid var(--line,#333);font-size:11px;color:var(--text3);display:flex;gap:16px">
          <span>↑↓ навигация</span><span>Enter открыть</span><span>Esc закрыть</span>
        </div>
      </div>`;
      document.body.appendChild(qs);
      const inp=qs.querySelector('#qs-input');
      const res=qs.querySelector('#qs-results');
      let items=[], sel=0;
      function render(q){
        items=[]; sel=0;
        if(!q||q.length<2){
          const u=window._appState?.user;
          const hint=!u?'Войдите для поиска по заявкам и клиентам'
            :(['admin','owner','master'].includes(u.role)?'Поиск по заявкам, клиентам, мастерам...'
            :'Введите номер заявки, дату или услугу...');
          res.innerHTML=`<div style="padding:20px;text-align:center;color:var(--text3);font-size:13px">${hint}</div>`;
          return;
        }
        const ql=q.toLowerCase();
        // Search orders
        const u=window._appState?.user;
        const allOrders=(window.DB?.Orders?.getAll?.()||[]);
        // Clients see their own orders; admin/master see all
        const visibleOrders = (u&&['admin','owner','master'].includes(u.role))
          ? allOrders
          : allOrders.filter(o=>(o.clientPhone||'').replace(/\D/g,'') === (u?.phone||'').replace(/\D/g,''));
        const orders=visibleOrders.filter(o=>
          (o.clientName||'').toLowerCase().includes(ql)||
          (o.id||'').toLowerCase().includes(ql)||
          (o.clientPhone||'').includes(q)||
          (o.serviceNames||'').toLowerCase().includes(ql)
        ).slice(0,5);
        orders.forEach(o=>items.push({type:'order',label:o.clientName||o.id,sub:(o.serviceNames||'')+'·'+(o.date||''),id:o.id,icon:'▤'}));
        // Search clients
        const clients=(window.DB?.Clients?.getAll?.()||[]).filter(c=>
          (c.name||'').toLowerCase().includes(ql)||
          (c.phone||'').includes(q)
        ).slice(0,3);
        clients.forEach(c=>items.push({type:'client',label:c.name||c.phone,sub:c.phone||'',id:c.id,icon:'○'}));
        // Search masters
        const masters=(window.DB?.Masters?.getAll?.()||[]).filter(m=>
          (m.name||'').toLowerCase().includes(ql)||
          (m.spec||'').toLowerCase().includes(ql)
        ).slice(0,2);
        masters.forEach(m=>items.push({type:'master',label:m.name,sub:m.spec||'',id:m.id,icon:'⌁'}));
        if(!items.length){res.innerHTML='<div style="padding:20px;text-align:center;color:var(--text3);font-size:13px">Ничего не найдено</div>';return;}
        res.innerHTML=items.map((it,i)=>`<div class="qs-item" data-idx="${i}" onclick="window._qsSelect(${i})" style="display:flex;align-items:center;gap:12px;padding:10px 16px;cursor:pointer;transition:.1s;background:${i===sel?'var(--orange-dim,rgba(255,107,0,.12))':'none'}">
          <span style="font-size:18px">${it.icon}</span>
          <div><div style="font-size:14px;font-weight:600;color:var(--text,#fff)">${escHtml(it.label)}</div>
          <div class="t-meta">${escHtml(it.sub)}</div></div>
          <span style="margin-left:auto;font-size:10px;color:var(--text3);background:var(--surface,#111);border:1px solid var(--line);border-radius:var(--ui-radius-sm,5px);padding:2px 6px">${{order:'Заявка',client:'Клиент',master:'Мастер'}[it.type]||it.type}</span>
        </div>`).join('');
      }
      window._qsSelect=function(i){
        const it=items[i];
        if(!it) return;
        close();
        if(it.type==='order') window.OrderSystem?.Detail?.open?.(it.id);
        else if(it.type==='master'&&window.Admin) Admin.showPane('masters');
        else if(it.type==='client') window.OrderSystem?.ClientsPanel?.render?.('admin-panes');
      };
      inp.addEventListener('input',()=>render(inp.value));
      inp.addEventListener('keydown',e=>{
        if(e.key==='Escape'){close();}
        else if(e.key==='ArrowDown'){sel=Math.min(sel+1,items.length-1);render(inp.value);}
        else if(e.key==='ArrowUp'){sel=Math.max(sel-1,0);render(inp.value);}
        else if(e.key==='Enter'){window._qsSelect(sel);}
      });
      qs.addEventListener('click',e=>{ if(e.target===qs) close(); });
    }
    function close(){if(qs){qs.remove();qs=null;}}
    document.addEventListener('keydown',e=>{
      if((e.ctrlKey||e.metaKey)&&e.key==='k'){ e.preventDefault(); open(); }
    });
    window._quickSearch={ open, close };
  })();

