  function refreshOwnerSchedulePane(){
    const pane = document.getElementById('op-schedule');
    if(!pane) return;
    const container = pane.querySelector('.container');
    if(!container) return;
    const DAY_NAMES=['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
    const base=new Date(); base.setHours(0,0,0,0);
    const weekDays=Array.from({length:7},(_,i)=>{ const d=new Date(base); d.setDate(d.getDate()+i); return d; });
    const todayIso=base.toISOString().slice(0,10);
    const masters=(DB.Masters?.getAll?.(true)||[]); // owner: all masters
    let html=`<div style="font-family:'Oswald',sans-serif;font-size:20px;font-weight:700;margin-bottom:20px">🗓 Графики мастеров на неделю</div>`;
    if(!masters.length){
      html+='<div style="color:var(--text3);text-align:center;padding:40px 0">Мастеров пока нет</div>';
    } else {
      html+=masters.map(m=>{
        const allOrders=DB.Orders.getAll({masterId:m.id}).filter(o=>o.status!=='cancelled');
        const weekCells=weekDays.map(d=>{
          const iso=d.toISOString().slice(0,10);
          const sched=DB.MasterSchedules.forDate(m.id,iso);
          const dayOrders=allOrders.filter(o=>o.date===iso);
          const isToday=iso===todayIso;
          const dayName=DAY_NAMES[d.getDay()];
          const dayNum=d.getDate();
          const monthStr=(d.getMonth()+1).toString().padStart(2,'0');
          let hoursHtml,cellBg,borderColor;
          if(!sched){
            hoursHtml=`<div style="font-size:10px;color:var(--text3);margin-top:3px">Не задан</div>`;
            cellBg='var(--bg2)'; borderColor='var(--line)';
          } else if(sched.isDayOff){
            hoursHtml=`<div style="font-size:10px;color:#ef4444;font-weight:600;margin-top:3px">Выходной</div>`;
            cellBg='rgba(239,68,68,.06)'; borderColor='rgba(239,68,68,.25)';
          } else {
            hoursHtml=`<div style="font-size:10px;color:var(--green);font-weight:600;margin-top:3px">${escHtml(sched.startTime||'09:00')}–${escHtml(sched.endTime||'18:00')}</div>`;
            cellBg='rgba(52,211,153,.06)'; borderColor='rgba(52,211,153,.3)';
          }
          const ordBadge=dayOrders.length?`<div style="margin-top:4px"><span style="font-size:9px;background:var(--orange-dim);color:var(--orange);border-radius:99px;padding:1px 5px;font-weight:700">${dayOrders.length}</span></div>`:'';
          return `<div onclick="masterEditDay('${escHtml(m.id)}','${iso}')" title="Изменить этот день" style="background:${cellBg};border:1.5px solid ${borderColor};border-radius:var(--ui-radius-sm,5px);padding:8px 6px 6px;text-align:center;cursor:pointer;transition:box-shadow .15s;flex:1;min-width:0" onmouseenter="this.style.boxShadow='0 0 0 2px var(--orange)'" onmouseleave="this.style.boxShadow=''">
            <div style="font-size:9px;color:var(--text3);font-weight:700;text-transform:uppercase;letter-spacing:1px">${dayName}</div>
            <div style="font-family:'Oswald',sans-serif;font-size:17px;font-weight:700;color:${isToday?'var(--orange)':'var(--text1)'}">${dayNum}</div>
            <div style="font-size:9px;color:var(--text3)">${monthStr}</div>
            ${hoursHtml}${ordBadge}
          </div>`;
        }).join('');
        return `<div class="cmodal-card master-schedule-shell" style="margin-bottom:18px;max-width:100%">
          <div class="cmodal-head" style="padding:14px 18px">
            <div class="flex-ac-10">
              <div style="width:34px;height:34px;border-radius:50%;background:${escHtml(m.color||'#f59e0b')}22;color:${escHtml(m.color||'#f59e0b')};display:flex;align-items:center;justify-content:center;font-family:'Oswald',sans-serif;font-size:14px;font-weight:700;border:1.5px solid ${escHtml(m.color||'#f59e0b')}44">${escHtml(m.initials||'М')}</div>
              <div>
                <div style="font-weight:700;font-size:15px">${escHtml(m.name||'Мастер')}</div>
                <div class="t-meta">${escHtml(m.spec||'')}</div>
              </div>
            </div>
            <button class="btn btn-outline" style="font-size:11px;padding:6px 12px;margin-left:auto" onclick="openMasterScheduleModal('${escHtml(m.id)}')">✎ Редактировать</button>
          </div>
          <div class="cmodal-body" style="padding:14px var(--ui-radius-lg,18px) var(--ui-radius-lg,18px)">
            <div style="display:flex;gap:6px">${weekCells}</div>
            <div style="display:flex;gap:12px;margin-top:10px;font-size:10px;color:var(--text3)">
              <span><span style="color:var(--green)">●</span> Рабочий</span>
              <span><span style="color:#ef4444">●</span> Выходной</span>
              <span style="opacity:.5">○ Не задан</span>
              <span style="opacity:.6;margin-left:4px">Нажмите на день для редактирования</span>
            </div>
          </div>
        </div>`;
      }).join('');
    }
    container.innerHTML = html;
  }

