  const st = (window.DB && window.DB.News && window.DB.News.stats) ? window.DB.News.stats() : {total:0,totalViews:0,featured:0,byCategory:{}};
  const cats = (window.DB && window.DB.News && window.DB.News.CATEGORIES) || {};
  var html = '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:24px">';
  var cards = [[st.total,'▤','Всего статей','var(--orange)'],[Number(st.totalViews||0).toLocaleString('ru'),'👁','Просмотров','#60a5fa'],[st.featured,'☆','Главных','#f59e0b'],[Object.keys(st.byCategory||{}).filter(function(k){return st.byCategory[k]>0;}).length,'📂','Категорий','#34d399']];
  cards.forEach(function(item){ html += '<div class="card" style="padding:14px 16px;border-left:3px solid '+item[3]+'"><div style="font-size:22px;margin-bottom:4px">'+item[1]+'</div><div style="font-family:\'Oswald\',sans-serif;font-size:20px;font-weight:700;color:'+item[3]+'">'+item[0]+'</div><div style="font-size:11px;color:var(--text3);margin-top:4px">'+item[2]+'</div></div>'; });
