window.ownerNewsEdit = function(btnOrJson){
  var a;
  try {
    if (btnOrJson && btnOrJson.dataset && btnOrJson.dataset.article) a = JSON.parse(btnOrJson.dataset.article);
    else if (typeof btnOrJson === 'string') a = JSON.parse(btnOrJson);
    else a = {};
  } catch(e){ if(window.showToast) showToast('Ошибка','error'); return; }
  document.getElementById('owner-news-modal-title').textContent = 'Редактировать статью';
  document.getElementById('on-id').value = a.id||'';
  document.getElementById('on-title').value = a.title||'';
  document.getElementById('on-category').value = a.category||'tips';
  document.getElementById('on-author').value = a.authorName||a.author_name||'';
  document.getElementById('on-role').value = a.authorRole||a.author_role||'';
  document.getElementById('on-date').value = a.publishedAt||a.published_at||new Date().toISOString().slice(0,10);
  document.getElementById('on-cover').value = a.coverUrl||a.cover_url||'';
  document.getElementById('on-readtime').value = a.readingTime||a.reading_time||3;
  document.getElementById('on-intro').value = a.intro||'';
  document.getElementById('on-body').value = a.body||'';
  document.getElementById('on-featured').checked = !!(a.isFeatured||a.is_featured);
  document.getElementById('on-active').checked = a.active!==false;
  ownerNewsPreviewCover(a.coverUrl||a.cover_url||'');
  document.getElementById('owner-news-modal').style.display = 'block';
};
window.ownerNewsCloseModal = function(){
  document.getElementById('owner-news-modal').style.display = 'none';
};
window.ownerNewsSave = async function(btn){
  var title = document.getElementById('on-title').value.trim();
  if (!title) { if(window.showToast) showToast('Укажите заголовок','error'); return; }
  if (btn) { btn.disabled=true; btn.textContent='⏳ Сохраняем…'; }
  var toast = document.getElementById('on-toast');
  try {
    var idVal = document.getElementById('on-id').value;
    var article = {
      title: title,
      category: document.getElementById('on-category').value || 'tips',
      authorName: document.getElementById('on-author').value.trim(),
      authorRole:  document.getElementById('on-role').value.trim(),
      publishedAt: document.getElementById('on-date').value || new Date().toISOString().slice(0,10),
      coverUrl:    document.getElementById('on-cover').value.trim(),
      readingTime: parseInt(document.getElementById('on-readtime').value)||3,
      intro:       document.getElementById('on-intro').value.trim(),
      body:        document.getElementById('on-body').value,
      isFeatured:  document.getElementById('on-featured').checked,
      active:      document.getElementById('on-active').checked,
    };
    if (idVal) article.id = idVal;
    await window.DB.News.save(article);
    if (toast) { toast.textContent='✓ Сохранено'; toast.style.opacity='1'; setTimeout(function(){toast.style.opacity='0';},2500); }
    ownerNewsCloseModal();
    ownerNewsRefreshList();
    ownerNewsRefreshStats();
  } catch(e) {
    if(window.showToast) showToast((e&&e.message)||'Ошибка сохранения','error');
  } finally {
    if (btn) { btn.disabled=false; btn.textContent='Сохранить'; }
  }
};
window.ownerNewsDelete = async function(id, title){
  if (!confirm('Удалить статью «'+title+'»?')) return;
  try {
    await window.DB.News.delete(id);
    ownerNewsRefreshList();
    ownerNewsRefreshStats();
    if(window.showToast) showToast('Статья удалена');
  } catch(e) { if(window.showToast) showToast((e&&e.message)||'Ошибка','error'); }
};

