  document.getElementById('news-entry-id').value = '';
  document.getElementById('news-entry-headline').value = '';
  document.getElementById('news-entry-category').value = 'tips';
  document.getElementById('news-entry-cover').value = '';
  document.getElementById('news-entry-intro').value = '';
  document.getElementById('news-entry-body').value = '';
  document.getElementById('news-entry-modal').classList.add('open');
  try{ window.App?.LayerManager?.open?.('news-entry'); }catch(_e){}
