/* ═══════════════════════════════════════════════════════════════════
   SPLASH SCREEN — логотип из центра в nav
═══════════════════════════════════════════════════════════════════ */
(function initSplash() {
  const splash = document.getElementById('kareta-splash');
  const wrap   = document.getElementById('splashLogoWrap');
  if (!splash || !wrap) return;

  // Публичный промис — App.init ждёт его перед запуском entry flow
  window._splashDonePromise = new Promise(resolve => {
    window._splashDoneResolve = resolve;
  });

  let _animDone = false;

  function _runSplashAnimate() {
    if (_animDone) return;
    _animDone = true;

    const navLogo = null;
    if (!navLogo) { _finishSplash(); return; }

    const rect    = navLogo.getBoundingClientRect();
    const targetX = rect.left + rect.width  / 2;
    const targetY = rect.top  + rect.height / 2;

    // Top header target was removed; splash finishes without top-logo-target animation.
    // Previous top-logo-target geometry is no longer used.
    // Весь блок с текстом — масштабируем сильнее
    const splashIconPx = 52;
    const navIconPx    = 30;
    const endScale     = navIconPx / splashIconPx; // ≈ 0.58

    // Стартуем из центра (сбрасываем transition)
    wrap.style.transition = 'none';
    wrap.style.left      = '50%';
    wrap.style.top       = '50%';
    wrap.style.transform = 'translate(-50%,-50%) scale(2.6)';
    void wrap.offsetWidth; // force reflow

    // Анимация в top-logo-target отключена вместе с верхним header
    wrap.style.transition =
      'left 0.68s cubic-bezier(.32,.72,0,1),' +
      'top  0.68s cubic-bezier(.32,.72,0,1),' +
      'transform 0.68s cubic-bezier(.32,.72,0,1),' +
      'opacity 0.28s ease 0.44s';
    wrap.style.left      = targetX + 'px';
    wrap.style.top       = targetY + 'px';
    wrap.style.transform = 'translate(-50%,-50%) scale(' + endScale + ')';
    wrap.style.opacity   = '0';

    // Убираем overlay сразу после исчезновения логотипа
    setTimeout(_finishSplash, 780);
  }

  function _finishSplash() {
    splash.style.transition = 'opacity 0.18s ease';
    splash.style.opacity    = '0';
    splash.style.pointerEvents = 'none';
    setTimeout(() => {
      try { splash.remove(); } catch(e) {}
      // Сигналим App.init что splash завершён
      if (typeof window._splashDoneResolve === 'function') {
        window._splashDoneResolve();
        window._splashDoneResolve = null;
      }
    }, 200);
  }

  // 1.7 сек показа → анимация
  setTimeout(_runSplashAnimate, 1700);
})();

/* ═══════════════════════════════════════════════════════════════════
   IP CITY DETECTION
═══════════════════════════════════════════════════════════════════ */
// Кэш IP-детекции в сессии
window._ipCityCache = null;

async function detectCityByIP() {
  if (window._ipCityCache) return window._ipCityCache;
  // Браузерные прямые запросы к публичным IP API режутся CORS/403.
  // До отдельного server-side proxy не шумим в консоли и тихо уходим в ручной выбор города.
  return null;
}

// Нормализует город из IP к ближайшему из нашего списка
function normalizeCityFromIP(ipCity) {
  if (!ipCity) return '';
  const lower = ipCity.toLowerCase();
  // Точное совпадение
  const exact = ENTRY_CITY_OPTIONS.find(c => c.toLowerCase() === lower);
  if (exact) return exact;
  // Частичное (начало слова)
  const partial = ENTRY_CITY_OPTIONS.find(c => lower.startsWith(c.toLowerCase().slice(0,5)) || c.toLowerCase().startsWith(lower.slice(0,5)));
  return partial || '';
}

/* ═══════════════════════════════════════════════════════════════════
   ONBOARDING v2 — мост к модулю js/onb2.js
═══════════════════════════════════════════════════════════════════ */
function showOnboarding(user, onDone, opts) {
  if (document.getElementById('onb2-overlay')) return;
  if (window.App?.getState?.()?.user?.phone) return;
  if (window.OnboardingV2?.show) {
    return window.OnboardingV2.show(user, onDone, opts || {});
  }
  window._onb2Done = onDone;
}
window.showOnboarding = showOnboarding;

function _showOnboarding2(opts) {
  if (window.OnboardingV2?.render) {
    return window.OnboardingV2.render(opts || {});
  }
}
window._showOnboarding2 = _showOnboarding2;

/* ═══════════════════════════════════════════════════════════════════
   PROFILE SETUP MODAL — Шаг 5: первичная настройка по роли
═══════════════════════════════════════════════════════════════════ */
function showProfileSetupModal(role, user) {
  if (!role || !user?.phone) return;
  // Не показываем повторно если профиль уже настроен (есть имя и город)
  const existingName = String(user.name || '').trim();
  const existingCity = String(user.city || '').trim();
  if (existingName && existingName !== 'Клиент' && existingName !== 'Мастер' && existingCity) return;

  document.getElementById('profile-setup-overlay')?.remove();
  const cityOptions = ENTRY_CITY_OPTIONS.map(c =>
    '<option value="'+esc(c)+'"'+(existingCity===c?' selected':'')+'>'+esc(c)+'</option>'
  ).join('');

  const FIELDS = {
    client: [
      {id:'ps-name',  label:'Ваше имя',         type:'text',   ph:'Алексей Иванов', key:'name'},
      {id:'ps-car',   label:'Автомобиль',        type:'text',   ph:'Toyota Camry 2020', key:'car'},
      {id:'ps-city',  label:'Город',             type:'select', key:'city', opts: cityOptions},
    ],
    master: [
      {id:'ps-name',  label:'Имя / псевдоним',   type:'text',   ph:'Артём Сергеев', key:'name'},
      {id:'ps-spec',  label:'Специализация',      type:'text',   ph:'Генераторы, стартеры, электрика', key:'spec'},
      {id:'ps-city',  label:'Город базы',         type:'select', key:'city', opts: cityOptions},
      {id:'ps-mode',  label:'Формат работы',      type:'select', key:'workMode',
       opts:'<option value="shop">🏭 Свой бокс</option><option value="mobile">▱ Выезд к клиенту</option><option value="hybrid">🔄 Совмещённый</option>'},
      {id:'ps-radius',label:'Радиус выезда (км)', type:'number', ph:'30', key:'serviceRadius'},
    ],
    sto: [
      {id:'ps-name',  label:'Название СТО',       type:'text',   ph:'АвтоМастер', key:'name'},
      {id:'ps-city',  label:'Город',              type:'select', key:'city', opts: cityOptions},
      {id:'ps-addr',  label:'Адрес',              type:'text',   ph:'ул. Гоголя 36А', key:'address'},
      {id:'ps-phone', label:'Контактный телефон', type:'tel',    ph:'+7 700 000 00 00', key:'contactPhone'},
      {id:'ps-hours', label:'Режим работы',       type:'text',   ph:'Пн–Сб 9:00–19:00', key:'workHours'},
    ],
  };
  const fields = FIELDS[normalizeEntryRole(role)] || FIELDS.client;
  const rolesLabel = {client:'клиента',master:'мастера',sto:'автосервиса'};

  const roleKey = normalizeEntryRole(role);
  const roleIcon = roleKey === 'master' ? '⌁' : (roleKey === 'sto' ? '🏭' : '○');
  const roleTitle = rolesLabel[roleKey] || 'профиля';
  const fieldsHtml = fields.map(f => {
    const el = f.type === 'select'
      ? '<select id="'+f.id+'" class="pf-input profile-setup-input"><option value="">Выберите…</option>'+f.opts+'</select>'
      : '<input id="'+f.id+'" class="pf-input profile-setup-input" type="'+f.type+'" placeholder="'+esc(f.ph||'')+'"'
        + (f.key === 'name' && existingName && existingName !== 'Клиент' && existingName !== 'Мастер' ? ' value="'+esc(existingName)+'"' : '')
        + '>';
    return '<div class="profile-setup-field">'
      +'<label class="profile-setup-label" for="'+esc(f.id)+'">'+esc(f.label)+'</label>'
      +el+'</div>';
  }).join('');

  const el = document.createElement('div');
  el.id = 'profile-setup-overlay';
  el.className = 'profile-setup-overlay open';
  el.setAttribute('role','dialog');
  el.setAttribute('aria-modal','true');
  el.setAttribute('aria-label','Настройка профиля');

  el.innerHTML = '<div class="profile-setup-panel" role="document">'
    +'<div class="profile-setup-drag" aria-hidden="true"></div>'
    +'<div class="profile-setup-head">'
      +'<div class="profile-setup-icon">'+roleIcon+'</div>'
      +'<div class="profile-setup-titlebox">'
        +'<div class="profile-setup-kicker">Шаг последний</div>'
        +'<div class="profile-setup-title">Настройка профиля '+esc(roleTitle)+'</div>'
        +'<div class="profile-setup-subtitle">Базовые данные для заявок, откликов и связи. Потом можно изменить в кабинете.</div>'
      +'</div>'
      +'<button class="profile-setup-close" type="button" aria-label="Закрыть" onclick="document.getElementById(&quot;profile-setup-overlay&quot;)?.remove()">✕</button>'
    +'</div>'
    +'<div class="profile-setup-body">'
      +'<div class="profile-setup-grid">'+fieldsHtml+'</div>'
    +'</div>'
    +'<div class="profile-setup-footer">'
      +'<button class="btn btn-outline profile-setup-skip" type="button" onclick="document.getElementById(&quot;profile-setup-overlay&quot;)?.remove()">Пропустить</button>'
      +'<button class="btn btn-primary profile-setup-save" type="button" onclick="window._saveProfileSetup(&quot;'+esc(role)+'&quot;)">💾 Сохранить профиль</button>'
    +'</div>'
    +'</div>';

  document.body.appendChild(el);
  requestAnimationFrame(() => { el.classList.add('is-visible'); });
}
window.showProfileSetupModal = showProfileSetupModal;

