async function _masterSavePostCore(masterId, postId, status) {
  const typeBtn = document.querySelector('#post-type-btns [data-type][style*="var(--orange)"]');
  const type    = typeBtn?.dataset?.type || 'case';
  const title   = document.getElementById('pe-title')?.value?.trim() || '';
  const preview = document.getElementById('pe-preview')?.value?.trim() || '';
  const body    = document.getElementById('pe-body')?.value?.trim() || '';
  const tags    = document.getElementById('pe-tags')?.value?.trim() || '';
  if (!title && !body) { window._showToast?.('Заполните заголовок или текст', 'error'); return; }
  try {
    await window.DB?.MasterPosts?.save?.({
      id: postId || undefined, masterId, master_id: masterId,
      type, title, preview, body, tags, status,
      publishedAt: status === 'published' ? new Date().toISOString() : undefined,
    });
    document.getElementById('master-post-editor-overlay')?.remove();
    window._showToast?.(status === 'published' ? '🚀 Опубликовано!' : '💾 Черновик сохранён');
    if (window._karetaPage === 'master') setTimeout(() => masterSwitchSubtab('cabinet','posts'), 200);
  } catch(e) {
    window._showToast?.(e?.message || 'Ошибка сохранения', 'error');
  }
}

