window.__onboardingFeatureGo = window.__onboardingFeatureGo || function(trigger, intent){
  try {
    var card = trigger && trigger.closest ? trigger.closest('.onb-card') : null;
    if (card) card.classList.remove('open');
    var u = window._appState && window._appState.user;
    var act = function(){
      try {
        if (!u) {
          // Гость: интенты, требующие авторизации — показываем форму входа
          var authRequired = ['myorders','messages','cabinet','services'];
          if (authRequired.indexOf(intent) !== -1) {
            window.App && window.App.showAuth && window.App.showAuth(intent);
          } else {
            window.App && ((intent==='services' && window.App.startServiceBooking) ? window.App.startServiceBooking() : (window.App.go && window.App.go(intent)));
          }
        } else {
          // Авторизован: прямой переход
          window.App && ((intent==='services' && window.App.startServiceBooking) ? window.App.startServiceBooking() : (window.App.go && window.App.go(intent)));
        }
      } catch(_e){}
    };
    setTimeout(function(){
      try { if (card) card.remove(); } catch(_e) {}
      act();
    }, 300);
  } catch(_e) {
    try { window.App && ((intent==='services' && window.App.startServiceBooking) ? window.App.startServiceBooking() : (window.App.go && window.App.go(intent))); } catch(__e) {}
  }
};

