/* stable cleanup branch: single helper for tier-2 navigation.
   It keeps tab state, pane visibility and URL sync in one place instead of scattered DOM switching. */
(function(){
  if (window.__KARETA_NAVIGATION_CONTRACT_STABLE__) return;
  window.__KARETA_NAVIGATION_CONTRACT_STABLE__ = true;
  function clean(value){ return String(value || '').trim().replace(/[^a-zA-Z0-9_-]/g, ''); }
  function cleanRoute(value){ return String(value || '').trim().replace(/^#/, '').replace(/[^a-zA-Z0-9_:-]/g, ''); }
  function currentRouteOwner(fallback){
    try { return clean((window._appState && window._appState.page) || window._karetaPage || fallback || 'home') || 'home'; }
    catch(_e){ return clean(fallback || 'home') || 'home'; }
  }
  function setUrl(route, source){
    var next = cleanRoute(route);
    if (!next) return false;
    try {
      if (window.App && typeof App.go === 'function') { App.go(next); return true; }
    } catch(_e) {}
    try { if (location.hash !== '#' + next) history.pushState({source:source||'nav-contract'}, '', '#' + next); return true; } catch(_e2) {}
    try { location.hash = '#' + next; return true; } catch(_e3) {}
    return false;
  }
  function applySubtab(scope,key,opts){
    var scopeKey = clean(scope);
    var tabKey = clean(key);
    if (!scopeKey || !tabKey) return false;
    var root = document.querySelector('[data-subtabs="' + scopeKey + '"]');
    if (!root) return false;
    root.setAttribute('data-nav-level','secondary');
    root.classList.add('k-nav-tier','k-nav-tier--secondary');
    root.querySelectorAll('[data-subtab]').forEach(function(btn){
      var active = btn.dataset.subtab === tabKey;
      btn.classList.toggle('active', active);
      btn.classList.toggle('is-active', active);
      btn.classList.toggle('btn-primary', active);
      btn.classList.toggle('btn-outline', !active);
      btn.setAttribute('aria-current', active ? 'page' : 'false');
      btn.setAttribute('aria-selected', active ? 'true' : 'false');
      btn.dataset.current = active ? '1' : '0';
    });
    document.querySelectorAll('[data-subpane-scope="' + scopeKey + '"]').forEach(function(pane){
      var active = pane.dataset.subpane === tabKey;
      pane.hidden = !active;
      pane.setAttribute('data-subpane-active', active ? '1' : '0');
      pane.classList.toggle('is-active', active);
      pane.classList.toggle('is-hidden', !active);
      pane.style.display = active ? '' : 'none';
    });
    try { window.syncChromeGeometry && window.syncChromeGeometry(); } catch(_e) {}
    var push = !opts || opts.push !== false;
    if (push) {
      var owner = currentRouteOwner(opts && opts.routeOwner);
      if (owner === 'master' || scopeKey === 'work' || scopeKey === 'shop' || scopeKey === 'cabinet') {
        setUrl('master:' + scopeKey + ':' + tabKey, 'tier2-nav');
      }
    }
    return true;
  }
  document.addEventListener('click', function(e){
    var btn = e.target && e.target.closest && e.target.closest('[data-kroute],[data-route-go],[data-inline-route]');
    if (!btn || btn.closest('[data-nav-contract-ignore]')) return;
    var route = btn.getAttribute('data-kroute') || btn.getAttribute('data-route-go') || btn.getAttribute('data-inline-route');
    if (!route || btn.getAttribute('href')) return;
    e.preventDefault();
    setUrl(route, 'delegated-route');
  }, true);
  window.KaretaNavigationContract = Object.assign(window.KaretaNavigationContract || {}, { applySubtab:applySubtab, go:setUrl, version:'stable' });
})();
