  function designStabilityApply(routeName, canonicalHash){
    try {
      const appRoot = document.getElementById('app');
      const route = String(routeName || window._karetaPage || 'home');
      const hash = String(canonicalHash || location.hash || '#home').replace(/^#/, '') || 'home';
      document.documentElement.setAttribute('data-design-stability', 'active');
      document.body.setAttribute('data-design-route', route);
      document.body.setAttribute('data-design-hash', hash.split(':')[0] || route);
      if (appRoot) {
        appRoot.setAttribute('data-design-stability', 'active');
        appRoot.setAttribute('data-design-route', route);
      }

      const bottomNav = document.querySelector('#bottom-nav,.bottom-nav');
      const navHeight = bottomNav ? Math.ceil(bottomNav.getBoundingClientRect().height || 0) : 0;
      document.documentElement.style.setProperty('--app-bottom-nav-height', String(navHeight || 0) + 'px');

      const topHead = document.querySelector('.services-home-head,.account-top-head,.k-main-head,.services-app-nav-head');
      const headHeight = topHead ? Math.ceil(topHead.getBoundingClientRect().height || 0) : 0;
      document.documentElement.style.setProperty('--app-top-head-height', String(headHeight || 0) + 'px');

      document.querySelectorAll('img:not([width]):not([height])').forEach(img => {
        img.setAttribute('loading', img.getAttribute('loading') || 'lazy');
        img.setAttribute('decoding', img.getAttribute('decoding') || 'async');
      });

      document.querySelectorAll('.services-quick-card,.services-category-card,.parts-product-card,.part-card-v2,.services-app-tile,.home-feature-card,.master-card,.order-card,.cab-card').forEach(card => {
        card.setAttribute('data-stable-card', '1');
      });

      window.KaretaDesignStability = Object.assign(window.KaretaDesignStability || {}, {
        route,
        hash,
        bottomNavHeight: navHeight,
        topHeadHeight: headHeight,
        activePages: document.querySelectorAll('#app > .page.active, #app > .services-app-page.active').length,
        at: Date.now(),
      });
      return true;
    } catch (_e) {
      return false;
    }
  }

  function designStabilityLock(routeName, canonicalHash){
    try {
      const appRoot = document.getElementById('app');
      const previous = appRoot ? Math.ceil(appRoot.getBoundingClientRect().height || 0) : 0;
      if (appRoot && previous > 0) {
        appRoot.style.setProperty('--route-previous-height', previous + 'px');
      }
      document.documentElement.setAttribute('data-route-transition', '1');
      document.body.setAttribute('data-route-transition', '1');
      designStabilityApply(routeName, canonicalHash);
      return true;
    } catch (_e) {
      return false;
    }
  }

  function designStabilityUnlock(){
    try {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          try {
            designStabilityApply(window._karetaPage || 'home', location.hash || '#home');
            document.documentElement.removeAttribute('data-route-transition');
            document.body.removeAttribute('data-route-transition');
          } catch (_e) {}
        });
      });
      return true;
    } catch (_e) {
      return false;
    }
  }

  function installDesignStabilityMonitor(){
    if (window.__karetaDesignStabilityInstalled) return;
    window.__karetaDesignStabilityInstalled = true;

    try {
      if ('PerformanceObserver' in window) {
        const shifts = [];
        const observer = new PerformanceObserver(list => {
          list.getEntries().forEach(entry => {
            if (!entry.hadRecentInput && entry.value) {
              shifts.push({
                value: Number(entry.value || 0),
                sources: Array.from(entry.sources || []).slice(0, 4).map(src => {
                  const node = src.node;
                  if (!node || !node.tagName) return '';
                  const id = node.id ? ('#' + node.id) : '';
                  const cls = node.className && typeof node.className === 'string'
                    ? '.' + node.className.trim().split(/\s+/).slice(0, 3).join('.')
                    : '';
                  return node.tagName.toLowerCase() + id + cls;
                }).filter(Boolean),
                at: Date.now(),
              });
              while (shifts.length > 30) shifts.shift();
              window.KaretaLayoutShiftAudit = {
                total: Number(shifts.reduce((sum, item) => sum + Number(item.value || 0), 0).toFixed(4)),
                count: shifts.length,
                last: shifts[shifts.length - 1] || null,
                items: shifts,
                at: Date.now(),
              };
            }
          });
        });
        observer.observe({ type:'layout-shift', buffered:true });
      }
    } catch (_e) {}

    window.addEventListener('resize', () => {
      clearTimeout(window.__karetaDesignStabilityResizeTimer);
      window.__karetaDesignStabilityResizeTimer = setTimeout(() => designStabilityApply(window._karetaPage || 'home', location.hash || '#home'), 120);
    }, { passive:true });

    window.addEventListener('load', () => setTimeout(() => designStabilityApply(window._karetaPage || 'home', location.hash || '#home'), 180));
    document.addEventListener('DOMContentLoaded', () => setTimeout(() => designStabilityApply(window._karetaPage || 'home', location.hash || '#home'), 180));
  }

  try {
    installDesignStabilityMonitor();
    window.KaretaDesignStability = Object.assign(window.KaretaDesignStability || {}, {
      apply: designStabilityApply,
      lock: designStabilityLock,
      unlock: designStabilityUnlock,
    });
  } catch (_e) {}


  function collectDesignQualityAudit(){
    const viewportWidth = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
    const viewportHeight = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
    const appRoot = document.getElementById('app');

    const overflowElements = [];
    document.querySelectorAll('body *').forEach(el => {
      try {
        const rect = el.getBoundingClientRect();
        if (!rect || rect.width <= 0 || rect.height <= 0) return;
        const overflowRight = rect.right - viewportWidth;
        const overflowLeft = -rect.left;
        if (overflowRight > 2 || overflowLeft > 2) {
          const tag = el.tagName ? el.tagName.toLowerCase() : 'node';
          const id = el.id ? ('#' + el.id) : '';
          const cls = typeof el.className === 'string' && el.className.trim()
            ? '.' + el.className.trim().split(/\s+/).slice(0, 4).join('.')
            : '';
          overflowElements.push({
            selector: tag + id + cls,
            left: Math.round(rect.left),
            right: Math.round(rect.right),
            width: Math.round(rect.width),
            overflowLeft: Math.max(0, Math.round(overflowLeft)),
            overflowRight: Math.max(0, Math.round(overflowRight)),
          });
        }
      } catch (_e) {}
    });

    const visibleBlocks = Array.from(document.querySelectorAll(
      '#app > .page.active, #app > .services-app-page.active, .services-quick, .services-category, .parts-catalog, .masters-page, .messages-page, .account-top-shell'
    )).filter(el => {
      try {
        const rect = el.getBoundingClientRect();
        const style = getComputedStyle(el);
        return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
      } catch (_e) {
        return false;
      }
    });

    const badWritingMode = [];
    document.querySelectorAll('#app *').forEach(el => {
      try {
        const style = getComputedStyle(el);
        if (style.writingMode && style.writingMode !== 'horizontal-tb') {
          const tag = el.tagName ? el.tagName.toLowerCase() : 'node';
          const id = el.id ? ('#' + el.id) : '';
          const cls = typeof el.className === 'string' && el.className.trim()
            ? '.' + el.className.trim().split(/\s+/).slice(0, 3).join('.')
            : '';
          badWritingMode.push({ selector: tag + id + cls, writingMode: style.writingMode });
        }
      } catch (_e) {}
    });

    const smallTapTargets = [];
    document.querySelectorAll('#app button, #app a, #bottom-nav button, #bottom-nav a').forEach(el => {
      try {
        const rect = el.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0 && (rect.width < 34 || rect.height < 34)) {
          const tag = el.tagName ? el.tagName.toLowerCase() : 'node';
          const id = el.id ? ('#' + el.id) : '';
          const cls = typeof el.className === 'string' && el.className.trim()
            ? '.' + el.className.trim().split(/\s+/).slice(0, 3).join('.')
            : '';
          smallTapTargets.push({
            selector: tag + id + cls,
            width: Math.round(rect.width),
            height: Math.round(rect.height),
          });
        }
      } catch (_e) {}
    });

    const duplicateFixedNav = {
      bottomNav: document.querySelectorAll('#bottom-nav,.bottom-nav').length,
      topHead: document.querySelectorAll('.services-home-head,.account-top-head,.k-main-head').length,
    };

    const checks = {
      appRoot: !!appRoot,
      noHorizontalOverflow: overflowElements.length === 0,
      noBadWritingMode: badWritingMode.length === 0,
      tapTargetsAcceptable: smallTapTargets.length === 0,
      visibleBlocksStable: visibleBlocks.length > 0,
      bottomNavSingle: duplicateFixedNav.bottomNav <= 1,
    };

    const audit = {
      ok: Object.values(checks).every(Boolean),
      checks,
      viewport: { width: viewportWidth, height: viewportHeight },
      route: String(location.hash || '#home'),
      overflowElements: overflowElements.slice(0, 30),
      badWritingMode: badWritingMode.slice(0, 30),
      smallTapTargets: smallTapTargets.slice(0, 30),
      duplicateFixedNav,
      visibleBlocks: visibleBlocks.length,
      layoutShift: window.KaretaLayoutShiftAudit || null,
      at: Date.now(),
    };

    window.KaretaDesignQualityAudit = audit;
    return audit;
  }

