  function collectDesignPolishAudit(){
    const appRoot = document.getElementById('app');
    const controls = Array.from(document.querySelectorAll('#app [data-control-polish]'));
    const cards = Array.from(document.querySelectorAll('#app [data-card-polish]'));
    const floating = Array.from(document.querySelectorAll('#app [data-layer-polish]'));
    const badControls = controls.filter(el => {
      try {
        const rect = el.getBoundingClientRect();
        const style = getComputedStyle(el);
        return rect.width > 0 && rect.height > 0 && (rect.height < 34 || style.visibility === 'hidden');
      } catch (_e) {
        return false;
      }
    }).slice(0, 20).map(el => {
      const tag = el.tagName ? el.tagName.toLowerCase() : 'node';
      const cls = typeof el.className === 'string' && el.className.trim() ? '.' + el.className.trim().split(/\s+/).slice(0, 3).join('.') : '';
      return tag + cls;
    });

    const audit = {
      ok: !!appRoot && badControls.length === 0,
      appRoot: !!appRoot,
      controls: controls.length,
      cards: cards.length,
      floatingLayers: floating.length,
      badControls,
      route: String(location.hash || '#home'),
      at: Date.now(),
    };
    window.KaretaDesignPolishAudit = audit;
    return audit;
  }

