  function collectDesignSystemAudit(){
    const appRoot = document.getElementById('app');
    const route = String(window._karetaPage || 'home');
    const containers = document.querySelectorAll('#app [data-ui-container="stable"]').length;
    const surfaces = document.querySelectorAll('#app [data-ui-surface="stable"]').length;
    const controls = document.querySelectorAll('#app [data-ui-control]').length;
    const visiblePages = Array.from(document.querySelectorAll('#app > .page, #app > .services-app-page')).filter(el => {
      try {
        const rect = el.getBoundingClientRect();
        const style = getComputedStyle(el);
        return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
      } catch (_e) {
        return false;
      }
    }).length;

    const rootWidth = appRoot ? Math.round(appRoot.getBoundingClientRect().width || 0) : 0;
    const viewportWidth = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
    const overflow = rootWidth > viewportWidth + 2;

    const audit = {
      ok: !!appRoot && visiblePages <= 1 && !overflow,
      route,
      appRoot: !!appRoot,
      visiblePages,
      rootWidth,
      viewportWidth,
      overflow,
      containers,
      surfaces,
      controls,
      designQuality: window.KaretaDesignQualityAudit || null,
      designPolish: window.KaretaDesignPolishAudit || null,
      layoutShift: window.KaretaLayoutShiftAudit || null,
      at: Date.now(),
    };

    window.KaretaDesignSystemAudit = audit;
    return audit;
  }

