    '.services-grid[data-card-grid="1"]',
    '.services-cards[data-card-grid="1"]',
    '.services-catalog[data-card-grid="1"]',
    '.parts-grid[data-card-grid="1"]',
    '.parts-products[data-card-grid="1"]',
    '.parts-catalog-grid[data-card-grid="1"]',
    '.products-grid[data-card-grid="1"]',
    '.masters-grid[data-card-grid="1"]',
